import { useState, useEffect, useContext, useRef } from 'react'
import { DataContext } from './context/DataContext'
import { db } from './services/firebaseConfig'
import { collection, onSnapshot } from 'firebase/firestore'
import {
  Menu, X, Truck, MapPin, FileText, Droplet, Wrench,
  CreditCard, PieChart, Calendar, Settings, Shield, LogOut, Bell, AlertTriangle, Sun, Moon, Waves, ChevronDown, Building2, Server
} from 'lucide-react'
import Dashboard from './components/Dashboard'
import Trips from './components/Trips'
import Invoices from './components/Invoices'
import Fuel from './components/Fuel'
import Maintenance from './components/Maintenance'
import Payments from './components/Payments'
import SettingsPage from './components/Settings'
import Login from './components/Login'
import AdminLog from './components/AdminLog'
import Detaylar from './components/Detaylar'
import CompanyAdmin from './components/CompanyAdmin'
import SuperAdmin from './components/SuperAdmin'
import { useCompany } from './context/CompanyContext'
import { useTruck } from './context/TruckContext'

function App() {
  const [activeTab, setActiveTab] = useState(() => {
    const savedTab = localStorage.getItem('tir_active_tab')
    if (savedTab) return savedTab;
    return 'dashboard';
  })
  const [isMenuOpen, setIsMenuOpen] = useState(window.innerWidth >= 768)
  const [isMobile, setIsMobile] = useState(window.innerWidth < 768)
  const [theme, setTheme] = useState(() => localStorage.getItem('tir_theme') || 'dark')

  useEffect(() => {
    localStorage.setItem('tir_active_tab', activeTab)
  }, [activeTab])

  const toggleTheme = () => {
    const next = theme === 'dark' ? 'light' : 'dark';
    setTheme(next);
    localStorage.setItem('tir_theme', next);
    const meta = document.getElementById('theme-color-meta');
    if (meta) meta.setAttribute('content', next === 'light' ? '#f5f3ef' : '#0f172a');
  }

  const { currentSession, logoutSession, isDataLoading, docs, penalties } = useContext(DataContext)
  const { activeCompanyId, setActiveCompanyId, companyData, companies } = useCompany()
  const { activeTruckId, setActiveTruckId, activeTruckData, trucks } = useTruck()
  const currentUser = currentSession;
  const userRole = currentUser?.username === 'kenan' ? 'super_admin' : String(currentUser?.role || 'user').toLowerCase();

  const [showCompanyDrop, setShowCompanyDrop] = useState(false);
  const [showTruckDrop, setShowTruckDrop] = useState(false);
  const companyDropRef = useRef(null);
  const truckDropRef = useRef(null);

  const DEFAULT_PIC = '/tir-clear.png?v=8'
  const picKey = `tir_profile_pic_${currentUser?.username || 'default'}`;
  const [profilePic, setProfilePic] = useState(() => {
    const pic = localStorage.getItem(picKey);
    if (pic && (pic.startsWith('/tir-icon') || pic.startsWith('/unnamed') || pic.startsWith('/tir-clear'))) {
      localStorage.removeItem(picKey);
      return DEFAULT_PIC;
    }
    return pic || DEFAULT_PIC;
  })

  useEffect(() => {
    const handler = (e) => {
      if (companyDropRef.current && !companyDropRef.current.contains(e.target)) setShowCompanyDrop(false);
      if (truckDropRef.current && !truckDropRef.current.contains(e.target)) setShowTruckDrop(false);
    };
    document.addEventListener('mousedown', handler);
    return () => document.removeEventListener('mousedown', handler);
  }, []);

  useEffect(() => {
    const handleResize = () => setIsMobile(window.innerWidth < 768)
    window.addEventListener('resize', handleResize)

    const handleStorageChange = () => {
      const pic = localStorage.getItem(picKey) || DEFAULT_PIC;
      setProfilePic(pic);
      // NOT: favicon/apple-touch-icon güncellenmez
    }
    window.addEventListener('storage', handleStorageChange)
    window.addEventListener('tir_profile_pic_updated', handleStorageChange)

    return () => {
      window.removeEventListener('resize', handleResize)
      window.removeEventListener('storage', handleStorageChange)
      window.removeEventListener('tir_profile_pic_updated', handleStorageChange)
    }
  }, [])

  // Mobilde sidebar açıkken tıklanabilir sayfa alanında kapansın
  const handleOverlayClick = () => {
    if (isMobile) setIsMenuOpen(false)
  }

  const handleLogout = () => {
    logoutSession()
    localStorage.removeItem('tir_active_tab')
    setIsMenuOpen(false)
  }

  // Belge uyarısı hesapla (Detaylar sekmesi badge) - DataContext'ten gelen verilerle
  const DOC_WARNINGS = { bandrol: 30, inspection: 45, trailerInspection: 45, insurance: 30, k1: 60, l1: 60, srcBelgesi: 60, odp: 30 }

  const urgentDocsCount = Object.entries(DOC_WARNINGS).filter(([k, days]) => {
    const d = docs && docs[k]?.date ? docs[k].date : null
    if (!d) return false
    const diff = Math.ceil((new Date(d) - new Date()) / 86400000)
    return diff <= days
  }).length

  const unpaidPenaltiesCount = penalties ? penalties.filter(p => !p.paid).length : 0;
  const notifCountRaw = urgentDocsCount + unpaidPenaltiesCount;

  // Sync badges across components via custom event and storage updates
  const [readDocsNotif, setReadDocsNotif] = useState(() => {
    try { return JSON.parse(localStorage.getItem('tir_read_docs_notif')) || {}; } catch { return {}; }
  });
  const [readPenaltiesNotif, setReadPenaltiesNotif] = useState(() => {
    try { return JSON.parse(localStorage.getItem('tir_read_penalties_notif')) || []; } catch { return []; }
  });

  useEffect(() => {
    const handleStorage = () => {
      try {
        setReadDocsNotif(JSON.parse(localStorage.getItem('tir_read_docs_notif')) || {});
        setReadPenaltiesNotif(JSON.parse(localStorage.getItem('tir_read_penalties_notif')) || []);
      } catch { }
    };
    window.addEventListener('storage', handleStorage);
    window.addEventListener('tir_notif_updated', handleStorage);
    return () => {
      window.removeEventListener('storage', handleStorage);
      window.removeEventListener('tir_notif_updated', handleStorage);
    };
  }, []);

  const unreadDocsCount = Object.entries(DOC_WARNINGS).filter(([k, days]) => {
    const d = docs && docs[k]?.date ? docs[k].date : null;
    if (!d) return false;
    const diff = Math.ceil((new Date(d) - new Date()) / 86400000);
    return diff <= days && readDocsNotif[k] !== d;
  }).length;

  const unpaidPenalties = penalties ? penalties.filter(p => !p.paid) : [];
  const unreadPenaltiesCount = unpaidPenalties.filter(p => !readPenaltiesNotif.includes(p.id)).length;

  const notifCount = unreadDocsCount + unreadPenaltiesCount;

  const menuItems = [
    { id: 'dashboard', label: 'Özet', icon: <PieChart size={20} /> },
    { id: 'trips', label: 'Seferler', icon: <MapPin size={20} /> },
    { id: 'fuel', label: 'Mazot Fişleri', icon: <Droplet size={20} /> },
    { id: 'maintenance', label: 'Araç Bakım', icon: <Wrench size={20} /> },
    { id: 'detaylar', label: 'Ceza & Belgeler', icon: <AlertTriangle size={20} />, badge: notifCount },
    { id: 'invoices', label: 'Fatura Durumu', icon: <FileText size={20} /> },
    { id: 'payments', label: 'Ödeme Takibi', icon: <CreditCard size={20} /> },
    { id: 'company_admin', label: 'Şirket Yönetimi', icon: <Building2 size={20} /> },
    { id: 'super_admin', label: 'SaaS Yönetimi', icon: <Server size={20} /> },
    { id: 'adminlog', label: 'Admin Logu', icon: <Shield size={20} /> },
  ]

  useEffect(() => {
    if (userRole === 'super_admin') {
      const unsub = onSnapshot(collection(db, 'companies'), (snapshot) => {
        setAllCompanies(snapshot.docs.map(doc => doc.data()));
      });
      return () => unsub();
    }
  }, [userRole]);



  const filteredMenuItems = menuItems.filter(item => {
    if (userRole === 'super_admin') return true;

    if (userRole === 'company_admin') {
      return item.id !== 'super_admin';
    }

    // Default 'şoför' (Sürücü) -> Sadece operasyonel sekmeleri görür
    return !['adminlog', 'super_admin', 'company_admin'].includes(item.id);
  })

  // Login ekranı
  if (!currentUser) {
    return <Login />
  }

  if (isDataLoading) {
    return (
      <div className="min-h-screen flex flex-col items-center justify-center gap-4" style={{ backgroundColor: 'var(--bg-base)' }}>
        <div className="w-10 h-10 border-4 border-orange-500/30 border-t-orange-500 rounded-full animate-spin" />
        <p className="text-slate-400 text-sm font-medium">Veriler yükleniyor...</p>
      </div>
    );
  }

  // Askıya Alma (Suspend) Kontrolü
  if (companyData?.status === 'suspended' && userRole !== 'super_admin') {
    return (
      <div className="min-h-screen bg-slate-950 flex flex-col items-center justify-center p-6 text-center">
        <div className="bg-red-500/10 p-4 rounded-full mb-6">
          <AlertTriangle size={48} className="text-red-500" />
        </div>
        <h1 className="text-3xl font-bold text-slate-100 mb-2">Erişim Engellendi</h1>
        <p className="text-slate-400 max-w-sm mb-8">
          <b>{companyData.name}</b> sistem lisansı askıya alınmıştır. Detaylı bilgi veya sistemi tekrar aktif etmek için lütfen sistem yöneticinizle iletişime geçin.
        </p>
        <button onClick={logoutSession} className="flex items-center gap-2 bg-slate-800 hover:bg-slate-700 text-slate-200 px-6 py-3 rounded-lg font-medium transition-colors">
          <LogOut size={18} />
          Güvenli Çıkış Yap
        </button>
      </div>
    );
  }

  // Masaüstünde sidebar açıkken içerik kayar, mobilde overlay açılır
  const mainPaddingLeft = isMenuOpen && !isMobile ? 'pl-72' : 'pl-0'

  return (
    <div className={`min-h-screen font-sans relative overflow-x-clip ${theme === 'light' ? 'light' : ''
      }`} style={{ backgroundColor: 'var(--bg-base)', color: 'var(--text-primary)' }}>

      {/* Mobil overlay */}
      {isMenuOpen && isMobile && (
        <div className="fixed inset-0 bg-black/70 backdrop-blur-sm z-40" onClick={handleOverlayClick} />
      )}

      {/* Sidebar - Avant Garde Minimalist Layout */}
      <aside className={`fixed top-0 left-0 h-full w-72 z-50 flex flex-col transition-transform duration-500 ease-in-out ${isMenuOpen ? 'translate-x-0' : '-translate-x-full'}`}
        style={{
          background: 'var(--bg-sidebar)',
          borderRight: `1px solid var(--border-color)`,
        }}>
        {/* Header - Profile Area (Company & Truck Switcher) */}
        <div className="px-5 pt-6 pb-4 flex flex-col gap-3">

          {userRole === 'super_admin' && (companies || []).length > 1 && (
            <div ref={companyDropRef} className="relative">
              <button
                onClick={() => setShowCompanyDrop(v => !v)}
                className="w-full bg-indigo-500/10 rounded-xl p-3 border border-indigo-500/30 hover:border-indigo-500/60 transition-all shadow-inner shadow-indigo-500/5 flex flex-col text-left"
              >
                <span className="text-[10px] text-indigo-400 font-bold tracking-widest uppercase mb-1">Müşteri Seçimi (SaaS)</span>
                <div className="flex items-center justify-between">
                  <div className="flex items-center gap-2">
                    <Building2 size={15} className="text-indigo-400 flex-shrink-0" />
                    <span className="text-sm font-bold text-slate-100 truncate">{(companies || []).find(c => c.id === activeCompanyId)?.name || 'Seç...'}</span>
                  </div>
                  <ChevronDown size={14} className={`text-indigo-400/60 transition-transform duration-200 ${showCompanyDrop ? 'rotate-180' : ''}`} />
                </div>
              </button>
              {showCompanyDrop && (
                <div className="absolute left-0 right-0 top-full mt-1.5 z-50 bg-slate-900 border border-indigo-500/30 rounded-xl overflow-hidden shadow-2xl shadow-black/50 backdrop-blur-xl">
                  {(companies || []).map(c => (
                    <button key={c.id} onClick={() => { setActiveCompanyId(c.id); localStorage.setItem('tir_current_company', c.id); setShowCompanyDrop(false); }}
                      className={`w-full flex items-center gap-2.5 px-3 py-2.5 text-sm transition-colors text-left ${activeCompanyId === c.id ? 'bg-indigo-500/20 text-indigo-300 font-semibold' : 'text-slate-300 hover:bg-white/5 hover:text-white'}`}>
                      <Building2 size={13} className={activeCompanyId === c.id ? 'text-indigo-400' : 'text-slate-500'} />
                      {c.name}
                      {activeCompanyId === c.id && <span className="ml-auto text-[9px] bg-indigo-500/20 text-indigo-400 px-1.5 py-0.5 rounded-full font-bold">✓</span>}
                    </button>
                  ))}
                </div>
              )}
            </div>
          )}

          {trucks.length <= 1 ? (
            /* Tek tır varsa: sadece bilgi kartı, dropdown yok */
            <div className="glass-panel !bg-orange-500/10 rounded-xl p-3 border border-orange-500/50 shadow-[0_0_15px_rgba(249,115,22,0.15)] dark:shadow-none flex items-center gap-3 transition-colors duration-300">
              <div className="w-11 h-11 rounded-lg overflow-hidden glass-panel border border-orange-500/30 flex items-center justify-center flex-shrink-0 cursor-pointer" onClick={() => setActiveTab('settings')}>
                {profilePic
                  ? <img src={profilePic} alt="Profile" className="w-full h-full object-cover bg-[var(--bg-base)]" onError={() => setProfilePic(null)} />
                  : <div className="w-full h-full flex items-center justify-center"><Truck size={20} className="text-orange-500" /></div>}
              </div>
              <div className="flex-1 min-w-0">
                <p className="text-sm font-bold text-orange-500 drop-shadow-sm truncate leading-tight">
                  {trucks.length === 0 ? 'Tır Bulunmuyor' : trucks[0]?.plate}
                </p>
                <p className="text-[11px] text-orange-400 font-medium tracking-wide truncate mt-0.5">
                  {activeTruckData?.brand || companyData?.name || 'Yükleniyor...'}
                </p>
              </div>
            </div>
          ) : (
            <div ref={truckDropRef} className="relative">
              <button
                onClick={() => setShowTruckDrop(v => !v)}
                className="w-full glass-panel !bg-orange-500/10 rounded-xl p-3 border border-orange-500/50 shadow-[0_0_15px_rgba(249,115,22,0.15)] hover:shadow-[0_0_20px_rgba(249,115,22,0.25)] dark:shadow-none dark:hover:shadow-none transition-all duration-300 flex items-center gap-3 text-left"
              >
                <div className="w-11 h-11 rounded-lg overflow-hidden glass-panel border border-orange-500/30 flex items-center justify-center flex-shrink-0" onClick={(e) => { e.stopPropagation(); setActiveTab('settings'); }}>
                  {profilePic
                    ? <img src={profilePic} alt="Profile" className="w-full h-full object-cover bg-[var(--bg-base)]" onError={() => setProfilePic(null)} />
                    : <div className="w-full h-full flex items-center justify-center"><Truck size={20} className="text-orange-500" /></div>}
                </div>
                <div className="flex-1 min-w-0">
                  <p className="text-sm font-bold text-orange-500 drop-shadow-sm truncate leading-tight">
                    {trucks.length === 0 ? 'Tır Bulunmuyor' : (trucks.find(t => t.id === activeTruckId)?.plate || 'Seç...')}
                  </p>
                  <p className="text-[11px] text-orange-400 font-medium tracking-wide truncate mt-0.5">
                    {activeTruckData?.brand || companyData?.name || 'Yükleniyor...'}
                  </p>
                </div>
                <ChevronDown size={15} className={`text-orange-500 transition-transform duration-200 flex-shrink-0 ${showTruckDrop ? 'rotate-180 drop-shadow-[0_0_5px_rgba(249,115,22,0.5)] dark:drop-shadow-none' : ''}`} />
              </button>

              {showTruckDrop && trucks.length > 0 && (
                <div className="absolute left-0 right-0 top-full mt-1.5 z-50 bg-slate-900 border border-slate-700/80 rounded-xl overflow-hidden shadow-2xl shadow-black/60">
                  {trucks.map(t => (
                    <button key={t.id} onClick={() => { setActiveTruckId(t.id); setShowTruckDrop(false); }}
                      className={`w-full flex items-center gap-3 px-3 py-2.5 transition-colors text-left ${activeTruckId === t.id ? 'bg-brand-500/15 text-brand-300' : 'text-slate-300 hover:bg-white/5 hover:text-white'}`}>
                      <div className={`w-7 h-7 rounded-md flex items-center justify-center flex-shrink-0 ${activeTruckId === t.id ? 'bg-brand-500/20' : 'bg-slate-800'}`}>
                        <Truck size={13} className={activeTruckId === t.id ? 'text-brand-400' : 'text-slate-500'} />
                      </div>
                      <div className="flex-1 min-w-0">
                        <p className="text-sm font-semibold truncate">{t.plate}</p>
                        <p className="text-[10px] text-slate-500 truncate">{t.brand}</p>
                      </div>
                      {activeTruckId === t.id && <span className="text-[9px] bg-brand-500/20 text-brand-400 px-1.5 py-0.5 rounded-full font-bold">✓</span>}
                    </button>
                  ))}
                </div>
              )}
            </div>
          )}
        </div>

        {/* Nav Links */}
        <nav className="flex-1 px-4 py-6 space-y-1.5 overflow-y-auto">
          {filteredMenuItems.map((item) => (
            <button key={item.id} onClick={() => { setActiveTab(item.id); if (isMobile) setIsMenuOpen(false); }}
              className={`w-full flex items-center space-x-3 px-4 py-2.5 rounded-lg group ${activeTab === item.id
                ? 'bg-transparent text-orange-500 border border-orange-500/50 shadow-[0_0_10px_rgba(249,115,22,0.2)] dark:shadow-none font-medium'
                : 'text-[var(--text-secondary)] hover:bg-[var(--bg-panel-hover)]'}`}>
              <div className={`${activeTab === item.id ? 'scale-110 drop-shadow-[0_0_5px_rgba(249,115,22,0.5)] dark:drop-shadow-none' : 'group-hover:scale-110'}`}>
                {item.icon}
              </div>
              <span className="flex-1 text-left text-sm tracking-wide">{item.label}</span>
              {item.badge > 0 && (
                <span className="bg-red-500/10 text-red-500 text-[10px] font-bold px-2 py-0.5 rounded-full flex items-center justify-center flex-shrink-0">{item.badge}</span>
              )}
            </button>
          ))}

          <div className="pt-6 pb-2">
            <div className="h-px w-full bg-gradient-to-r from-transparent via-slate-700/30 to-transparent"></div>
          </div>

        </nav>

        {/* Footer: User & Theme */}
        <div className="p-4 px-6 flex items-center justify-between">
          <span className="text-xs text-slate-500 font-medium truncate max-w-[120px]" title={currentUser.username}>
            {currentUser.username}
          </span>
          <div className="flex items-center gap-2">
            <button onClick={toggleTheme}
              title={theme === 'dark' ? 'Aydınlık Tema' : 'Karanlık Tema'}
              className="p-2 rounded-full transition-all duration-300 hover:bg-slate-800/50 text-slate-400 hover:text-slate-200"
            >
              {theme === 'dark' ? <Sun size={14} /> : <Moon size={14} />}
            </button>
            <button onClick={handleLogout} title="Oturumu Kapat" className="p-2 rounded-full text-slate-500 hover:text-red-400 hover:bg-red-500/10 transition-all duration-300">
              <LogOut size={14} />
            </button>
          </div>
        </div>
      </aside>

      {/* Main Content */}
      <main className={`min-h-screen ${mainPaddingLeft}`}>
        <div className="flex flex-col min-h-screen w-full">

          {/* Header - Simple & Clean (sticky) */}
          <div className={`sticky top-0 z-30 px-6 py-5 flex items-center justify-between bg-[var(--bg-base)] border-b border-[var(--border-color)] transition-all duration-300 ${activeTab === 'invoices' ? 'md:hidden' : ''}`}>
            <div className="flex items-center space-x-4">
              {isMobile && (
                <button onClick={() => setIsMenuOpen(true)} className="p-2 -ml-2 text-slate-400 hover:text-slate-100 transition-colors">
                  <Menu size={24} />
                </button>
              )}
              <h2 className="text-xl font-medium tracking-tight text-slate-100">
                {menuItems.find(i => i.id === activeTab)?.label || 'Bilinmeyen'}
              </h2>
            </div>
          </div>

          {/* Content Area */}
          <div className="flex-1 p-4 md:p-6 xl:p-8">
            {activeTab === 'dashboard' && <Dashboard />}
            {activeTab === 'trips' && <Trips />}
            {activeTab === 'fuel' && <Fuel />}
            {activeTab === 'maintenance' && <Maintenance />}
            {activeTab === 'detaylar' && <Detaylar />}
            {activeTab === 'invoices' && <Invoices />}
            {activeTab === 'payments' && <Payments />}
            {activeTab === 'settings' && <SettingsPage />}
            {activeTab === 'company_admin' && <CompanyAdmin />}
            {activeTab === 'super_admin' && <SuperAdmin />}
            {activeTab === 'adminlog' && (userRole === 'super_admin' || userRole === 'company_admin') && <AdminLog />}
          </div>
        </div>
      </main>

      {/* Mobil Alt Bar - Minimalist Navigation */}
      <div className="md:hidden fixed bottom-0 left-0 right-0 z-40 transition-all duration-300"
        style={{
          background: 'var(--bg-panel)',
          borderTop: '1px solid var(--border-color)',
          backdropFilter: 'blur(24px)',
          paddingBottom: 'env(safe-area-inset-bottom)',
        }}
      >
        <div className="flex justify-around items-center px-2 pt-3 pb-2">
          {[
            { id: 'dashboard', label: 'Özet', icon: <PieChart size={20} /> },
            { id: 'trips', label: 'Seferler', icon: <MapPin size={20} /> },
            { id: 'fuel', label: 'Mazot', icon: <Droplet size={20} /> },
            { id: 'maintenance', label: 'Araç', icon: <Wrench size={20} /> },
          ].filter(item => filteredMenuItems.find(m => m.id === item.id)).map((item) => (
            <button key={item.id} onClick={() => setActiveTab(item.id)}
              className={`flex flex-col items-center flex-1 py-1.5 rounded-xl transition-all duration-300 ${activeTab === item.id
                ? 'text-brand-500 scale-105'
                : 'text-slate-400/80 hover:text-slate-300'
                }`}>
              {item.icon}
              <span className="text-[10px] mt-1 font-medium tracking-wide">{item.label}</span>
            </button>
          ))}
          <button onClick={() => setIsMenuOpen(true)}
            className="flex flex-col items-center flex-1 py-1.5 rounded-xl transition-all duration-300 text-slate-400/80 hover:text-slate-300">
            <Menu size={20} />
            <span className="text-[10px] mt-1 font-medium tracking-wide">Daha</span>
          </button>
        </div>
      </div>
    </div>
  )
}

export default App

import React, { useState, useContext } from 'react';
import { useCompany } from '../context/CompanyContext';
import { useTruck } from '../context/TruckContext';
import { DataContext } from '../context/DataContext';
import { Building2, Truck, Users, Plus, Edit2, Trash2, Check, X, AlertTriangle } from 'lucide-react';
import { db } from '../services/firebaseConfig';
import { collection, addDoc, updateDoc, doc, deleteDoc } from 'firebase/firestore';

const CompanyAdmin = () => {
    const { activeCompanyId, companyData } = useCompany();
    const { trucks, activeTruckId, setActiveTruckId } = useTruck();
    const { approvedUsers, pendingUsers, approveUser, rejectUser, addApprovedUser } = useContext(DataContext);

    const [activeTab, setActiveTab] = useState('trucks');

    // Yeni: Kullanıcı Silme Onay Modalı
    const [userToDelete, setUserToDelete] = useState(null);
    const [isDeleteModalOpen, setIsDeleteModalOpen] = useState(false);


    // Truck Form
    const [showTruckForm, setShowTruckForm] = useState(false);
    const [truckPlate, setTruckPlate] = useState('');
    const [truckBrand, setTruckBrand] = useState('');

    const [editingTruckId, setEditingTruckId] = useState(null);
    const [editTruckForm, setEditTruckForm] = useState({ plate: '', brand: '', status: 'active' });

    const handleAddTruck = async (e) => {
        e.preventDefault();
        try {
            await addDoc(collection(db, 'trucks'), {
                companyId: activeCompanyId,
                plate: truckPlate,
                brand: truckBrand,
                status: 'active',
                createdAt: new Date().toISOString()
            });
            setTruckPlate('');
            setTruckBrand('');
            setShowTruckForm(false);
        } catch (err) {
            console.error(err);
        }
    };

    const handleEditSaveTruck = async (truckId) => {
        try {
            await updateDoc(doc(db, 'trucks', truckId), {
                plate: editTruckForm.plate.toUpperCase(),
                brand: editTruckForm.brand,
                status: editTruckForm.status
            });
            setEditingTruckId(null);
        } catch (err) {
            console.error(err);
        }
    };

    const handleDeleteTruck = async (truckId, plate) => {
        if (window.confirm(`${plate} plakalı aracı tamamen silmek istediğinize emin misiniz? (Geçmiş veriler askıda kalabilir)`)) {
            try {
                await deleteDoc(doc(db, 'trucks', truckId));
            } catch (err) {
                console.error(err);
            }
        }
    };

    return (
        <div className="space-y-6 animate-in fade-in duration-500">
            {/* Header */}
            <div className="glass-panel p-6 border-l-4 border-l-brand-500 flex justify-between items-center">
                <div>
                    <h3 className="text-xl font-bold flex items-center mb-1 text-[var(--text-primary)]">
                        <Building2 className="mr-3 text-brand-400" size={24} />
                        Şirket Yönetimi: {companyData?.name || 'Yükleniyor...'}
                    </h3>
                    <p className="text-[var(--text-secondary)] text-sm">
                        Şirketinize ait araçları ve şoförleri buradan yönetebilirsiniz.
                    </p>
                </div>
            </div>

            {/* Tabs */}
            <div className="flex space-x-2 border-b border-[var(--border-color)] pb-px">
                <button
                    onClick={() => setActiveTab('trucks')}
                    className={`px-4 py-2 font-medium text-sm transition-colors border-b-2 ${activeTab === 'trucks' ? 'border-brand-500 text-brand-400' : 'border-transparent text-[var(--text-secondary)] hover:text-[var(--text-primary)]'}`}
                >
                    <div className="flex items-center"><Truck size={16} className="mr-2" /> Araçlar ({trucks.length})</div>
                </button>
                <button
                    onClick={() => setActiveTab('drivers')}
                    className={`px-4 py-2 font-medium text-sm transition-colors border-b-2 ${activeTab === 'drivers' ? 'border-brand-500 text-brand-400' : 'border-transparent text-[var(--text-secondary)] hover:text-[var(--text-primary)]'}`}
                >
                    <div className="flex items-center"><Users size={16} className="mr-2" /> Şoförler</div>
                </button>
            </div>

            {/* Trucks Tab */}
            {activeTab === 'trucks' && (
                <div className="space-y-4">
                    <div className="flex justify-between items-center bg-[var(--bg-panel-hover)] p-4 rounded-xl border border-[var(--border-color)]">
                        <div className="text-sm text-[var(--text-primary)]">Sisteme kayıtlı toplam <strong>{trucks.length}</strong> araç bulunuyor.</div>
                        <button onClick={() => setShowTruckForm(!showTruckForm)} className="bg-brand-500 hover:bg-brand-600 text-[var(--text-primary)] px-4 py-2 rounded-lg text-sm font-medium flex items-center transition-colors">
                            <Plus size={16} className="mr-1.5" /> Yeni Araç Ekle
                        </button>
                    </div>

                    {showTruckForm && (
                        <form onSubmit={handleAddTruck} className="glass-panel p-5 grid grid-cols-1 md:grid-cols-3 gap-4 border border-brand-500/20">
                            <div>
                                <label className="block text-xs font-medium text-[var(--text-secondary)] mb-1">Plaka</label>
                                <input type="text" required value={truckPlate} onChange={e => setTruckPlate(e.target.value.toUpperCase())} className="w-full bg-[var(--bg-panel-hover)] border border-[var(--border-color)] text-[var(--text-primary)] rounded-lg px-3 py-2 text-sm focus:border-brand-500 outline-none" placeholder="Örn: 34 ABC 123" />
                            </div>
                            <div>
                                <label className="block text-xs font-medium text-[var(--text-secondary)] mb-1">Marka & Model</label>
                                <input type="text" required value={truckBrand} onChange={e => setTruckBrand(e.target.value)} className="w-full bg-[var(--bg-panel-hover)] border border-[var(--border-color)] text-[var(--text-primary)] rounded-lg px-3 py-2 text-sm focus:border-brand-500 outline-none" placeholder="Örn: Mercedes Actros" />
                            </div>
                            <div className="flex items-end">
                                <button type="submit" className="w-full bg-emerald-500/10 text-emerald-400 hover:bg-emerald-500/20 border border-emerald-500/20 px-4 py-2 rounded-lg text-sm font-medium transition-colors">
                                    Kaydet
                                </button>
                            </div>
                        </form>
                    )}

                    <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                        {trucks.map(truck => (
                            <div key={truck.id} className={`glass-panel p-5 relative group transition-all ${activeTruckId === truck.id ? 'border-brand-500 bg-brand-500/5' : 'border-[var(--border-color)] hover:border-slate-600'}`}>
                                <div className="flex justify-between items-start mb-3">
                                    <div className="w-10 h-10 rounded-lg bg-[var(--bg-panel-hover)] flex items-center justify-center border border-[var(--border-color)]">
                                        <Truck size={20} className={activeTruckId === truck.id ? 'text-brand-400' : 'text-[var(--text-secondary)]'} />
                                    </div>
                                    <span className={`text-[10px] font-bold px-2 py-0.5 rounded-full ${
                                        activeTruckId === truck.id
                                            ? 'bg-emerald-500/10 text-emerald-400'
                                            : truck.status === 'inactive'
                                                ? 'bg-red-500/10 text-red-400'
                                                : truck.status === 'maintenance'
                                                    ? 'bg-amber-500/10 text-amber-400'
                                                    : 'bg-emerald-500/10 text-emerald-400'
                                    }`}>
                                        {activeTruckId === truck.id
                                            ? 'AKTİF'
                                            : truck.status === 'inactive'
                                                ? 'PASİF'
                                                : truck.status === 'maintenance'
                                                    ? 'BAKIMDA'
                                                    : 'AKTİF'
                                        }
                                    </span>
                                </div>

                                {editingTruckId === truck.id ? (
                                    <div className="space-y-3 mb-4">
                                        <input type="text" value={editTruckForm.plate} onChange={e => setEditTruckForm({ ...editTruckForm, plate: e.target.value })} className="w-full bg-[var(--bg-panel-hover)] border border-[var(--border-color)] text-[var(--text-primary)] rounded-md px-3 py-1.5 text-sm outline-none focus:border-brand-500" placeholder="Plaka" />
                                        <input type="text" value={editTruckForm.brand} onChange={e => setEditTruckForm({ ...editTruckForm, brand: e.target.value })} className="w-full bg-[var(--bg-panel-hover)] border border-[var(--border-color)] text-[var(--text-primary)] rounded-md px-3 py-1.5 text-sm outline-none focus:border-brand-500" placeholder="Marka" />
                                        <select value={editTruckForm.status} onChange={e => setEditTruckForm({ ...editTruckForm, status: e.target.value })} className="w-full bg-[var(--bg-panel-hover)] border border-[var(--border-color)] text-[var(--text-primary)] rounded-md px-3 py-1.5 text-sm outline-none focus:border-brand-500">
                                            <option value="active">Aktif (Çalışıyor)</option>
                                            <option value="inactive">Pasif (Yatıyor)</option>
                                            <option value="maintenance">Bakımda</option>
                                        </select>
                                        <div className="flex gap-2">
                                            <button onClick={() => handleEditSaveTruck(truck.id)} className="flex-1 bg-brand-500/20 hover:bg-brand-500/30 text-brand-400 py-1.5 rounded-md text-xs font-semibold transition border border-brand-500/30 flex justify-center items-center gap-1">
                                                <Check size={12} /> Kaydet
                                            </button>
                                            <button onClick={() => setEditingTruckId(null)} className="flex-1 bg-slate-700/50 hover:bg-slate-700/80 text-[var(--text-primary)] py-1.5 rounded-md text-xs font-semibold transition border border-slate-600/50 flex justify-center items-center gap-1">
                                                <X size={12} /> İptal
                                            </button>
                                        </div>
                                    </div>
                                ) : (
                                    <div className="mb-4">
                                        <h4 className="text-xl font-bold tracking-tight text-[var(--text-primary)] mb-1">{truck.plate}</h4>
                                        <p className="text-xs text-[var(--text-secondary)] font-medium">{truck.brand}</p>
                                    </div>
                                )}

                                <div className="mt-auto pt-4 border-t border-[var(--border-color)] flex justify-between items-center">
                                    <button
                                        onClick={() => setActiveTruckId(truck.id)}
                                        className={`flex-1 py-1.5 rounded-md text-xs font-medium transition-colors ${activeTruckId === truck.id ? 'bg-brand-500 text-[var(--text-primary)]' : 'bg-[var(--bg-panel-hover)] text-[var(--text-primary)] hover:bg-slate-700'}`}
                                    >
                                        {activeTruckId === truck.id ? 'Şu An Seçili' : 'Bu Araca Geç'}
                                    </button>
                                    <div className="flex gap-1.5 ml-3">
                                        <button onClick={() => { setEditingTruckId(truck.id); setEditTruckForm({ plate: truck.plate, brand: truck.brand, status: truck.status || 'active' }); }} className="text-slate-500 hover:text-brand-400 p-1.5 bg-[var(--bg-panel-hover)] hover:bg-brand-500/10 rounded-md transition-colors" title="Düzenle">
                                            <Edit2 size={13} />
                                        </button>
                                        <button onClick={() => handleDeleteTruck(truck.id, truck.plate)} className="text-slate-500 hover:text-red-400 p-1.5 bg-[var(--bg-panel-hover)] hover:bg-red-500/10 rounded-md transition-colors" title="Aracı Sil">
                                            <Trash2 size={13} />
                                        </button>
                                    </div>
                                </div>
                            </div>
                        ))}
                    </div>
                </div>
            )}

            {/* Drivers Tab */}
            {activeTab === 'drivers' && (
                <div className="space-y-6">
                    {/* Bekleyen Başvurular */}
                    {pendingUsers.length > 0 && (
                        <div className="glass-panel p-5 border-l-4 border-l-amber-500">
                            <h4 className="text-sm font-bold text-amber-400 mb-3">Onay Bekleyen Şoför Başvuruları ({pendingUsers.length})</h4>
                            <div className="space-y-3">
                                {pendingUsers.map(user => (
                                    <div key={user.id} className="flex items-center justify-between bg-[var(--bg-panel-hover)] p-3 rounded-lg border border-[var(--border-color)]">
                                        <div>
                                            <p className="font-medium text-[var(--text-primary)]">{user.username}</p>
                                            <p className="text-xs text-slate-500">Kayıt: {new Date(user.requestedAt).toLocaleDateString('tr-TR')}</p>
                                        </div>
                                        <div className="flex space-x-2">
                                            <button onClick={() => approveUser(user.id, 'şoför')} className="bg-emerald-500/10 text-emerald-400 hover:bg-emerald-500/20 p-2 rounded-md transition-colors" title="Şoför Olarak Onayla">
                                                <Check size={16} />
                                            </button>
                                            <button onClick={() => rejectUser(user.id)} className="bg-red-500/10 text-red-400 hover:bg-red-500/20 p-2 rounded-md transition-colors" title="Reddet">
                                                <X size={16} />
                                            </button>
                                        </div>
                                    </div>
                                ))}
                            </div>
                        </div>
                    )}

                    {/* Aktif Şoförler */}
                    <div className="glass-panel p-5">
                        <div className="flex justify-between items-center mb-4">
                            <h4 className="text-sm font-bold text-[var(--text-primary)]">Aktif Şoförler</h4>
                        </div>
                        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                            {approvedUsers.filter(u => u.role === 'şoför' || u.role === 'user').map(driver => (
                                <div key={driver.id} className="bg-[var(--bg-panel-hover)] p-4 rounded-xl border border-[var(--border-color)] flex items-center space-x-4">
                                    <div className="w-10 h-10 rounded-full bg-slate-700 flex items-center justify-center text-[var(--text-primary)] flex-shrink-0">
                                        <Users size={20} />
                                    </div>
                                    <div className="flex-1 min-w-0">
                                        <p className="font-bold text-[var(--text-primary)] truncate">{driver.username}</p>
                                        <span className="text-[10px] uppercase tracking-wider font-bold text-brand-400 bg-brand-500/10 px-2 py-0.5 rounded-full inline-block mt-1">
                                            ŞOFÖR
                                        </span>
                                    </div>
                                    <button
                                        onClick={() => {
                                            setUserToDelete(driver);
                                            setIsDeleteModalOpen(true);
                                        }}
                                        className="text-slate-500 hover:text-red-400 p-2 transition-colors"
                                        title="Şoförü Sil"
                                    >
                                        <Trash2 size={16} />
                                    </button>
                                </div>
                            ))}
                            {approvedUsers.filter(u => u.role === 'şoför' || u.role === 'user').length === 0 && (
                                <div className="col-span-full text-center py-6 text-slate-500 text-sm">
                                    Henüz kayıtlı şoför bulunmuyor.
                                </div>
                            )}
                        </div>
                    </div>
                </div>
            )}

            {/* Kullanıcı Silme Onay Modalı */}
            {isDeleteModalOpen && userToDelete && (
                <div className="fixed inset-0 z-[60] flex items-center justify-center p-4 bg-[var(--bg-base)] backdrop-blur-md">
                    <div className="glass-panel w-full max-w-sm p-6 relative animate-in zoom-in-95 duration-200">
                        <button onClick={() => { setIsDeleteModalOpen(false); setUserToDelete(null); }} className="absolute top-4 right-4 text-[var(--text-secondary)] hover:text-[var(--text-primary)]"><X size={20} /></button>
                        <h3 className="text-xl font-bold text-[var(--text-primary)] mb-2 flex items-center gap-2">
                            <AlertTriangle className="text-red-500" /> Şoförü Sil
                        </h3>
                        <p className="text-sm text-[var(--text-secondary)] mb-6">
                            <strong className="text-[var(--text-primary)] uppercase">{userToDelete.username}</strong> isimli şoförü şirketinizden tamamen silmek istediğinize emin misiniz?
                        </p>
                        <div className="flex flex-col sm:flex-row gap-3">
                            <button onClick={() => { setIsDeleteModalOpen(false); setUserToDelete(null); }} className="w-full sm:flex-1 bg-[var(--bg-panel-hover)] hover:bg-slate-700 text-[var(--text-primary)] py-2.5 rounded-lg text-sm font-semibold transition border border-[var(--border-color)]">
                                İptal Et
                            </button>
                            <button onClick={async () => {
                                try {
                                    await deleteDoc(doc(db, 'approved_users', userToDelete.id));
                                    setIsDeleteModalOpen(false);
                                    setUserToDelete(null);
                                } catch (error) {
                                    console.error(error);
                                    alert("Kullanıcı silinirken bir hata oluştu.");
                                }
                            }} className="w-full sm:flex-1 bg-red-600 hover:bg-red-500 text-[var(--text-primary)] py-2.5 rounded-lg text-sm font-semibold transition shadow-lg shadow-red-500/20">
                                Evet, Tamamen Sil
                            </button>
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
};

export default CompanyAdmin;

import React, { useState, useMemo } from 'react';
import { X, Calendar as CalendarIcon, ChevronLeft, ChevronRight, Droplet } from 'lucide-react';

const InvoicePeriodModal = ({ isOpen, onClose, trips, allTrips = [], lastInvoiceEndDate, onSelectPeriod, fuelRecords = [] }) => {
    // Current viewed month in the calendar
    const [currentDate, setCurrentDate] = useState(new Date());

    // Selection state
    // 0: none selected, 1: start selected, 2: both selected
    const [selectionStep, setSelectionStep] = useState(0);
    const [startDate, setStartDate] = useState(null);
    const [endDate, setEndDate] = useState(null);

    // Filtered trips for the selected range to show a preview
    const tripsInPeriod = useMemo(() => {
        if (!startDate || !endDate) return [];
        const startStr = startDate.toISOString().split('T')[0];
        const endStr = endDate.toISOString().split('T')[0];
        return trips.filter(t => !t.deleted && t.status === 'Fatura Bekliyor' && t.date >= startStr && t.date <= endStr);
    }, [startDate, endDate, trips]);

    if (!isOpen) return null;

    const daysInMonth = new Date(currentDate.getFullYear(), currentDate.getMonth() + 1, 0).getDate();
    const firstDayOfMonth = new Date(currentDate.getFullYear(), currentDate.getMonth(), 1).getDay();
    // Adjust Sunday to 6, Monday to 0 for TR locale
    const startOffset = firstDayOfMonth === 0 ? 6 : firstDayOfMonth - 1;

    // Helper map for fast lookup of trip statuses by date
    const tripStatusByDate = allTrips.reduce((acc, t) => {
        if (t.deleted) return acc;
        if (!acc[t.date]) acc[t.date] = { count: 0, pending: 0, completed: 0 };
        acc[t.date].count++;
        if (t.status === 'Fatura Bekliyor') acc[t.date].pending++;
        if (t.status === 'Fatura Kesildi') acc[t.date].completed++;
        return acc;
    }, {});

    const prevMonth = () => setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth() - 1, 1));
    const nextMonth = () => setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth() + 1, 1));

    const handleDateClick = (day) => {
        const clickedDate = new Date(currentDate.getFullYear(), currentDate.getMonth(), day, 12, 0, 0); // Noon to avoid timezone shifts
        const dateStr = clickedDate.toISOString().split('T')[0];

        // Faturası zaten kesilmiş bir günü başlangıç veya bitiş olarak seçmesini engelle
        const tripsInfo = tripStatusByDate[dateStr];
        if (tripsInfo && tripsInfo.completed > 0 && tripsInfo.pending === 0) {
            return; // Zaten kesilmiş, tıklanamaz
        }

        if (selectionStep === 0 || selectionStep === 2) {
            // Start parsing a new range
            setStartDate(clickedDate);
            setEndDate(null);
            setSelectionStep(1);
        } else if (selectionStep === 1) {
            // Complete the range
            if (clickedDate < startDate) {
                // Swap if they clicked an earlier date
                setEndDate(startDate);
                setStartDate(clickedDate);
            } else {
                setEndDate(clickedDate);
            }
            setSelectionStep(2);
        }
    };

    const handleConfirm = () => {
        if (startDate && endDate) {
            const startStr = startDate.toISOString().split('T')[0];
            const endStr = endDate.toISOString().split('T')[0];
            onSelectPeriod({ startDate: startStr, endDate: endStr, trips: tripsInPeriod });
            onClose();
        } else {
            alert("Lütfen bir başlangıç ve bitiş tarihi seçin.");
        }
    };

    // Render calendar grid
    const renderCalendarDays = () => {
        const grid = [];
        const weekdays = ['Pzt', 'Sal', 'Çar', 'Per', 'Cum', 'Cmt', 'Paz'];

        // Weekday Headers
        weekdays.forEach(day => {
            grid.push(<div key={`header-${day}`} className="py-2 text-center text-xs font-semibold text-slate-500 uppercase">{day}</div>);
        });

        // Empty cells before the 1st
        for (let i = 0; i < startOffset; i++) {
            grid.push(<div key={`empty-${i}`} className="p-2"></div>);
        }

        // Days
        const todayStr = new Date().toISOString().split('T')[0];

        for (let day = 1; day <= daysInMonth; day++) {
            const dateObj = new Date(currentDate.getFullYear(), currentDate.getMonth(), day, 12, 0, 0);
            const dateStr = dateObj.toISOString().split('T')[0];
            const tripsInfo = tripStatusByDate[dateStr];

            // Yakıt alındı mı?
            const hasFuel = fuelRecords.some(r => !r.deleted && r.date === dateStr);

            // Interaction States
            const isStartDate = startDate && dateObj.toDateString() === startDate.toDateString();
            const isEndDate = endDate && dateObj.toDateString() === endDate.toDateString();
            const isInRange = startDate && endDate && dateObj > startDate && dateObj < endDate;

            // Sadece faturası kesilmiş (ve bekleyeni olmayan) bir gün ise tıklanmasın
            const isFullyCompleted = tripsInfo && tripsInfo.completed > 0 && tripsInfo.pending === 0;

            // Visual Styles based on Trip Data
            let dotStyle = "";
            let dotTitle = "";
            if (tripsInfo) {
                if (tripsInfo.pending > 0) {
                    dotStyle = "bg-emerald-500 shadow-[0_0_8px_rgba(16,185,129,0.8)]"; // Fatura Bekliyor (Yeşil)
                    dotTitle = `${tripsInfo.pending} sefer faturası bekliyor`;
                } else if (tripsInfo.completed > 0) {
                    dotStyle = "bg-orange-500 shadow-[0_0_5px_rgba(249,115,22,0.8)]"; // Önceden kesilmiş (Turuncu/Sönük)
                    dotTitle = "Bu tarihin faturaları daha önce kesildi";
                }
            }

            // Cell Styles
            let cellStyle = "text-[var(--text-primary)] hover:bg-white/10 hover:text-[var(--text-primary)]";
            if (isFullyCompleted) {
                cellStyle = "text-slate-500 cursor-default"; // Turuncu (tamamlanan) günler hover efektine sahip olmasın
            } else if (isStartDate || isEndDate) {
                cellStyle = "bg-brand-500 text-[var(--text-primary)] font-bold shadow-lg scale-105 z-10 rounded-lg";
            } else if (isInRange) {
                cellStyle = "bg-brand-500/20 text-brand-100 rounded-none";
            }

            // Make start and end bounds connect visually if within a range
            let roundedClasses = "rounded-lg";
            if (isStartDate && endDate) roundedClasses = "rounded-l-lg rounded-r-none";
            if (isEndDate && startDate) roundedClasses = "rounded-r-lg rounded-l-none";
            if (isStartDate && isEndDate) roundedClasses = "rounded-lg"; // Same day

            grid.push(
                <div
                    key={day}
                    onClick={() => handleDateClick(day)}
                    className={`relative flex flex-col items-center justify-center p-2 transition-all duration-200 ${!isFullyCompleted ? 'cursor-pointer' : ''} ${cellStyle} ${roundedClasses}`}
                    title={dotTitle}
                >
                    <span className="text-sm z-10 relative flex flex-col items-center">
                        {day}
                        {hasFuel && (
                            <div className="absolute -bottom-2 w-4 h-[2px] bg-cyan-400 shadow-[0_0_6px_rgba(34,211,238,1)] rounded-full"></div>
                        )}
                    </span>
                    {dotStyle && (
                        <div className={`absolute bottom-1 right-1 w-1.5 h-1.5 rounded-full ${dotStyle} z-10`}></div>
                    )}
                </div>
            );
        }

        return grid;
    };

    return (
        <div className="fixed inset-0 bg-black/80 backdrop-blur-md flex items-center justify-center p-2 sm:p-4 z-50">
            <div className="glass-panel w-full max-w-2xl flex flex-col md:flex-row max-h-[98vh] md:max-h-[90vh] overflow-hidden animate-in zoom-in-95 duration-200">

                {/* Sol Taraf: Takvim */}
                <div className="w-full md:w-[60%] p-3 sm:p-4 md:p-6 border-b md:border-b-0 md:border-r border-[var(--border-color)] flex flex-col overflow-y-auto md:overflow-visible min-h-[320px] md:min-h-0">
                    <div className="flex justify-between items-center mb-6">
                        <h3 className="text-lg font-bold text-[var(--text-primary)] flex items-center">
                            <CalendarIcon className="mr-2 text-brand-400" size={18} />
                            Periyot Seçimi
                        </h3>
                        <div className="flex gap-2">
                            <button onClick={prevMonth} className="p-1.5 text-[var(--text-secondary)] hover:text-[var(--text-primary)] hover:bg-white/10 rounded transition-colors"><ChevronLeft size={16} /></button>
                            <span className="text-sm font-medium text-[var(--text-primary)] w-24 text-center">
                                {currentDate.toLocaleDateString('tr-TR', { month: 'long', year: 'numeric' })}
                            </span>
                            <button onClick={nextMonth} className="p-1.5 text-[var(--text-secondary)] hover:text-[var(--text-primary)] hover:bg-white/10 rounded transition-colors"><ChevronRight size={16} /></button>
                        </div>
                    </div>

                    <div className="grid grid-cols-7 gap-y-1 sm:gap-y-2 gap-x-1 flex-1">
                        {renderCalendarDays()}
                    </div>

                    <div className="mt-3 sm:mt-4 pt-3 sm:pt-4 border-t border-[var(--border-color)] flex flex-wrap gap-x-4 gap-y-2 text-[9px] sm:text-[10px] text-[var(--text-secondary)] justify-center">
                        <div className="flex items-center gap-1.5">
                            <span className="w-1.5 h-1.5 sm:w-2 sm:h-2 rounded-full bg-emerald-500 shadow-[0_0_5px_rgba(16,185,129,0.8)] block"></span> Kesilecek
                        </div>
                        <div className="flex items-center gap-1.5">
                            <span className="w-1.5 h-1.5 sm:w-2 sm:h-2 rounded-full bg-orange-500 shadow-[0_0_5px_rgba(249,115,22,0.8)] block"></span> Tamamlanan
                        </div>
                        <div className="flex items-center gap-1.5">
                            <span className="w-2.5 h-0.5 sm:w-3 sm:h-0.5 rounded-full bg-cyan-400 shadow-[0_0_5px_rgba(34,211,238,1)] block"></span> Yakıt Alındı
                        </div>
                    </div>
                </div>

                {/* Sağ Taraf: Detaylar & Seçim */}
                <div className="w-full md:w-[40%] bg-[var(--bg-panel)] p-3 sm:p-4 md:p-6 flex flex-col border-t md:border-t-0 border-[var(--border-color)] overflow-y-auto">
                    <div className="flex justify-between items-start mb-3 sm:mb-6">
                        <h4 className="text-xs sm:text-sm font-bold text-[var(--text-primary)]">Seçim Detayları</h4>
                        <button onClick={onClose} className="p-1 text-slate-500 hover:text-[var(--text-primary)] transition-colors">
                            <X size={18} />
                        </button>
                    </div>

                    <div className="flex flex-row md:flex-col gap-2 md:space-y-4 mb-3 sm:mb-6">
                        <div className="flex-1 bg-black/30 p-2 sm:p-3 rounded-lg border border-[var(--border-color)]">
                            <p className="text-[8px] sm:text-[10px] text-slate-500 mb-0.5 sm:mb-1 uppercase tracking-wider">BAŞLANGIÇ</p>
                            <p className="text-[10px] sm:text-sm font-semibold text-brand-300 leading-tight">
                                {startDate ? startDate.toLocaleDateString('tr-TR', { day: '2-digit', month: 'short' }) : 'Seçiniz...'}
                            </p>
                        </div>
                        <div className="flex-1 bg-black/30 p-2 sm:p-3 rounded-lg border border-[var(--border-color)]">
                            <p className="text-[8px] sm:text-[10px] text-slate-500 mb-0.5 sm:mb-1 uppercase tracking-wider">BİTİŞ</p>
                            <p className="text-[10px] sm:text-sm font-semibold text-brand-300 leading-tight">
                                {endDate ? endDate.toLocaleDateString('tr-TR', { day: '2-digit', month: 'short' }) : 'Seçiniz...'}
                            </p>
                        </div>
                    </div>

                    <div className="flex-1 min-h-[100px] md:min-h-0 overflow-y-auto custom-scrollbar border border-[var(--border-color)] rounded-lg bg-black/20 p-2 sm:p-3">
                        <p className="text-[10px] sm:text-xs text-[var(--text-secondary)] mb-2 border-b border-[var(--border-color)] pb-1 sm:pb-2">
                            Aralıkta Seçili Seferler: <strong className="text-emerald-400">{tripsInPeriod.length}</strong>
                        </p>
                        <ul className="space-y-1.5 sm:space-y-2">
                            {tripsInPeriod.map(t => (
                                <li key={t.id} className="text-[9px] sm:text-[10px] flex justify-between bg-white/5 p-1 sm:p-1.5 rounded">
                                    <span className="text-[var(--text-primary)]">{new Date(t.date).getDate()} {new Date(t.date).toLocaleDateString('tr-TR', { month: 'short' })}</span>
                                    <span className="text-[var(--text-secondary)] truncate max-w-[60px] sm:max-w-[80px]">{t.to}</span>
                                    <span className="text-brand-300 font-mono font-bold">{t.tonnage}t</span>
                                </li>
                            ))}
                            {tripsInPeriod.length === 0 && (
                                <li className="text-[10px] text-slate-500 italic text-center py-4">Fatura bekleyen sefer yok.</li>
                            )}
                        </ul>
                    </div>

                    <div className="mt-3 sm:mt-6 pt-3 sm:pt-4 border-t border-[var(--border-color)] shrink-0">
                        <button
                            onClick={handleConfirm}
                            disabled={!startDate || !endDate || tripsInPeriod.length === 0}
                            className={`w-full py-2 sm:py-2.5 rounded-lg text-xs sm:text-sm font-semibold transition-all shadow-lg ${startDate && endDate && tripsInPeriod.length > 0
                                ? 'bg-emerald-600 hover:bg-emerald-500 text-[var(--text-primary)] shadow-emerald-500/25 border border-emerald-500'
                                : 'bg-[var(--bg-panel-hover)] text-slate-500 cursor-not-allowed border border-[var(--border-color)]'
                                }`}
                        >
                            Dökümü Oluştur
                        </button>
                    </div>
                </div>
            </div>
        </div>
    );
};

export default InvoicePeriodModal;

import React, { useContext, useState, useRef, useEffect, useMemo } from 'react';
import { FileText, Printer, Save, PlusCircle, CheckCircle, Clock, Trash2, StickyNote, Paperclip } from 'lucide-react';
import { DataContext } from '../context/DataContext';
import { useTruck } from '../context/TruckContext';
import InvoicePeriodModal from './InvoicePeriodModal';
import A4InvoicePreview from './A4InvoicePreview';
import FileUpload from './FileUpload';
import { doc, updateDoc, writeBatch } from 'firebase/firestore';
import { db } from '../services/firebaseConfig';

const Invoices = () => {
    const { trips, invoices, addInvoice, updateInvoice, deleteInvoice, addLog, fuelRecords, draftInvoice, saveDraftInvoice, clearDraftInvoice } = useContext(DataContext);
    const { activeTruckData } = useTruck();
    const invoicePrintRef = useRef(null);

    const [isPeriodModalOpen, setIsPeriodModalOpen] = useState(false);

    // Aktif Düzenlenen Fatura State'i
    const [activeInvoice, setActiveInvoice] = useState(null);
    const [note, setNote] = useState('');
    const [invoiceFiles, setInvoiceFiles] = useState([]);
    const [isSavingNote, setIsSavingNote] = useState(false);
    const [noteModalInvoice, setNoteModalInvoice] = useState(null);
    const [modalNote, setModalNote] = useState('');
    const [modalFiles, setModalFiles] = useState([]);
    const [taxRate, setTaxRate] = useState(20); // Default 20%
    const [unitPrice, setUnitPrice] = useState(351.40); // Default Price

    // Sadece Fatura Bekleyen Seferler listesi (Yeni fatura oluşturmak için adaylar)
    const availableTrips = (trips || []).filter(t => !t.deleted && t.status === 'Fatura Bekliyor');

    // Son kesilen faturanın bitiş tarihini bul
    const lastInvoice = (invoices || [])[0];
    const lastInvoiceEndDate = lastInvoice ? lastInvoice.endDate : null;

    // Eski fatura görüntüleme modu
    const [isViewingOldInvoice, setIsViewingOldInvoice] = useState(false);
    const [showOldInvoiceWarning, setShowOldInvoiceWarning] = useState(false);

    // Uyarıyı 3 saniye sonra kapat
    useEffect(() => {
        if (showOldInvoiceWarning) {
            const timer = setTimeout(() => setShowOldInvoiceWarning(false), 3000);
            return () => clearTimeout(timer);
        }
    }, [showOldInvoiceWarning]);

    // Fatura listesi değişince aktif görüntülemenin geçerli olup olmadığını kontrol et
    useEffect(() => {
        if (isViewingOldInvoice && activeInvoice) {
            // Eğer görüntülenen fatura artık listede yoksa temizle (ID veya DocId üzerinden kontrol)
            const stillExists = (invoices || []).some(inv =>
                !inv.deleted && (inv.id === activeInvoice.id || (inv.docId && inv.docId === activeInvoice.docId))
            );
            if (!stillExists) {
                setActiveInvoice(null);
                setIsViewingOldInvoice(false);
                setNote('');
            }
        } else if (!activeInvoice && !isViewingOldInvoice) {
            // Önce taslağı yükle, yoksa son faturayı otomatik yükle
            if (draftInvoice) {
                setActiveInvoice(draftInvoice);
                setNote(draftInvoice.note || '');
                setTaxRate(draftInvoice.taxRate ?? 20);
                setUnitPrice(draftInvoice.unitPrice ?? 351.40);
                setIsViewingOldInvoice(false);
            } else {
                const last = (invoices || []).filter(inv => !inv.deleted)[0];
                if (last) {
                    setActiveInvoice(last);
                    setNote(last.note || '');
                    setTaxRate(last.taxRate ?? 20);
                    setUnitPrice(last.unitPrice ?? 351.40);
                    setIsViewingOldInvoice(true);
                    setShowOldInvoiceWarning(true);
                }
            }
        }
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [invoices]);

    // Yetim Seferleri Bul (Fatura Kesildi gözüken ama herhangi bir faturada olmayanlar)
    const orphanTrips = useMemo(() => {
        const invoicedTripIds = new Set();
        (invoices || []).filter(inv => !inv.deleted).forEach(inv => {
            (inv.trips || []).forEach(t => invoicedTripIds.add(t.id));
        });
        return (trips || []).filter(t => !t.deleted && t.status === 'Fatura Kesildi' && !invoicedTripIds.has(t.id));
    }, [trips, invoices]);

    const handleFixOrphans = async () => {
        if (orphanTrips.length === 0) return;
        if (window.confirm(`${orphanTrips.length} adet bağlantısız sefer bulundu. Bunları 'Fatura Bekliyor' durumuna geri çekmek istiyor musunuz?`)) {
            try {
                const batch = writeBatch(db);
                orphanTrips.forEach(t => {
                    batch.update(doc(db, 'trips', t.id), { status: 'Fatura Bekliyor' });
                });
                await batch.commit();
                addLog('YETIM_SEFER_DUZELTME', `${orphanTrips.length} adet sefer statüsü sıfırlandı.`);
                alert("İşlem başarılı. Artık takvimde bu günleri seçebilirsiniz.");
            } catch (err) {
                console.error("Düzeltme hatası:", err);
                alert("Bir hata oluştu.");
            }
        }
    };

    const handleOpenPeriodModal = () => {
        setIsPeriodModalOpen(true);
    };

    const handleSelectPeriod = ({ startDate, endDate, trips: selectedTrips }) => {
        // Yeni taslak oluştur
        const newDraft = {
            id: `TASLAK-${Date.now().toString().slice(-4)}`,
            startDate,
            endDate,
            trips: selectedTrips,
            status: 'Draft',
            note: '',
            taxRate: 20,
            unitPrice: 351.40
        };
        setActiveInvoice(newDraft);
        saveDraftInvoice(newDraft);
        setIsViewingOldInvoice(false);
        setNote('');
        setTaxRate(20);
        setUnitPrice(351.40);
    };

    // Eski faturaya tıklandığında önizleleme yükle
    const handleViewInvoice = (inv) => {
        setActiveInvoice(inv);
        setNote(inv.note || '');
        setInvoiceFiles(inv.files || []);
        setTaxRate(inv.taxRate ?? 20);
        setUnitPrice(inv.unitPrice ?? 351.40);
        setIsViewingOldInvoice(true);
        setShowOldInvoiceWarning(true);
    };

    const handleSaveInvoice = async () => {
        if (!activeInvoice || activeInvoice.trips.length === 0) {
            alert("Kaydedilecek sefer bulunamadı.");
            return;
        }

        const totalTonnage = activeInvoice.trips.reduce((acc, t) => acc + (Number(t.tonnage) || 0), 0);
        const subTotal = totalTonnage * unitPrice;
        const taxAmount = subTotal * (taxRate / 100);
        const grandTotal = subTotal + taxAmount;

        const newInvoiceData = {
            startDate: activeInvoice.startDate,
            endDate: activeInvoice.endDate,
            trips: (activeInvoice.trips || []).map(t => ({ id: t.id, date: t.date, from: t.from, to: t.to, tonnage: t.tonnage })),
            totalTonnage,
            subTotal,
            taxRate,
            taxAmount,
            grandTotal,
            note,
            unitPrice,
            status: 'Sent',
            docId: `INV-${new Date().getFullYear()}-${String(invoices.length + 1).padStart(3, '0')}` // Örn: INV-2026-001
        };

        try {
            // Faturayı Firebase'e ekle
            await addInvoice(newInvoiceData);

            // Faturası kesilen seferlerin status'ünü 'Fatura Kesildi' yap. (Batch Update)
            const batch = writeBatch(db);
            activeInvoice.trips.forEach(trip => {
                const tripRef = doc(db, 'trips', trip.id);
                batch.update(tripRef, { status: 'Fatura Kesildi' });
            });
            await batch.commit();
            await clearDraftInvoice();

            addLog('FATURA_KESILDI', `${activeInvoice.startDate} - ${activeInvoice.endDate} periyodu için fatura başarıyla kesildi.`);

            // Faturayı ekranda tut ve 'Sent' durumuna çek
            setActiveInvoice({ ...newInvoiceData, id: newInvoiceData.docId });
            setIsViewingOldInvoice(false);
        } catch (error) {
            console.error("Fatura kaydedilirken hata:", error);
            alert("Fatura kaydedilirken bir hata oluştu.");
        }
    };

    const handleSaveNoteAndFiles = async () => {
        if (!activeInvoice?.id) return;
        setIsSavingNote(true);
        try {
            await updateInvoice(activeInvoice.id, { note, files: invoiceFiles });
            setActiveInvoice(prev => ({ ...prev, note, files: invoiceFiles }));
            addLog('FATURA_NOT', `${activeInvoice.docId} notları güncellendi`);
        } catch (e) {
            console.error(e);
        } finally {
            setIsSavingNote(false);
        }
    };

    const handleDeleteInvoice = async (invoiceId, docId, e) => {
        e.stopPropagation();

        // Mobil kontrolü (768px altı)
        const isMobile = window.innerWidth < 768;

        if (isMobile || window.confirm(`${docId} numaralı faturayı/dökümü silmek istediğinize emin misiniz? (Bağlı seferler faturası kesilmemiş hale dönecektir)`)) {
            try {
                // Faturayı siliyoruz (Soft Delete)
                await deleteInvoice(invoiceId);

                // Bu faturaya bağlı olan seferleri bulup statülerini "Fatura Bekliyor" olarak geri alıyoruz
                const linkedInvoice = invoices.find(inv => inv.id === invoiceId);
                if (linkedInvoice && linkedInvoice.trips) {
                    const batch = writeBatch(db);
                    linkedInvoice.trips.forEach(trip => {
                        const tripRef = doc(db, 'trips', trip.id);
                        batch.update(tripRef, { status: 'Fatura Bekliyor' });
                    });
                    await batch.commit();
                }
            } catch (err) {
                console.error("Fatura silinirken hata:", err);
            }
        }
    };

    const handlePrintPDF = () => {
        if (!invoicePrintRef.current) return;

        // Sadece A4 alanını yazdırmak için geçici bir iframe veya window.print yöntemi kullanılabilir.
        // Tailwind classları yazıcıya geçerken bozulmasın diye modern tarayıcılarda direk body gizlenip sadece bu ref de yazdırılabilir.

        const printContent = invoicePrintRef.current;
        const orginalContents = document.body.innerHTML;

        // CSS in Js trick to print just the component
        const printWindow = window.open('', '', 'width=900,height=1200');
        printWindow.document.write('<html><head><title>Fatura Yazdır</title>');
        // Load all current stylesheets
        const styles = document.querySelectorAll('style, link[rel="stylesheet"]');
        styles.forEach(s => {
            printWindow.document.write(s.outerHTML);
        });
        printWindow.document.write('</head><body style="background-color: white;">');
        printWindow.document.write(printContent.outerHTML);
        printWindow.document.write('</body></html>');
        printWindow.document.close();
        printWindow.focus();
        setTimeout(() => {
            printWindow.print();
            printWindow.close();
        }, 500); // Wait for styles to load
    };

    return (
        <div className="flex flex-col md:flex-row md:h-[calc(100vh-64px)] gap-6 md:gap-8 animate-in fade-in duration-500 overflow-y-auto md:overflow-hidden pb-4 md:pb-0">

            {/* Sol Panel: Kontrol Merkezi */}
            <div className="w-full md:w-[45%] lg:w-[40%] flex flex-col gap-4 md:gap-6 md:overflow-y-auto custom-scrollbar md:pr-2">

                {/* Masüstü İzole Başlık (App.jsx'teki global başlığın yerini alır) */}
                <div className="hidden md:flex glass-panel px-6 py-4 items-center justify-between shadow-sm border-b border-[var(--border-color)] backdrop-blur-md rounded-2xl shrink-0">
                    <h2 className="text-2xl font-bold tracking-tight text-[var(--text-primary)] mb-0.5">Fatura Durumu</h2>
                </div>



                <div className="glass-panel p-6">
                    <button
                        onClick={handleOpenPeriodModal}
                        className="w-full bg-brand-600 hover:bg-brand-500 text-[var(--text-primary)] p-3 rounded-lg font-bold flex items-center justify-center transition-all shadow-lg shadow-brand-500/20"
                    >
                        <PlusCircle className="mr-2" size={20} /> Yeni Fatura Periyodu Seç
                    </button>
                    {activeInvoice && activeInvoice.status === 'Draft' && (
                        <div className="mt-4 p-4 bg-emerald-500/10 border border-emerald-500/30 rounded-lg group">
                            <div className="flex justify-between items-start mb-2">
                                <h4 className="flex items-center text-emerald-400 font-semibold">
                                    <Clock size={16} className="mr-2" /> İşlem Bekleyen Taslak
                                </h4>
                                <button
                                    onClick={() => {
                                        if (window.confirm("Taslağı iptal etmek istediğinize emin misiniz?")) {
                                            clearDraftInvoice();
                                            setActiveInvoice(null);
                                        }
                                    }}
                                    className="text-xs text-red-400 hover:text-red-300 transition-colors"
                                >
                                    İptal Et
                                </button>
                            </div>
                            <p className="text-sm text-[var(--text-primary)]">
                                {new Date(activeInvoice.startDate).toLocaleDateString('tr-TR')} - {new Date(activeInvoice.endDate).toLocaleDateString('tr-TR')}
                            </p>
                            <p className="text-xs text-slate-500 mt-1">{activeInvoice.trips.length} sefer seçildi.</p>
                        </div>
                    )}

                    {/* Aktif Fatura Aksiyonları (PDF, Onayla vb.) */}
                    {activeInvoice && (
                        <div className="mt-4 flex flex-col gap-2">
                            <button
                                onClick={handlePrintPDF}
                                className="w-full flex items-center justify-center gap-2 p-3 bg-slate-700 hover:bg-slate-600 text-[var(--text-primary)] rounded-xl text-sm font-medium transition-colors"
                            >
                                <Printer size={16} /> PDF İndir / Yazdır
                            </button>
                            {activeInvoice.status === 'Sent' ? (
                                <button
                                    disabled
                                    className="w-full flex items-center justify-center gap-2 p-3 bg-[var(--bg-panel-hover)] text-emerald-400 rounded-xl text-sm font-medium border border-emerald-500/30 opacity-80"
                                >
                                    <CheckCircle size={16} /> Fatura Onaylandı
                                </button>
                            ) : (
                                <button
                                    onClick={handleSaveInvoice}
                                    className="w-full flex items-center justify-center gap-2 p-3 bg-emerald-600 hover:bg-emerald-500 text-[var(--text-primary)] rounded-xl text-sm font-medium transition-colors border border-emerald-500 shadow-lg shadow-emerald-500/20"
                                >
                                    <Save size={16} /> Faturayı Kes & Onayla
                                </button>
                            )}
                        </div>
                    )}


                    {/* Yetim Sefer Uyarısı */}

                </div>

                {/* Geçmiş Faturalar Listesi */}
                <div className="glass-panel flex-1 min-h-0 flex flex-col">
                    <div className="p-4 border-b border-[var(--border-color)] sticky top-0 bg-[var(--bg-panel)] backdrop-blur z-10 rounded-t-xl">
                        <h4 className="font-bold text-[var(--text-primary)] flex items-center">
                            <CheckCircle className="mr-2 text-brand-400" size={18} />
                            Tamamlanan Faturalar
                        </h4>
                    </div>
                    <div className="p-4 flex-1 overflow-y-auto custom-scrollbar space-y-3">
                        {(invoices || []).length > 0 ? (invoices || []).filter(inv => !inv.deleted).map(inv => (
                            <div
                                key={inv.id}
                                onClick={() => handleViewInvoice(inv)}
                                className={`p-3 bg-white/5 hover:bg-white/10 border rounded-lg transition-colors group relative cursor-pointer ${activeInvoice?.id === inv.id && isViewingOldInvoice ? 'border-amber-400/50 bg-amber-400/5' : 'border-[var(--border-color)]'
                                    }`}
                            >
                                <div className="flex justify-between items-center mb-1">
                                    <span className="font-bold text-brand-400 text-sm">{inv.docId}</span>
                                    <div className="flex items-center gap-1.5">
                                        <span className="text-xs text-[var(--text-secondary)]">{new Date(inv.endDate).toLocaleDateString('tr-TR')}</span>
                                        <button
                                            onClick={(e) => { e.stopPropagation(); setNoteModalInvoice(inv); setModalNote(inv.note || ''); setModalFiles(inv.files || []); }}
                                            className={`p-1 rounded transition-colors ${inv.note || inv.files?.length > 0 ? 'text-brand-400' : 'text-slate-600 hover:text-brand-400 md:opacity-0 group-hover:opacity-100'}`}
                                            title="Not & Belge Ekle"
                                        >
                                            <StickyNote size={13} />
                                        </button>
                                        <button
                                            onClick={(e) => handleDeleteInvoice(inv.id, inv.docId, e)}
                                            className="text-slate-500 hover:text-red-400 p-1 md:opacity-0 group-hover:opacity-100 transition-opacity"
                                            title="Faturayı Sil"
                                        >
                                            <Trash2 size={14} />
                                        </button>
                                    </div>
                                </div>
                                <div className="text-sm text-[var(--text-primary)] font-medium">₺{inv.grandTotal?.toLocaleString('tr-TR', { minimumFractionDigits: 2 })}</div>
                                <div className="text-xs text-slate-500 mt-1">{inv.trips?.length || 0} Sefer | {inv.totalTonnage?.toFixed(2)} Ton
                                    {(inv.note || inv.files?.length > 0) && <span className="ml-2 text-brand-400">📎 {inv.files?.length || 0}{inv.note ? ' · not' : ''}</span>}
                                </div>
                            </div>
                        )) : (
                            <div className="text-center py-8 text-slate-500 text-sm">
                                <FileText size={24} className="mx-auto mb-2 opacity-50" />
                                Henüz kesilmiş fatura yok.
                            </div>
                        )}
                    </div>
                </div>
            </div>

            {/* Sağ Panel: A4 Fatura Görünümü */}
            <div className="w-full md:w-[55%] lg:w-[60%] relative flex flex-col overflow-hidden md:min-h-0 pl-0 md:pl-4" style={{ minHeight: '70vh' }}>
                {/* A4 Render Alanı (Çerçevesiz ve temiz alan) */}
                <div className="w-full relative overflow-hidden flex flex-col" style={{ flex: 1, minHeight: '70vh' }}>
                    {activeInvoice ? (
                        <A4InvoicePreview
                            ref={invoicePrintRef}
                            invoiceData={activeInvoice}
                            vehicleInfo={{ plate: activeTruckData?.plate, trailerPlate: activeTruckData?.trailerPlate }}
                            note={note}
                            onChangeNote={setNote}
                            taxRate={taxRate}
                            onChangeTaxRate={setTaxRate}
                            unitPrice={unitPrice}
                            onChangeUnitPrice={setUnitPrice}
                            fuelRecords={fuelRecords}
                        />
                    ) : (
                        <div className="text-center flex flex-col items-center justify-center text-slate-500 pt-20">
                            <FileText size={48} className="mb-4 opacity-30" />
                            <p className="text-lg font-medium text-[var(--text-primary)] mb-2">Önizleme Yok</p>
                            <p className="text-sm">Sol taraftaki menüden "Yeni Fatura Periyodu Seç" butonuna tıklayarak taslak oluşturun.</p>
                        </div>
                    )}
                </div>
            </div>

            <InvoicePeriodModal
                isOpen={isPeriodModalOpen}
                onClose={() => setIsPeriodModalOpen(false)}
                trips={availableTrips}
                allTrips={trips}
                lastInvoiceEndDate={lastInvoiceEndDate}
                onSelectPeriod={handleSelectPeriod}
                fuelRecords={fuelRecords}
            />

            {/* Not & Belge Modal */}
            {noteModalInvoice && (
                <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 backdrop-blur-sm" onClick={() => setNoteModalInvoice(null)}>
                    <div className="bg-[var(--bg-panel)] border border-[var(--border-color)] rounded-2xl p-6 w-full max-w-md mx-4 shadow-2xl space-y-4" onClick={e => e.stopPropagation()}>
                        <div className="flex justify-between items-center">
                            <h3 className="font-bold text-[var(--text-primary)] flex items-center gap-2">
                                <StickyNote size={16} className="text-brand-400" />
                                {noteModalInvoice.docId} — Not & Belge
                            </h3>
                            <button onClick={() => setNoteModalInvoice(null)} className="text-slate-500 hover:text-[var(--text-primary)] transition-colors">✕</button>
                        </div>
                        <textarea
                            rows={4}
                            placeholder="Not ekle... (örn: ödeme tarihi, onay notu, müşteri yorumu)"
                            className="w-full bg-[var(--bg-panel-hover)] border border-[var(--border-color)] text-[var(--text-primary)] rounded-lg px-3 py-2 text-sm resize-none outline-none focus:border-brand-500"
                            value={modalNote}
                            onChange={e => setModalNote(e.target.value)}
                        />
                        <div>
                            <p className="text-xs text-slate-500 mb-2 flex items-center gap-1"><Paperclip size={11} /> Onay Belgesi / Fotoğraf / PDF</p>
                            <FileUpload files={modalFiles} onChange={setModalFiles} maxSizeMB={10} />
                        </div>
                        <button
                            onClick={async () => {
                                setIsSavingNote(true);
                                try {
                                    await updateInvoice(noteModalInvoice.id, { note: modalNote, files: modalFiles });
                                    addLog('FATURA_NOT', `${noteModalInvoice.docId} notları güncellendi`);
                                    setNoteModalInvoice(null);
                                } catch (e) { console.error(e); }
                                setIsSavingNote(false);
                            }}
                            disabled={isSavingNote}
                            className="w-full bg-brand-600 hover:bg-brand-500 disabled:opacity-50 text-[var(--text-primary)] py-2.5 rounded-xl font-medium text-sm transition-colors flex items-center justify-center gap-2"
                        >
                            <Save size={14} /> {isSavingNote ? 'Kaydediliyor...' : 'Kaydet'}
                        </button>
                    </div>
                </div>
            )}
        </div>
    );
};

export default Invoices;

import React, { useState, useContext } from 'react';
import { DataContext } from '../context/DataContext';
import { User, Lock, Eye, EyeOff, AlertCircle, UserPlus, ChevronLeft } from 'lucide-react';
import { db } from '../services/firebaseConfig';
import { collection, query, where, getDocs, addDoc } from 'firebase/firestore';

const ADMIN_USER = { username: 'kenan', password: 'Newrules1.', role: 'super_admin', displayName: 'Kenan (Admin)' };

const Login = () => {
    const { pendingUsers, registerUser, loginSession } = useContext(DataContext);
    const [mode, setMode] = useState('login'); // 'login' | 'register' | 'pending'
    const [username, setUsername] = useState('');
    const [password, setPassword] = useState('');
    const [confirmPassword, setConfirmPassword] = useState('');
    const [showPassword, setShowPassword] = useState(false);
    const [error, setError] = useState('');
    const [loading, setLoading] = useState(false);
    const [failCount, setFailCount] = useState(0);
    const [showVideo, setShowVideo] = useState(false);

    const handleLogin = async (e) => {
        e.preventDefault();
        setError('');
        setLoading(true);
        await new Promise(r => setTimeout(r, 500));

        let ip = 'Bilinmiyor';
        try {
            const ipRes = await fetch('https://api.ipify.org?format=json');
            const ipData = await ipRes.json();
            ip = ipData.ip;
        } catch (err) {
            console.log('IP alınamadı: ', err);
        }

        const device = navigator.userAgent;
        const uname = username.toLowerCase().trim();

        // Admin kontrolü
        if (uname === ADMIN_USER.username && password === ADMIN_USER.password) {
            localStorage.setItem('tir_auth_kenan_v1', btoa(`${uname}:${Date.now()}`));
            localStorage.setItem('tir_active_tab', 'dashboard');
            loginSession({ username: uname, role: ADMIN_USER.role, ip, device });
            window.location.href = '/';
            return;
        }

        // Firestore'dan doğrudan kullanıcı kontrolü (Login.jsx'te DataContext'e güvenmiyoruz çünkü session olmadan data yüklenmez)
        try {
            const usersRef = collection(db, 'approved_users');
            const q = query(usersRef, where('username', '==', uname));
            const querySnapshot = await getDocs(q);

            if (!querySnapshot.empty) {
                const userDoc = querySnapshot.docs[0].data();
                const hashedInputPassword = btoa(password);
                if (userDoc.password === hashedInputPassword || userDoc.password === password) {
                    localStorage.setItem('tir_auth_kenan_v1', btoa(`${uname}:${Date.now()}`));
                    localStorage.setItem('tir_active_tab', 'dashboard');
                    // Company admin vs. rolüne göre loginSession'a data gönderiliyor
                    loginSession({ username: uname, role: userDoc.role || 'user', companyId: userDoc.companyId, ip, device });
                    window.location.href = '/';
                    return;
                }
            }

            // Bekleyen kullanıcı kontrolü
            const pendingRef = collection(db, 'pending_users');
            const pq = query(pendingRef, where('username', '==', uname));
            const pSnapshot = await getDocs(pq);
            if (!pSnapshot.empty) {
                setError('Hesabınız henüz admin tarafından onaylanmadı. Lütfen bekleyin.');
                setLoading(false);
                return;
            }

        } catch (dbErr) {
            console.error("Giriş kontrolü sırasında veritabanı hatası: ", dbErr);
            setError('Sunucu bağlantı hatası. Lütfen daha sonra tekrar deneyin.');
            setLoading(false);
            return;
        }

        setError('Kullanıcı adı veya şifre hatalı.');
        const newFailCount = failCount + 1;
        if (newFailCount >= 4) {
            setShowVideo(true);
            setFailCount(0);
            // 33 saniye sonra otomatik kapat (Video süresine göre ayarlandı)
            setTimeout(() => setShowVideo(false), 33000);
        } else {
            setFailCount(newFailCount);
        }
        setLoading(false);
    };

    const handleRegister = async (e) => {
        e.preventDefault();
        setError('');
        if (password !== confirmPassword) { setError('Şifreler eşleşmiyor.'); return; }
        if (password.length < 4) { setError('Şifre en az 4 karakter olmalı.'); return; }

        const uname = username.toLowerCase().trim();
        if (uname === ADMIN_USER.username) { setError('Bu kullanıcı adı kullanılamaz.'); return; }

        setLoading(true);
        await new Promise(r => setTimeout(r, 400));

        try {
            // Check if username already exists in DB
            const usersRef = collection(db, 'approved_users');
            const q1 = query(usersRef, where('username', '==', uname));
            const snap1 = await getDocs(q1);

            const pendingRef = collection(db, 'pending_users');
            const q2 = query(pendingRef, where('username', '==', uname));
            const snap2 = await getDocs(q2);

            if (!snap1.empty || !snap2.empty) {
                setError('Bu kullanıcı adı zaten alınmış.');
                setLoading(false);
                return;
            }

            // Şifreyi açık metin (plaintext) olarak saklıyoruz (user isteği üzerine btoa kaldırıldı)
            await addDoc(collection(db, 'pending_users'), {
                username: uname,
                password: password,
                role: 'user',
                createdAt: new Date().toISOString()
            });

            setLoading(false);
            setMode('pending');

        } catch (err) {
            console.error(err);
            setError('Kayıt oluşturulurken bir hata oluştu');
            setLoading(false);
        }
    };

    return (
        <div
            className="min-h-screen w-full relative overflow-hidden bg-[var(--bg-base)] bg-cover bg-top"
            style={{
                backgroundImage: `linear-gradient(rgba(10, 18, 35, 0.55), rgba(2, 6, 23, 0.85)), url('/arkaplan123.jpg')`,
                backgroundSize: 'cover',
                backgroundPosition: 'center center'
            }}
        >
            {/* Ortadaki/Üstteki Yazı */}
            <div className="absolute top-20 md:top-32 left-0 right-0 flex flex-col items-center justify-center pointer-events-none z-0 px-4">
                <h1 className="text-4xl sm:text-5xl md:text-7xl font-extralight tracking-[0.2em] text-[var(--text-primary)]/90 text-center uppercase"
                    style={{
                        textShadow: '0 2px 10px rgba(0,0,0,0.4)',
                    }}>
                    İNANER LOJİSTİK
                </h1>
            </div>

            {/* Sol Alttaki Login Kutusu */}
            <div className="absolute bottom-6 left-6 md:bottom-10 md:left-10 z-10 w-[280px]">
                <div style={{ background: 'rgba(15,23,42,0.7)', border: '1px solid rgba(255,255,255,0.1)', backdropFilter: 'blur(16px)' }}
                    className="rounded-xl p-5 shadow-2xl relative overflow-hidden">

                    <div className="absolute inset-0 bg-gradient-to-br from-white/5 to-transparent pointer-events-none" />

                    <div className="relative z-10">
                        {/* Onay Bekliyor */}
                        {mode === 'pending' && (
                            <div className="text-center py-2 space-y-3">
                                <div className="w-12 h-12 bg-amber-500/20 rounded-full flex items-center justify-center mx-auto">
                                    <UserPlus size={20} className="text-amber-400" />
                                </div>
                                <h2 className="text-base font-semibold text-[var(--text-primary)]">Başvurunuz Alındı</h2>
                                <p className="text-[var(--text-secondary)] text-xs">Admin onayından sonra giriş yapabilirsiniz.</p>
                                <button onClick={() => { setMode('login'); setUsername(''); setPassword(''); }}
                                    className="text-brand-400 text-xs hover:underline">Giriş ekranına dön</button>
                            </div>
                        )}

                        {/* Giriş */}
                        {mode === 'login' && (
                            <>
                                <h2 className="text-base font-semibold text-[var(--text-primary)] mb-4">Giriş Yap</h2>
                                <form onSubmit={handleLogin} className="space-y-3">
                                    <div>
                                        <label className="block text-xs text-[var(--text-secondary)] mb-1">Kullanıcı Adı</label>
                                        <div className="relative">
                                            <User size={14} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-500" />
                                            <input type="text" autoComplete="username" placeholder="kullanici_adi" value={username}
                                                onChange={e => setUsername(e.target.value)} className="w-full glass-input text-sm pl-9 pr-3 py-2" required />
                                        </div>
                                    </div>
                                    <div>
                                        <label className="block text-xs text-[var(--text-secondary)] mb-1">Şifre</label>
                                        <div className="relative">
                                            <Lock size={14} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-500" />
                                            <input type={showPassword ? 'text' : 'password'} autoComplete="current-password" placeholder="••••••"
                                                value={password} onChange={e => setPassword(e.target.value)}
                                                className="w-full glass-input text-sm pl-9 pr-9 py-2" required />
                                            <button type="button" onClick={() => setShowPassword(!showPassword)}
                                                className="absolute right-3 top-1/2 -translate-y-1/2 text-slate-500 hover:text-[var(--text-primary)] transition-colors">
                                                {showPassword ? <EyeOff size={14} /> : <Eye size={14} />}
                                            </button>
                                        </div>
                                    </div>
                                    {error && (
                                        <div className="flex items-center gap-1.5 text-red-400 text-xs bg-red-500/10 border border-red-500/20 rounded-md px-2 py-1.5">
                                            <AlertCircle size={12} /> {error}
                                        </div>
                                    )}
                                    <button type="submit" disabled={loading}
                                        className="w-full bg-brand-600 hover:bg-brand-500 disabled:bg-brand-800 disabled:cursor-not-allowed text-[var(--text-primary)] text-sm font-medium py-2 rounded-lg transition-all shadow-lg flex items-center justify-center gap-2 mt-2">
                                        {loading ? <div className="w-4 h-4 border-2 border-[var(--border-color)] border-t-white rounded-full animate-spin" /> : 'Giriş Yap'}
                                    </button>
                                    <button type="button" onClick={() => { setMode('register'); setError(''); }}
                                        className="w-full text-[var(--text-secondary)] hover:text-[var(--text-primary)] text-xs py-1 transition-colors flex items-center justify-center gap-1 mt-1">
                                        <UserPlus size={12} /> Yeni Hesap Oluştur
                                    </button>
                                </form>
                            </>
                        )}

                        {/* Kayıt */}
                        {mode === 'register' && (
                            <>
                                <div className="flex items-center gap-2 mb-4">
                                    <button onClick={() => { setMode('login'); setError(''); }}
                                        className="text-[var(--text-secondary)] hover:text-[var(--text-primary)] p-1 rounded transition">
                                        <ChevronLeft size={16} />
                                    </button>
                                    <h2 className="text-base font-semibold text-[var(--text-primary)]">Yeni Hesap</h2>
                                </div>
                                <p className="text-slate-500 text-[10px] mb-3 bg-amber-500/10 border border-amber-500/20 rounded-md px-2 py-1.5 text-amber-400">
                                    ⚠️ Hesabınız admin onayından sonra aktif olur.
                                </p>
                                <form onSubmit={handleRegister} className="space-y-3">
                                    <div>
                                        <label className="block text-xs text-[var(--text-secondary)] mb-1">Kullanıcı Adı</label>
                                        <div className="relative">
                                            <User size={14} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-500" />
                                            <input type="text" placeholder="kullanici_adi" value={username}
                                                onChange={e => setUsername(e.target.value)} className="w-full glass-input text-sm pl-9 pr-3 py-2" required />
                                        </div>
                                    </div>
                                    <div>
                                        <label className="block text-xs text-[var(--text-secondary)] mb-1">Şifre</label>
                                        <div className="relative">
                                            <Lock size={14} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-500" />
                                            <input type={showPassword ? 'text' : 'password'} placeholder="••••••"
                                                value={password} onChange={e => setPassword(e.target.value)}
                                                className="w-full glass-input text-sm pl-9 pr-9 py-2" required />
                                            <button type="button" onClick={() => setShowPassword(!showPassword)}
                                                className="absolute right-3 top-1/2 -translate-y-1/2 text-slate-500 hover:text-[var(--text-primary)]">
                                                {showPassword ? <EyeOff size={14} /> : <Eye size={14} />}
                                            </button>
                                        </div>
                                    </div>
                                    <div>
                                        <label className="block text-xs text-[var(--text-secondary)] mb-1">Şifre Tekrar</label>
                                        <div className="relative">
                                            <Lock size={14} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-500" />
                                            <input type="password" placeholder="••••••"
                                                value={confirmPassword} onChange={e => setConfirmPassword(e.target.value)}
                                                className="w-full glass-input text-sm pl-9 pr-3 py-2" required />
                                        </div>
                                    </div>
                                    {error && (
                                        <div className="flex items-center gap-1.5 text-red-400 text-xs bg-red-500/10 border border-red-500/20 rounded-md px-2 py-1.5">
                                            <AlertCircle size={12} /> {error}
                                        </div>
                                    )}
                                    <button type="submit" disabled={loading}
                                        className="w-full bg-brand-600 hover:bg-brand-500 disabled:bg-brand-800 text-[var(--text-primary)] text-sm font-medium py-2 rounded-lg transition-all flex items-center justify-center gap-2 mt-2">
                                        {loading ? <div className="w-4 h-4 border-2 border-[var(--border-color)] border-t-white rounded-full animate-spin" /> : 'Başvuru Gönder'}
                                    </button>
                                </form>
                            </>
                        )}
                    </div>
                </div>
                <p className="text-left text-[var(--text-primary)]/50 text-[10px] mt-2 ml-1">İnaner Lojistik © 2026</p>
            </div>

            {/* Yanlış Giriş YouTube Easter Egg */}
            {showVideo && (
                <div className="fixed inset-0 z-[100] bg-black flex flex-col items-center justify-center animate-in fade-in zoom-in duration-500">
                    <div className="absolute top-6 right-6 z-[110]">
                        <button
                            onClick={() => setShowVideo(false)}
                            className="bg-white/10 hover:bg-white/20 text-[var(--text-primary)] px-4 py-2 rounded-lg backdrop-blur-md border border-[var(--border-color)] transition-all text-sm font-bold"
                        >
                            Kapat (X)
                        </button>
                    </div>
                    <div className="w-full h-full p-4 md:p-10">
                        <iframe
                            width="100%"
                            height="100%"
                            src="https://www.youtube.com/embed/TZdY5TV-CNM?autoplay=1&controls=0&rel=0"
                            title="İnaner Lojistik"
                            frameBorder="0"
                            allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share"
                            allowFullScreen
                            className="rounded-2xl shadow-2xl border border-[var(--border-color)]"
                        ></iframe>
                    </div>
                    <div className="absolute bottom-10 text-[var(--text-primary)]/40 text-xs tracking-widest uppercase">
                        Çok fazla hatalı deneme yaptınız... biraz dinlenin.
                    </div>
                </div>
            )}
        </div>
    );
};

