import React, { useState, useContext } from 'react';
import { Wrench, Plus, Calendar, X, MapPin, Truck, Trash2, Pencil, Check, User, Users, FileText, StickyNote, AlertCircle, ChevronDown, Download, Eye, Paperclip, FolderOpen, FolderPlus, Map, Phone, Package } from 'lucide-react';
import { DataContext } from '../context/DataContext';
import { useTruck } from '../context/TruckContext';
import { db } from '../services/firebaseConfig';
import { doc, updateDoc, deleteDoc } from 'firebase/firestore';
import FileUpload from './FileUpload';

const MAINTENANCE_TYPES = ['Periyodik Bakım', 'Lastik', 'Motor', 'Fren', 'Şanzıman', 'Elektrik', 'Kaporta', 'Diğer'];

const Maintenance = () => {
    const {
        maintenanceRecords, addMaintenance, deleteMaintenance, updateMaintenance,
        mechanics, addMechanic, deleteMechanic, updateMechanic,
        maintenanceFolders, addMaintenanceFolder, updateMaintenanceFolder, deleteMaintenanceFolder,
        drivers, allDrivers, updateDrivers, approvedUsers, // Added approvedUsers here
        spareParts, addSparePart, updateSparePart, deleteSparePart,
        sparePartCategories, addSparePartCategory,
        addLog, docs
    } = useContext(DataContext);

    const { activeTruckId, activeTruckData } = useTruck();

    const [activeTab, setActiveTab] = useState('info'); // 'info', 'records', 'mechanics', 'photos'
    const [viewFiles, setViewFiles] = useState(null);
    const [deleteConfirm, setDeleteConfirm] = useState(null);

    // ─── Araç Bilgileri Edit State ───────────────────────────────────────────
    const [editingField, setEditingField] = useState(null);
    const [editValue, setEditValue] = useState('');

    const [showDriverForm, setShowDriverForm] = useState(false);
    const [driverForm, setDriverForm] = useState({ name: '', phone: '' });

    const saveDrivers = (d) => {
        if (updateDrivers) updateDrivers(d);
    };

    const handleDeleteDriverEntry = async (driver) => {
        // Eğer id yoksa (eski usul manuel liste ise ismine göre sil)
        if (driver.isSystem) {
            if (window.confirm(`${driver.name} adlı sistem kullanıcısını (şoför) tamamen silmek istediğinize emin misiniz?`)) {
                try {
                    await deleteDoc(doc(db, 'approved_users', driver.id));
                    addLog('KULLANICI_SİL', `${driver.name} (Sistem Kullanıcısı) silindi`);
                } catch (error) {
                    console.error(error);
                    alert("Hata: " + error.message);
                }
            }
        } else {
            if (window.confirm(`${driver.name} adlı şoför kaydını listeden silmek istiyor musunuz?`)) {
                try {
                    const newDrivers = (drivers || []).filter(d => d.name !== driver.name);
                    await updateDrivers(newDrivers);
                    addLog('SOFOR_KAYDI_SIL', `${driver.name} (Manuel Kayıt) silindi`);
                } catch (error) {
                    console.error(error);
                    alert("Hata: " + error.message);
                }
            }
        }
    };

    // ─── Tamir Notları ────────────────────────────────────────────────────────
    const [repairNotes, setRepairNotes] = useState(() => {
        try { return JSON.parse(localStorage.getItem('tir_repair_notes')) || []; }
        catch { return []; }
    });
    const [noteText, setNoteText] = useState('');

    const saveNote = () => {
        if (!noteText.trim()) return;
        const newNotes = [{ id: Date.now(), text: noteText.trim(), date: new Date().toISOString() }, ...repairNotes];
        setRepairNotes(newNotes);
        localStorage.setItem('tir_repair_notes', JSON.stringify(newNotes));
        addLog('NOT_EKLE', noteText.trim().slice(0, 60));
        setNoteText('');
    };

    const deleteNote = (id) => {
        const newNotes = repairNotes.filter(n => n.id !== id);
        setRepairNotes(newNotes);
        localStorage.setItem('tir_repair_notes', JSON.stringify(newNotes));
    };

    // ─── Bakım Ekleme ──────────────────────────────────────────────────────────
    const [isMaintenanceModalOpen, setIsMaintenanceModalOpen] = useState(false);
    const [editingMaintenanceId, setEditingMaintenanceId] = useState(null);
    const [maintenanceForm, setMaintenanceForm] = useState({
        date: new Date().toISOString().split('T')[0],
        type: 'Periyodik Bakım', description: '', mechanicId: '', km: '', cost: '', files: []
    });

    // ─── Tamirci Ekleme ────────────────────────────────────────────────────────
    const [isMechanicModalOpen, setIsMechanicModalOpen] = useState(false);
    const [editingMechanicId, setEditingMechanicId] = useState(null);
    const [mechanicForm, setMechanicForm] = useState({ name: '', masterName: '', phone: '', location: '', mapLink: '', notes: '', type: 'Genel Bakım' });

    // ─── Albüm (Klasör) Ekleme ──────────────────────────────────────────────────
    const [isFolderModalOpen, setIsFolderModalOpen] = useState(false);
    const [folderForm, setFolderForm] = useState({ name: '', description: '', files: [] });
    const [editingFolderId, setEditingFolderId] = useState(null);
    const [openedFolder, setOpenedFolder] = useState(null);

    const handleSaveFolder = (e) => {
        e.preventDefault();
        if (editingFolderId) {
            updateMaintenanceFolder(editingFolderId, folderForm);
        } else {
            addMaintenanceFolder(folderForm);
        }
        setIsFolderModalOpen(false);
        setEditingFolderId(null);
        setFolderForm({ name: '', description: '', files: [] });
    };

    const handleDeleteFolder = (id, e) => {
        e.stopPropagation();
        const f = maintenanceFolders.find(f => f.id === id);
        deleteMaintenanceFolder(id, f ? f.name : '');
        if (openedFolder?.id === id) setOpenedFolder(null);
    };

    const handleAddMaintenance = (e) => {
        e.preventDefault();
        const mechanic = mechanics.find(m => m.id === maintenanceForm.mechanicId); // Note: mechanicId could be string, checking later. 
        const payload = {
            date: maintenanceForm.date,
            type: maintenanceForm.type,
            description: maintenanceForm.description,
            mechanicName: mechanic ? mechanic.name : 'Belirtilmedi',
            km: parseInt(maintenanceForm.km) || 0,
            cost: parseFloat(maintenanceForm.cost),
            files: maintenanceForm.files
        };

        if (editingMaintenanceId) {
            updateMaintenance(editingMaintenanceId, payload);
        } else {
            addMaintenance(payload);
        }

        setIsMaintenanceModalOpen(false);
        setEditingMaintenanceId(null);
        setMaintenanceForm({ date: new Date().toISOString().split('T')[0], type: 'Periyodik Bakım', description: '', mechanicId: '', km: '', cost: '', files: [] });
    };

    const handleDeleteMaintenance = (id) => {
        deleteMaintenance(id);
    };

    const handleAddMechanic = (e) => {
        e.preventDefault();
        if (editingMechanicId) {
            if (updateMechanic) updateMechanic(editingMechanicId, mechanicForm);
        } else {
            addMechanic(mechanicForm);
        }
        setIsMechanicModalOpen(false);
        setEditingMechanicId(null);
        setMechanicForm({ name: '', masterName: '', phone: '', location: '', mapLink: '', notes: '', type: 'Genel Bakım' });
    };

    // Field edit helpers
    const startEdit = (field, val) => { setEditingField(field); setEditValue(val || ''); };
    const saveEdit = async (field) => {
        if (!activeTruckId) return;
        try {
            await updateDoc(doc(db, 'trucks', activeTruckId), {
                [field]: editValue
            });
            setEditingField(null);
        } catch (error) {
            console.error(error);
        }
    };

    const activeMaintenanceRecords = maintenanceRecords.filter(r => !r.deleted);
    const totalCost = activeMaintenanceRecords.reduce((acc, r) => acc + r.cost, 0);

    const tabs = [
        { id: 'info', label: 'Araç Bilgileri', icon: <Truck size={16} /> },
        { id: 'records', label: 'Bakım Kayıları', icon: <Wrench size={16} /> },
        { id: 'stock', label: 'Stok / Parça', icon: <Package size={16} /> },
        { id: 'mechanics', label: 'Servis Rehberi', icon: <MapPin size={16} /> },
        { id: 'photos', label: 'Fotoğraflar', icon: <FolderOpen size={16} /> },
    ];

    const [isStockModalOpen, setIsStockModalOpen] = useState(false);
    const [editingStockId, setEditingStockId] = useState(null);
    const [stockForm, setStockForm] = useState({ name: '', category: 'Genel', count: '', price: '', notes: '', files: [] });
    const [showNewCategoryInput, setShowNewCategoryInput] = useState(false);
    const [newCategoryName, setNewCategoryName] = useState('');

    const handleAddStock = (e) => {
        e.preventDefault();
        let selectedCategory = stockForm.category;

        if (showNewCategoryInput && newCategoryName) {
            addSparePartCategory(newCategoryName);
            selectedCategory = newCategoryName;
        }

        const payload = {
            name: stockForm.name,
            category: selectedCategory,
            count: parseInt(stockForm.count) || 1,
            price: parseFloat(stockForm.price) || 0,
            notes: stockForm.notes,
            files: stockForm.files || []
        };

        if (editingStockId) {
            updateSparePart(editingStockId, payload);
        } else {
            addSparePart(payload);
        }

        setIsStockModalOpen(false);
        setEditingStockId(null);
        setStockForm({ name: '', category: sparePartCategories ? sparePartCategories[0] : 'Genel', count: '', price: '', notes: '', files: [] });
        setShowNewCategoryInput(false);
        setNewCategoryName('');
    };

    return (
        <div className="space-y-5 animate-in fade-in duration-500 relative pb-ios-nav">

            {/* Tab Bar */}
            <div className="flex gap-1 bg-white/5 p-1 rounded-xl flex-wrap">
                {tabs.map(tab => (
                    <button key={tab.id} onClick={() => setActiveTab(tab.id)}
                        className={`flex items-center gap-1.5 px-3 py-2 rounded-lg text-sm font-medium transition-all flex-1 justify-center whitespace-nowrap ${activeTab === tab.id ? 'bg-brand-500/20 text-brand-300 border border-brand-500/30' : 'text-[var(--text-secondary)] hover:text-[var(--text-primary)]'}`}>
                        {tab.icon} {tab.label}
                    </button>
                ))}
            </div>

            {/* ─── ARAÇ BİLGİLERİ ─── */}
            {activeTab === 'info' && (
                <div className="space-y-4">
                    <div className="glass-panel p-5">
                        <h3 className="font-bold text-[var(--text-primary)] mb-4 flex items-center gap-2"><Truck size={18} className="text-brand-400" /> Araç Bilgileri</h3>
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                            {[
                                { key: 'plate', label: 'Çekici Plakası', src: 'truck' },
                                { key: 'trailerPlate', label: 'Dorse Plakası', src: 'truck' },
                                { key: 'brand', label: 'Model & Marka', src: 'truck' },
                                { key: 'inspection', label: 'Çekici Muayene Tarihi', src: 'docs' },
                                { key: 'trailerInspection', label: 'Dorse Muayene Tarihi', src: 'docs' },
                                { key: 'odp', label: 'Sigorta Bitiş Tarihi', src: 'docs' },
                            ].map(field => {
                                const isDoc = field.src === 'docs';
                                const rawValue = isDoc ? (docs?.[field.key]?.date || '') : (activeTruckData?.[field.key] || '');
                                const displayValue = (isDoc && rawValue) ? rawValue.split('-').reverse().join('.') : rawValue;

                                return (
                                    <div key={field.key} className="flex items-center justify-between gap-2 bg-white/5 rounded-xl p-3">
                                        <div className="flex-1 min-w-0">
                                            <p className="text-xs text-slate-500 mb-0.5">{field.label}</p>
                                            {(!isDoc && editingField === field.key) ? (
                                                <div className="flex items-center gap-2 mt-1">
                                                    <input type={field.type || 'text'} value={editValue}
                                                        onChange={e => setEditValue(e.target.value)}
                                                        className="glass-input px-2 py-1 text-sm flex-1" autoFocus />
                                                    <button onClick={() => saveEdit(field.key)} className="text-emerald-400 hover:text-emerald-300 p-1">
                                                        <Check size={16} />
                                                    </button>
                                                    <button onClick={() => setEditingField(null)} className="text-slate-500 hover:text-[var(--text-primary)] p-1">
                                                        <X size={16} />
                                                    </button>
                                                </div>
                                            ) : (
                                                <p className="text-[var(--text-primary)] font-semibold text-sm truncate">{displayValue || '—'}</p>
                                            )}
                                        </div>
                                        {!isDoc && editingField !== field.key && (
                                            <button onClick={() => startEdit(field.key, rawValue)}
                                                className="text-slate-600 hover:text-brand-400 p-1 rounded transition flex-shrink-0">
                                                <Pencil size={14} />
                                            </button>
                                        )}
                                        {isDoc && (
                                            <div className="text-slate-600 p-1 flex-shrink-0" title="Ceza ve Belgeler sekmesinden düzenleyin">
                                                <FileText size={14} className="opacity-50 hover:opacity-100 transition-opacity" />
                                            </div>
                                        )}
                                    </div>
                                );
                            })}
                        </div>
                    </div>

                    {/* Şoförler */}
                    <div className="glass-panel p-5">
                        <div className="flex items-center justify-between mb-4">
                            <h3 className="font-bold text-[var(--text-primary)] flex items-center gap-2"><Users size={18} className="text-brand-400" /> Şoförler</h3>
                            <span className="text-[10px] text-slate-500 italic">Admin Paneli &gt; Kullanıcılar &gt; Yeni Kullanıcı &gt; Rol: Şoför</span>
                        </div>

                        <div className="space-y-2">
                            {(allDrivers && allDrivers.length > 0) ? allDrivers.map((d, i) => (
                                <div key={d.id || i} className="flex items-center gap-3 bg-white/5 rounded-xl px-3 py-2 border border-transparent hover:border-white/10 transition-colors">
                                    <div className="bg-brand-500/20 p-1.5 rounded-lg">
                                        <User size={14} className="text-brand-400" />
                                    </div>
                                    <div className="flex-1 min-w-0">
                                        <p className="text-[var(--text-primary)] text-sm font-medium truncate">{d.name}</p>
                                        {d.phone && <p className="text-slate-500 text-xs">{d.phone}</p>}
                                    </div>
                                    <button
                                        onClick={() => handleDeleteDriverEntry(d)}
                                        className="p-2 text-slate-500 hover:text-red-400 hover:bg-red-500/10 rounded-lg transition-all flex-shrink-0"
                                        title="Şoförü Sil"
                                    >
                                        <Trash2 size={16} />
                                    </button>
                                    <span className="text-[10px] bg-brand-500/10 text-brand-400 border border-brand-500/20 px-2 py-0.5 rounded-full flex-shrink-0">
                                        Şoför
                                    </span>
                                </div>
                            )) : (
                                <div className="text-slate-500 text-sm text-center py-6 bg-white/5 rounded-xl border border-dashed border-[var(--border-color)]">
                                    <User size={20} className="mx-auto mb-2 text-slate-600" />
                                    <p>Bu şirkete atanmış şoför yok.</p>
                                    <p className="text-xs mt-1 text-slate-600">Admin Paneli &gt; Kullanıcılar &gt; Yeni Kullanıcı &gt; Rol: Şoför</p>
                                </div>
                            )}
                        </div>
                    </div>
                </div>
            )}

            {/* ─── BAKIM KAYITLARI ─── */}
            {activeTab === 'records' && (
                <div className="space-y-4">
                    <div className="flex justify-between items-center gap-4 flex-wrap">
                        <div className="glass-panel px-4 py-2 flex items-center gap-3">
                            <div className="bg-amber-500/20 p-2 rounded-lg text-amber-400"><Wrench size={16} /></div>
                            <div>
                                <p className="text-xs text-[var(--text-secondary)]">Toplam Bakım Gideri</p>
                                <p className="font-bold text-[var(--text-primary)]">₺{totalCost.toLocaleString('tr-TR', { minimumFractionDigits: 2 })}</p>
                            </div>
                        </div>
                        <button onClick={() => {
                            setEditingMaintenanceId(null);
                            setMaintenanceForm({ date: new Date().toISOString().split('T')[0], type: 'Periyodik Bakım', description: '', mechanicId: '', km: '', cost: '', files: [] });
                            setIsMaintenanceModalOpen(true);
                        }}
                            className="bg-amber-600 hover:bg-amber-500 text-[var(--text-primary)] px-4 py-2 rounded-lg font-medium transition-all flex items-center gap-2">
                            <Plus size={18} /> Bakım Ekle
                        </button>
                    </div>

                    <div className="glass-panel overflow-hidden">
                        <div className="overflow-x-auto">
                            <table className="w-full border-collapse" style={{ minWidth: '480px' }}>
                                <thead>
                                    <tr className="bg-white/5 border-b border-[var(--border-color)] text-[var(--text-secondary)] text-xs uppercase tracking-wide">
                                        <th className="p-3 pl-4 text-left">Tarih</th>
                                        <th className="p-3 text-left">Tür</th>
                                        <th className="p-3 text-left">Açıklama</th>
                                        <th className="p-3 text-center">KM</th>
                                        <th className="p-3 text-right">Tutar</th>
                                        <th className="p-3 text-center">Ekler</th>
                                        <th className="p-3 text-center w-24">İşlemler</th>
                                    </tr>
                                </thead>
                                <tbody className="divide-y divide-white/5">
                                    {activeMaintenanceRecords.length > 0 ? activeMaintenanceRecords.map(rec => (
                                        <tr key={rec.id} className="hover:bg-white/5 transition-colors group">
                                            <td className="p-3 pl-4 text-[var(--text-primary)] text-sm whitespace-nowrap">{new Date(rec.date).toLocaleDateString('tr-TR')}</td>
                                            <td className="p-3">
                                                <span className="bg-amber-500/10 text-amber-400 border border-amber-500/20 text-xs px-2 py-0.5 rounded-full whitespace-nowrap">{rec.type}</span>
                                            </td>
                                            <td className="p-3 text-[var(--text-primary)] text-sm">
                                                <div>{rec.description}</div>
                                                {rec.mechanicName && rec.mechanicName !== 'Belirtilmedi' && (
                                                    <div className="text-xs text-slate-500 mt-0.5 flex items-center gap-1">
                                                        <MapPin size={10} /> {rec.mechanicName}
                                                    </div>
                                                )}
                                            </td>
                                            <td className="p-3 text-center text-[var(--text-secondary)] text-sm">{rec.km > 0 ? `${rec.km.toLocaleString()} km` : '—'}</td>
                                            <td className="p-3 text-right text-amber-400 font-bold text-sm">₺{rec.cost.toLocaleString('tr-TR', { minimumFractionDigits: 2 })}</td>
                                            <td className="p-3 text-center">
                                                {rec.files && rec.files.length > 0 ? (
                                                    <button onClick={() => setViewFiles({ title: rec.description || 'Bakım Kaydı', files: rec.files })}
                                                        className="text-xs text-brand-400 hover:text-brand-300 flex items-center justify-center gap-1 transition-colors whitespace-nowrap mx-auto">
                                                        <Paperclip size={11} /> {rec.files.length} Ek
                                                    </button>
                                                ) : <span className="text-slate-700">—</span>}
                                            </td>
                                            <td className="p-3 text-center">
                                                <div className="flex justify-center gap-1 opacity-100 md:opacity-0 group-hover:opacity-100 transition-opacity">
                                                    <button onClick={() => {
                                                        const matchedMechanic = mechanics.find(m => m.name === rec.mechanicName);
                                                        setEditingMaintenanceId(rec.id);
                                                        setMaintenanceForm({
                                                            date: rec.date || new Date().toISOString().split('T')[0],
                                                            type: rec.type || 'Periyodik Bakım',
                                                            description: rec.description || '',
                                                            mechanicId: matchedMechanic ? matchedMechanic.id : '',
                                                            km: rec.km || '',
                                                            cost: rec.cost || '',
                                                            files: rec.files || []
                                                        });
                                                        setIsMaintenanceModalOpen(true);
                                                    }}
                                                        className="p-1.5 rounded-lg transition-all text-slate-600 hover:text-amber-400 hover:bg-amber-500/10">
                                                        <Pencil size={14} />
                                                    </button>
                                                    <button onClick={() => handleDeleteMaintenance(rec.id)}
                                                        className="p-1.5 rounded-lg transition-all text-slate-600 hover:text-red-400 hover:bg-red-500/10">
                                                        <Trash2 size={14} />
                                                    </button>
                                                </div>
                                            </td>
                                        </tr>
                                    )) : (
                                        <tr><td colSpan="6" className="p-8 text-center text-slate-500">
                                            <Wrench size={32} className="mx-auto mb-3 opacity-30" />
                                            <p className="text-[var(--text-secondary)] font-medium">Henüz Bakım Kaydı Yok</p>
                                        </td></tr>
                                    )}
                                </tbody>
                            </table>
                        </div>
                    </div>
                </div>
            )}

            {/* ─── STOK / YEDEK PARÇA ─── */}
            {activeTab === 'stock' && (
                <div className="space-y-4">
                    <div className="flex justify-between items-center bg-brand-500/10 p-3 rounded-xl border border-brand-500/20">
                        <div className="flex items-center gap-2 text-brand-400">
                            <Package size={18} />
                            <span className="text-sm font-medium">Elinizdeki yedek parçaları ve bakım malzemelerini takip edin.</span>
                        </div>
                        <button onClick={() => {
                            setEditingStockId(null);
                            setStockForm({ name: '', category: (sparePartCategories && sparePartCategories.length > 0) ? sparePartCategories[0] : 'Genel', count: '', price: '', notes: '', files: [] });
                            setShowNewCategoryInput(false);
                            setIsStockModalOpen(true);
                        }}
                            className="bg-brand-600 hover:bg-brand-500 text-[var(--text-primary)] px-4 py-2 rounded-lg flex items-center gap-2 font-medium transition">
                            <Plus size={18} /> Yeni Stok Ekle
                        </button>
                    </div>

                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                        {(spareParts || []).filter(p => !p.deleted).map(item => (
                            <div key={item.id} className="glass-panel p-5 flex flex-col gap-3 relative group">
                                <div className="absolute top-4 right-4 flex gap-1 opacity-100 md:opacity-0 group-hover:opacity-100 transition">
                                    <button onClick={() => {
                                        setEditingStockId(item.id);
                                        setStockForm(item);
                                        setIsStockModalOpen(true);
                                    }} className="text-slate-600 hover:text-brand-400 p-1 rounded">
                                        <Pencil size={16} />
                                    </button>
                                    <button onClick={() => deleteSparePart(item.id, item.name)} className="text-slate-600 hover:text-red-400 p-1 rounded">
                                        <Trash2 size={16} />
                                    </button>
                                </div>

                                <div className="flex items-start gap-3 w-5/6">
                                    {item.files && item.files.length > 0 && item.files[0].type?.startsWith('image/') ? (
                                        <img src={item.files[0].data} className="w-12 h-12 rounded-lg object-cover bg-black/50 border border-[var(--border-color)]" alt="" />
                                    ) : (
                                        <div className="bg-brand-500/20 w-12 h-12 flex items-center justify-center rounded-lg text-brand-400 border border-brand-500/20 flex-shrink-0"><Package size={24} /></div>
                                    )}
                                    <div className="flex-1 min-w-0 pr-2 pt-0.5">
                                        <h4 className="font-bold text-[var(--text-primary)] text-base truncate">{item.name}</h4>
                                        <span className="text-[10px] bg-white/5 border border-[var(--border-color)] text-[var(--text-secondary)] px-2 py-0.5 rounded-full mt-1 inline-block uppercase tracking-wider">{item.category}</span>
                                    </div>
                                </div>

                                <div className="flex items-center justify-between border-t border-[var(--border-color)] pt-3 mt-1">
                                    <div className="flex flex-col">
                                        <span className="text-xs text-slate-500">Miktar</span>
                                        <span className="font-semibold text-[var(--text-primary)]">{item.count} Adet <span className="text-slate-500 font-normal text-xs ml-1">(Stokta)</span></span>
                                    </div>
                                    {item.price > 0 && (
                                        <div className="flex flex-col text-right">
                                            <span className="text-xs text-slate-500">Birim Fiyat</span>
                                            <span className="font-bold text-amber-400">₺{item.price.toLocaleString('tr-TR', { minimumFractionDigits: 2 })}</span>
                                        </div>
                                    )}
                                </div>

                                {item.notes && (
                                    <p className="text-xs text-[var(--text-secondary)] mt-1 line-clamp-2 italic">{item.notes}</p>
                                )}
                            </div>
                        ))}

                        {(spareParts || []).filter(p => !p.deleted).length === 0 && (
                            <div className="col-span-full glass-panel p-10 text-center text-slate-500 mt-2">
                                <Package size={40} className="mx-auto mb-4 opacity-30 text-brand-400" />
                                <h4 className="text-[var(--text-primary)] font-medium mb-1">Stokta Ürün Yok</h4>
                                <p className="text-sm">Elinizdeki yedek parçaları, yağ ve filtre gibi bakım malzemelerini buraya ekleyebilirsiniz.</p>
                            </div>
                        )}
                    </div>
                </div>
            )}

            {/* ─── SERVİS REHBERİ ─── */}
            {activeTab === 'mechanics' && (
                <div className="space-y-4">
                    <div className="flex justify-between items-center bg-brand-500/10 p-3 rounded-xl border border-brand-500/20">
                        <div className="flex items-center gap-2 text-brand-400">
                            <AlertCircle size={18} />
                            <span className="text-sm font-medium">Uzman servislerinizi ve iletişim bilgilerini burada saklayın.</span>
                        </div>
                        <button onClick={() => setIsMechanicModalOpen(true)}
                            className="bg-brand-600 hover:bg-brand-500 text-[var(--text-primary)] px-4 py-2 rounded-lg flex items-center gap-2 font-medium transition">
                            <Plus size={18} /> Tamirci Ekle
                        </button>
                    </div>
                    <div className="flex flex-col gap-4">
                        {mechanics.map(m => (
                            <div key={m.id} className="glass-panel p-5 flex flex-col gap-3 relative group">
                                <div className="absolute top-4 right-4 flex gap-1 opacity-100 md:opacity-0 group-hover:opacity-100 transition">
                                    <button onClick={() => {
                                        setEditingMechanicId(m.id);
                                        setMechanicForm({
                                            name: m.name, masterName: m.masterName || '', phone: m.phone || '',
                                            location: m.location || '', mapLink: m.mapLink || '', notes: m.notes || '', type: m.type || 'Genel Bakım'
                                        });
                                        setIsMechanicModalOpen(true);
                                    }} className="text-slate-600 hover:text-brand-400 p-1 rounded">
                                        <Pencil size={16} />
                                    </button>
                                    <button onClick={() => deleteMechanic(m.id)} className="text-slate-600 hover:text-red-400 p-1 rounded">
                                        <Trash2 size={16} />
                                    </button>
                                </div>

                                <div className="flex items-start gap-3">
                                    <div className="bg-brand-500/20 p-2.5 rounded-xl text-brand-400"><Wrench size={20} /></div>
                                    <div className="flex-1 min-w-0 pr-6">
                                        <h4 className="font-bold text-[var(--text-primary)] text-base">{m.name}</h4>
                                        <span className="text-[10px] bg-white/5 border border-[var(--border-color)] text-[var(--text-secondary)] px-2 py-0.5 rounded-full mt-1 inline-block uppercase tracking-wider">{m.type}</span>
                                    </div>
                                </div>

                                <div className="space-y-2 mt-1">
                                    {m.masterName && (
                                        <div className="flex items-center gap-2 text-sm text-[var(--text-primary)]">
                                            <User size={14} className="text-slate-500 flex-shrink-0" />
                                            <span>İlgili Kişi / Usta: <strong>{m.masterName}</strong></span>
                                        </div>
                                    )}
                                    {m.phone && (
                                        <div className="flex items-center gap-2 text-sm text-[var(--text-primary)]">
                                            <Phone size={14} className="text-slate-500 flex-shrink-0" />
                                            <a href={`tel:${m.phone}`} className="hover:text-brand-400 transition">{m.phone}</a>
                                        </div>
                                    )}
                                    {m.location && (
                                        <div className="flex items-start gap-2 text-sm text-[var(--text-primary)]">
                                            <MapPin size={14} className="text-slate-500 flex-shrink-0 mt-0.5" />
                                            <div className="flex flex-col flex-1">
                                                <span>{m.location}</span>
                                                {/* Küçük Harita */}
                                                <div className="mt-2 w-full h-32 rounded-lg overflow-hidden border border-[var(--border-color)] opacity-80 hover:opacity-100 transition-opacity">
                                                    <iframe
                                                        width="100%"
                                                        height="100%"
                                                        frameBorder="0" style={{ border: 0 }}
                                                        src={`https://maps.google.com/maps?q=${encodeURIComponent(m.location)}&t=&z=13&ie=UTF8&iwloc=&output=embed`}
                                                        allowFullScreen
                                                    ></iframe>
                                                </div>
                                            </div>
                                        </div>
                                    )}
                                </div>

                                {m.notes && (
                                    <div className="mt-2 pt-3 border-t border-[var(--border-color)] p-3 rounded-lg text-xs leading-relaxed text-[var(--text-secondary)] italic">
                                        <span className="font-semibold text-[var(--text-primary)] mb-1 flex items-center gap-1"><StickyNote size={12} /> Özel Notlar:</span>
                                        {m.notes}
                                    </div>
                                )}
                            </div>
                        ))}
                        {mechanics.length === 0 && (
                            <div className="glass-panel p-10 text-center text-slate-500">
                                <Wrench size={40} className="mx-auto mb-4 opacity-30 text-brand-400" />
                                <h4 className="text-[var(--text-primary)] font-medium mb-1">Kayıtlı Servis Yok</h4>
                                <p className="text-sm">Araçlarınızın bakımını yapan sürekli çalıştığınız ustaları ve servisleri buraya ekleyebilirsiniz.</p>
                            </div>
                        )}
                    </div>
                </div>
            )}

            {/* ─── FOTOĞRAFLAR VE İLGİLİ BELGELER ─── */}
            {activeTab === 'photos' && (
                <div className="space-y-4">
                    {!openedFolder ? (
                        <>
                            <div className="flex justify-end">
                                <button onClick={() => {
                                    setEditingFolderId(null);
                                    setFolderForm({ name: '', description: '', files: [] });
                                    setIsFolderModalOpen(true);
                                }} className="bg-emerald-600 hover:bg-emerald-500 text-[var(--text-primary)] px-4 py-2 rounded-lg flex items-center gap-2 font-medium transition">
                                    <FolderPlus size={18} /> Yeni Albüm Ekle
                                </button>
                            </div>
                            <div className="grid grid-cols-2 lg:grid-cols-4 gap-4">
                                {maintenanceFolders.map(folder => (
                                    <div key={folder.id} onClick={() => setOpenedFolder(folder)}
                                        className="glass-panel p-4 flex flex-col items-center text-center cursor-pointer hover:bg-white/5 hover:-translate-y-1 hover:shadow-xl transition-all group relative">
                                        <button onClick={(e) => handleDeleteFolder(folder.id, e)} className="absolute top-2 right-2 text-slate-600 hover:text-red-400 p-1 opacity-100 md:opacity-0 group-hover:opacity-100 transition rounded z-10">
                                            <Trash2 size={16} />
                                        </button>
                                        <button onClick={(e) => {
                                            e.stopPropagation();
                                            setEditingFolderId(folder.id);
                                            setFolderForm({ name: folder.name, description: folder.description, files: folder.files || [] });
                                            setIsFolderModalOpen(true);
                                        }} className="absolute top-2 left-2 text-slate-600 hover:text-brand-400 p-1 opacity-100 md:opacity-0 group-hover:opacity-100 transition rounded z-10">
                                            <Pencil size={14} />
                                        </button>
                                        <FolderOpen size={48} className="text-amber-400 mb-3 group-hover:scale-110 transition-transform duration-300" strokeWidth={1.5} />
                                        <h4 className="font-bold text-[var(--text-primary)] text-sm w-full truncate px-2">{folder.name}</h4>
                                        <p className="text-xs text-[var(--text-secondary)] mt-1">{(folder.files || []).length} Dosya</p>
                                    </div>
                                ))}
                                {maintenanceFolders.length === 0 && (
                                    <div className="col-span-2 lg:col-span-4 glass-panel p-10 text-center text-slate-500 mt-4">
                                        <FolderOpen size={40} className="mx-auto mb-4 opacity-30 text-emerald-400" />
                                        <h4 className="text-[var(--text-primary)] font-medium mb-1">Albüm Bulunamadı</h4>
                                        <p className="text-sm mb-4">Parça faturaları, kaza fotoğrafları veya özel belgeleri kategorize etmek için albüm oluşturun.</p>
                                    </div>
                                )}
                            </div>
                        </>
                    ) : (
                        <div className="space-y-4">
                            <div className="glass-panel p-4 flex items-center justify-between">
                                <div className="flex items-center gap-3">
                                    <button onClick={() => setOpenedFolder(null)} className="text-[var(--text-secondary)] hover:text-[var(--text-primary)] bg-white/5 p-2 rounded-lg transition-colors">
                                        <ChevronDown size={20} className="rotate-90" />
                                    </button>
                                    <div>
                                        <h3 className="font-bold text-[var(--text-primary)] flex items-center gap-2"><FolderOpen size={18} className="text-amber-400" /> {openedFolder.name}</h3>
                                        {openedFolder.description && <p className="text-xs text-[var(--text-secondary)] mt-0.5">{openedFolder.description}</p>}
                                    </div>
                                </div>
                                <button onClick={() => {
                                    setEditingFolderId(openedFolder.id);
                                    setFolderForm({ name: openedFolder.name, description: openedFolder.description, files: openedFolder.files || [] });
                                    setIsFolderModalOpen(true);
                                }} className="bg-brand-500/20 hover:bg-brand-500/40 text-brand-300 px-3 md:px-4 py-2 rounded-lg flex items-center gap-2 text-xs md:text-sm font-medium transition">
                                    <Plus size={16} /> Dosya Ekle
                                </button>
                            </div>

                            <div className="grid grid-cols-2 lg:grid-cols-4 gap-4">
                                {(openedFolder.files || []).map((file, idx) => (
                                    <div key={idx} className="glass-panel overflow-hidden border border-[var(--border-color)] group relative rounded-xl">
                                        {file.type && file.type.startsWith('image/') ? (
                                            <div className="aspect-square bg-black/50 relative overflow-hidden">
                                                <img src={file.data} alt="Belge/Fotoğraf" className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-500" />
                                                <div className="absolute inset-0 bg-black/60 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center gap-2 backdrop-blur-sm">
                                                    <button onClick={() => setViewFiles({ title: openedFolder.name, files: [file] })} className="bg-white/20 hover:bg-white/40 p-2 rounded-full text-[var(--text-primary)] transition">
                                                        <Eye size={18} />
                                                    </button>
                                                    <a href={file.data} download={file.name || 'foto'} className="bg-brand-500/50 hover:bg-brand-500 p-2 rounded-full text-[var(--text-primary)] transition">
                                                        <Download size={18} />
                                                    </a>
                                                </div>
                                            </div>
                                        ) : (
                                            <div className="aspect-square flex flex-col items-center justify-center bg-[var(--bg-panel-hover)] p-4 relative">
                                                <FileText size={40} className="text-[var(--text-secondary)] mb-3" />
                                                <p className="text-xs text-[var(--text-primary)] font-medium text-center truncate w-full">{file.name || 'Belge'}</p>
                                                <div className="absolute inset-0 bg-black/60 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center gap-2 backdrop-blur-sm">
                                                    <a href={file.data} download={file.name || 'belge'} className="bg-brand-500/50 hover:bg-brand-500 p-2 rounded-full text-[var(--text-primary)] transition flex items-center gap-1 text-sm font-medium px-4">
                                                        <Download size={16} />
                                                    </a>
                                                </div>
                                            </div>
                                        )}
                                    </div>
                                ))}
                                {(openedFolder.files || []).length === 0 && (
                                    <div className="col-span-2 lg:col-span-4 p-8 text-center text-slate-500 border border-dashed border-[var(--border-color)] rounded-xl">
                                        <p>Bu albümde henüz fotoğraf veya belge yok.</p>
                                    </div>
                                )}
                            </div>
                        </div>
                    )}
                </div>
            )}

            {/* Bakım Ekleme Modalı */}
            {isMaintenanceModalOpen && (
                <div className="fixed inset-0 bg-[var(--bg-panel)] backdrop-blur-sm flex items-center justify-center p-4 z-50">
                    <div className="glass-panel w-full max-w-md p-6 border border-[var(--border-color)] rounded-2xl animate-in zoom-in-95 duration-200">
                        <div className="flex justify-between items-center mb-4">
                            <h2 className="text-xl font-bold flex items-center text-[var(--text-primary)]">
                                <Wrench className="mr-2 text-amber-400" />
                                {editingMaintenanceId ? 'Bakım Kaydını Düzenle' : 'Yeni Bakım Ekle'}
                            </h2>
                            <button onClick={() => {
                                setIsMaintenanceModalOpen(false);
                                setEditingMaintenanceId(null);
                            }} className="text-[var(--text-secondary)] hover:text-[var(--text-primary)] transition-colors">
                                <X size={24} />
                            </button>
                        </div>
                        <div className="space-y-4 max-h-[70vh] overflow-y-auto pr-2">
                            <form onSubmit={handleAddMaintenance} className="space-y-4">
                                <div className="grid grid-cols-2 gap-4">
                                    <div>
                                        <label className="block text-sm font-medium text-[var(--text-primary)] mb-1">Tarih</label>
                                        <input type="date" required className="w-full glass-input px-3 py-2" value={maintenanceForm.date}
                                            onChange={e => setMaintenanceForm({ ...maintenanceForm, date: e.target.value })} />
                                    </div>
                                    <div>
                                        <label className="block text-sm font-medium text-[var(--text-primary)] mb-1">Araç KM</label>
                                        <input type="number" placeholder="Örn: 450000" className="w-full glass-input px-3 py-2" value={maintenanceForm.km}
                                            onChange={e => setMaintenanceForm({ ...maintenanceForm, km: e.target.value })} />
                                    </div>
                                </div>
                                <div>
                                    <label className="block text-sm font-medium text-[var(--text-primary)] mb-1">Bakım Türü</label>
                                    <div className="relative">
                                        <select className="w-full glass-input px-3 py-2 bg-[var(--bg-panel-hover)] appearance-none" value={maintenanceForm.type}
                                            onChange={e => setMaintenanceForm({ ...maintenanceForm, type: e.target.value })}>
                                            {MAINTENANCE_TYPES.map(t => <option key={t} value={t}>{t}</option>)}
                                        </select>
                                        <ChevronDown size={14} className="absolute right-3 top-1/2 -translate-y-1/2 text-[var(--text-secondary)] pointer-events-none" />
                                    </div>
                                </div>
                                <div>
                                    <label className="block text-sm font-medium text-[var(--text-primary)] mb-1">Açıklama</label>
                                    <textarea rows={2} required className="w-full glass-input px-3 py-2 text-sm resize-none"
                                        placeholder="Yapılan işlemi açıklayın..." value={maintenanceForm.description}
                                        onChange={e => setMaintenanceForm({ ...maintenanceForm, description: e.target.value })} />
                                </div>
                                <div className="grid grid-cols-2 gap-4">
                                    <div>
                                        <label className="block text-sm font-medium text-[var(--text-primary)] mb-1">Tamirci</label>
                                        <div className="relative">
                                            <select className="w-full glass-input px-3 py-2 bg-[var(--bg-panel-hover)] appearance-none" value={maintenanceForm.mechanicId}
                                                onChange={e => setMaintenanceForm({ ...maintenanceForm, mechanicId: e.target.value })}>
                                                <option value="">Belirtilmedi</option>
                                                {mechanics.map(m => <option key={m.id} value={m.id}>{m.name}</option>)}
                                            </select>
                                            <ChevronDown size={14} className="absolute right-3 top-1/2 -translate-y-1/2 text-[var(--text-secondary)] pointer-events-none" />
                                        </div>
                                    </div>
                                    <div>
                                        <label className="block text-sm font-medium text-[var(--text-primary)] mb-1">Toplam Tutar (TL)</label>
                                        <input type="number" step="0.01" required placeholder="Örn: 5000" className="w-full glass-input px-3 py-2" value={maintenanceForm.cost}
                                            onChange={e => setMaintenanceForm({ ...maintenanceForm, cost: e.target.value })} />
                                    </div>
                                </div>
                                <div>
                                    <label className="block text-sm font-medium text-[var(--text-primary)] mb-2">📎 Tamir Belgesi / Fotoğraf</label>
                                    <FileUpload files={maintenanceForm.files} onChange={files => setMaintenanceForm({ ...maintenanceForm, files })} />
                                </div>
                                <button type="submit" className="w-full bg-amber-600 hover:bg-amber-500 text-[var(--text-primary)] py-3 rounded-lg font-medium transition mt-2">{editingMaintenanceId ? 'Bakımı Güncelle' : 'Bakımı Kaydet'}</button>
                            </form>
                        </div>
                    </div>
                </div>
            )}

            {/* ─── TAMİRCİ EKLEME MODALİ ─── */}
            {isMechanicModalOpen && (
                <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-[var(--bg-panel)] backdrop-blur-sm">
                    <div className="glass-panel w-full max-w-lg p-6 relative animate-in zoom-in-95 duration-200 max-h-[90vh] overflow-y-auto">
                        <button onClick={() => {
                            setIsMechanicModalOpen(false);
                            setEditingMechanicId(null);
                        }} className="absolute top-4 right-4 text-[var(--text-secondary)] hover:text-[var(--text-primary)]"><X size={20} /></button>
                        <h3 className="text-xl font-bold text-[var(--text-primary)] mb-5 flex items-center gap-2">
                            <MapPin className="text-brand-500" /> {editingMechanicId ? 'Tamirciyi Düzenle' : 'Tamirci / Servis Ekle'}
                        </h3>
                        <form onSubmit={handleAddMechanic} className="space-y-4">
                            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                                <div>
                                    <label className="block text-sm font-medium text-[var(--text-primary)] mb-1">Servis / Dükkan Adı</label>
                                    <input type="text" required placeholder="Örn: Ankara İveco Servisi" className="w-full glass-input px-4 py-2" value={mechanicForm.name}
                                        onChange={e => setMechanicForm({ ...mechanicForm, name: e.target.value })} />
                                </div>
                                <div>
                                    <label className="block text-sm font-medium text-[var(--text-primary)] mb-1">İlgili Usta / Kişi</label>
                                    <input type="text" placeholder="Örn: Ahmet Usta" className="w-full glass-input px-4 py-2" value={mechanicForm.masterName}
                                        onChange={e => setMechanicForm({ ...mechanicForm, masterName: e.target.value })} />
                                </div>
                            </div>
                            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                                <div>
                                    <label className="block text-sm font-medium text-[var(--text-primary)] mb-1">Telefon</label>
                                    <input type="text" placeholder="0555 555 55 55" className="w-full glass-input px-4 py-2" value={mechanicForm.phone}
                                        onChange={e => setMechanicForm({ ...mechanicForm, phone: e.target.value })} />
                                </div>
                                <div>
                                    <label className="block text-sm font-medium text-[var(--text-primary)] mb-1">Uzmanlık Alanı</label>
                                    <div className="relative">
                                        <select className="w-full glass-input px-3 py-2 bg-[var(--bg-panel-hover)] appearance-none" value={mechanicForm.type}
                                            onChange={e => setMechanicForm({ ...mechanicForm, type: e.target.value })}>
                                            {['Genel Bakım', 'Yetkili Servis', 'Lastik', 'Motor', 'Fren', 'Elektrik', 'Kaporta', 'Dorse', 'Diğer'].map(t => <option key={t} value={t}>{t}</option>)}
                                        </select>
                                        <ChevronDown size={14} className="absolute right-3 top-1/2 -translate-y-1/2 text-[var(--text-secondary)] pointer-events-none" />
                                    </div>
                                </div>
                            </div>
                            <div>
                                <label className="block text-sm font-medium text-[var(--text-primary)] mb-1">Açık Adres / Konum</label>
                                <input type="text" required placeholder="Örn: Şaşmaz Oto Sanayi, Ankara" className="w-full glass-input px-4 py-2" value={mechanicForm.location}
                                    onChange={e => setMechanicForm({ ...mechanicForm, location: e.target.value })} />
                            </div>
                            <div className="bg-white/5 p-3 rounded-lg border border-[var(--border-color)]">
                                <label className="block text-sm font-medium text-[var(--text-primary)] mb-2 flex justify-between">
                                    <span>Konum Linki (Apple / Google Haritalar)</span>
                                    {mechanicForm.location && (
                                        <button type="button" onClick={() => {
                                            if (mechanicForm.location) {
                                                setMechanicForm({ ...mechanicForm, mapLink: `https://maps.apple.com/?q=${encodeURIComponent(mechanicForm.location)}` });
                                            }
                                        }} className="text-xs text-brand-400 flex items-center gap-1 hover:text-brand-300"><Map size={12} /> Apple'da Bul</button>
                                    )}
                                </label>
                                <input type="url" placeholder="https://maps.app.goo.gl/..." className="w-full glass-input px-3 py-2 text-sm" value={mechanicForm.mapLink}
                                    onChange={e => setMechanicForm({ ...mechanicForm, mapLink: e.target.value })} />
                            </div>
                            <div>
                                <label className="block text-sm font-medium text-[var(--text-primary)] mb-1">Notlar (Servis Hakkında Bilgiler, Fiyat vs.)</label>
                                <textarea rows={2} placeholder="Sadece fren işleri yapıyor, parça dışarıdan..." className="w-full glass-input px-3 py-2 text-sm resize-none" value={mechanicForm.notes}
                                    onChange={e => setMechanicForm({ ...mechanicForm, notes: e.target.value })} />
                            </div>
                            <button type="submit" className="w-full bg-brand-600 hover:bg-brand-500 text-[var(--text-primary)] py-3 rounded-lg font-medium transition">Servisi Kaydet</button>
                        </form>
                    </div>
                </div>
            )}

            {/* ─── ALBÜM / KLASÖR EKLEME MODALİ ─── */}
            {isFolderModalOpen && (
                <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-[var(--bg-panel)] backdrop-blur-sm">
                    <div className="glass-panel w-full max-w-lg p-6 relative animate-in zoom-in-95 duration-200 max-h-[90vh] overflow-y-auto">
                        <button onClick={() => setIsFolderModalOpen(false)} className="absolute top-4 right-4 text-[var(--text-secondary)] hover:text-[var(--text-primary)]"><X size={20} /></button>
                        <h3 className="text-xl font-bold text-[var(--text-primary)] mb-5 flex items-center gap-2"><FolderOpen className="text-emerald-500" /> {editingFolderId ? 'Albümü Düzenle' : 'Yeni Albüm Ekle'}</h3>
                        <form onSubmit={handleSaveFolder} className="space-y-4">
                            <div>
                                <label className="block text-sm font-medium text-[var(--text-primary)] mb-1">Albüm / Klasör Adı</label>
                                <input type="text" required placeholder="Örn: 2026 Kaza Raporları" className="w-full glass-input px-4 py-2" value={folderForm.name}
                                    onChange={e => setFolderForm({ ...folderForm, name: e.target.value })} />
                            </div>
                            <div>
                                <label className="block text-sm font-medium text-[var(--text-primary)] mb-1">Açıklama (Opsiyonel)</label>
                                <textarea rows={2} placeholder="İzmir seferindeki kazaya ait tutanaklar..." className="w-full glass-input px-4 py-2 text-sm resize-none" value={folderForm.description}
                                    onChange={e => setFolderForm({ ...folderForm, description: e.target.value })} />
                            </div>
                            <div className="pt-2">
                                <label className="block text-sm font-medium text-[var(--text-primary)] mb-2">📸 Dosyaları Seçin</label>
                                <FileUpload files={folderForm.files} onChange={files => setFolderForm({ ...folderForm, files })} />
                            </div>
                            <button type="submit" className="w-full bg-emerald-600 hover:bg-emerald-500 text-[var(--text-primary)] py-3 rounded-lg font-medium transition mt-2">{editingFolderId ? 'Albümü Güncelle' : 'Albümü Oluştur'}</button>
                        </form>
                    </div>
                </div>
            )}

            {/* ─── STOK EKLEME MODALİ ─── */}
            {isStockModalOpen && (
                <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-[var(--bg-panel)] backdrop-blur-sm">
                    <div className="glass-panel w-full max-w-lg p-6 relative animate-in zoom-in-95 duration-200 max-h-[90vh] overflow-y-auto">
                        <button onClick={() => {
                            setIsStockModalOpen(false);
                            setEditingStockId(null);
                        }} className="absolute top-4 right-4 text-[var(--text-secondary)] hover:text-[var(--text-primary)]"><X size={20} /></button>
                        <h3 className="text-xl font-bold text-[var(--text-primary)] mb-5 flex items-center gap-2">
                            <Package className="text-brand-500" /> {editingStockId ? 'Ekli Ürünü Düzenle' : 'Yeni Stok / Parça Ekle'}
                        </h3>
                        <form onSubmit={handleAddStock} className="space-y-4">
                            <div>
                                <label className="block text-sm font-medium text-[var(--text-primary)] mb-1">Parça / Ürün Adı</label>
                                <input type="text" required placeholder="Örn: 20W-50 Motor Yağı" className="w-full glass-input px-4 py-2" value={stockForm.name}
                                    onChange={e => setStockForm({ ...stockForm, name: e.target.value })} />
                            </div>
                            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                                <div>
                                    <label className="block text-sm font-medium text-[var(--text-primary)] mb-1">Miktar (Adet / Litre)</label>
                                    <input type="number" required placeholder="Örn: 2" className="w-full glass-input px-4 py-2" value={stockForm.count}
                                        onChange={e => setStockForm({ ...stockForm, count: e.target.value })} />
                                </div>
                                <div>
                                    <label className="block text-sm font-medium text-[var(--text-primary)] mb-1">Birim Fiyatı (TL) <span className="text-slate-500 text-xs italic">Opsiyonel</span></label>
                                    <input type="number" step="0.01" className="w-full glass-input px-4 py-2" value={stockForm.price}
                                        onChange={e => setStockForm({ ...stockForm, price: e.target.value })} />
                                </div>
                            </div>
                            <div>
                                <label className="block text-sm font-medium text-[var(--text-primary)] mb-1">Kategori</label>
                                {showNewCategoryInput ? (
                                    <div className="flex gap-2">
                                        <input type="text" required placeholder="Yeni kategori adı (Örn: Motor Parçaları)" className="flex-1 glass-input px-4 py-2" value={newCategoryName}
                                            onChange={e => setNewCategoryName(e.target.value)} autoFocus />
                                        <button type="button" onClick={() => setShowNewCategoryInput(false)} className="bg-white/5 border border-[var(--border-color)] px-3 py-2 rounded-lg text-[var(--text-primary)] hover:text-[var(--text-primary)] transition">İptal</button>
                                    </div>
                                ) : (
                                    <div className="relative">
                                        <select className="w-full glass-input px-3 py-2 bg-[var(--bg-panel-hover)] appearance-none" value={stockForm.category}
                                            onChange={e => {
                                                if (e.target.value === 'YENI_EKLE') {
                                                    setShowNewCategoryInput(true);
                                                } else {
                                                    setStockForm({ ...stockForm, category: e.target.value });
                                                }
                                            }}>
                                            {(sparePartCategories || []).map(c => <option key={c} value={c}>{c}</option>)}
                                            <option value="YENI_EKLE" className="text-brand-400 font-bold">+ Yeni Kategori Ekle</option>
                                        </select>
                                        <ChevronDown size={14} className="absolute right-3 top-1/2 -translate-y-1/2 text-[var(--text-secondary)] pointer-events-none" />
                                    </div>
                                )}
                            </div>
                            <div>
                                <label className="block text-sm font-medium text-[var(--text-primary)] mb-1">Özel Notlar (Opsiyonel)</label>
                                <textarea rows={2} placeholder="Sadece kışın kullanılıyor..." className="w-full glass-input px-3 py-2 text-sm resize-none" value={stockForm.notes}
                                    onChange={e => setStockForm({ ...stockForm, notes: e.target.value })} />
                            </div>
                            <div>
                                <label className="block text-sm font-medium text-[var(--text-primary)] mb-2">📸 Ürün / Parça Fotoğrafı (Opsiyonel)</label>
                                <FileUpload files={stockForm.files} onChange={files => setStockForm({ ...stockForm, files })} />
                            </div>
                            <button type="submit" className="w-full bg-brand-600 hover:bg-brand-500 text-[var(--text-primary)] py-3 rounded-lg font-medium transition">{editingStockId ? 'Stok Güncelle' : 'Stoğa Ekle'}</button>
                        </form>
                    </div>
                </div>
            )}

            {/* Dosya Görüntüleyici Modal */}
            {viewFiles && (
                <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-[var(--bg-panel)] backdrop-blur-sm">
                    <div className="glass-panel w-full max-w-2xl p-6 relative animate-in zoom-in-95 duration-200">
                        <div className="flex justify-between items-center mb-6">
                            <h3 className="text-xl font-bold text-[var(--text-primary)] flex items-center gap-2">
                                <FileText className="text-amber-400" />
                                {viewFiles.title} İçin Ekler
                            </h3>
                            <button onClick={() => setViewFiles(null)} className="text-[var(--text-secondary)] hover:text-[var(--text-primary)] transition-colors">
                                <X size={24} />
                            </button>
                        </div>
                        <div className="space-y-4 max-h-[70vh] overflow-y-auto pr-2">
                            {viewFiles.files.map((file, idx) => (
                                <div key={idx} className="bg-white/5 border border-[var(--border-color)] rounded-xl overflow-hidden">
                                    {/* Preview if image */}
                                    {file.type && file.type.startsWith('image/') ? (
                                        <div className="bg-black/30 w-full flex justify-center p-4">
                                            <img src={file.data} alt="Belge/Makbuz" className="max-w-full max-h-[400px] object-contain rounded" />
                                        </div>
                                    ) : (
                                        <div className="p-8 flex flex-col items-center justify-center bg-white/5">
                                            <FileText size={48} className="text-[var(--text-secondary)] mb-3" />
                                            <p className="text-[var(--text-primary)] font-medium">{file.name || 'Belge dosyası'}</p>
                                        </div>
                                    )}

                                    {/* Footer with download */}
                                    <div className="p-4 bg-white/5 border-t border-[var(--border-color)] flex justify-between items-center">
                                        <span className="text-sm text-[var(--text-secondary)] truncate max-w-[70%]">{file.name || 'Ek_Belge'}</span>
                                        <a href={file.data} download={file.name || 'Belge'}
                                            className="flex items-center gap-1.5 px-3 py-1.5 text-sm font-medium text-brand-400 hover:text-[var(--text-primary)] bg-brand-500/10 hover:bg-brand-500/30 border border-brand-500/20 rounded-lg transition-colors">
                                            <Download size={14} /> İndir
                                        </a>
                                    </div>
                                </div>
                            ))}
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
};

export default Maintenance;

import React, { useState, useContext, useMemo } from 'react';
import { DataContext } from '../context/DataContext';
import { Wallet, Search, Filter, TrendingUp, TrendingDown, Plus, Download, Trash2, Calendar, Pencil, ArrowDownRight, ArrowUpRight, X } from 'lucide-react';
import FileUpload from './FileUpload';

const Payments = () => {
    const {
        paymentRecords,
        addPayment,
        deletePayment,
        updatePayment
    } = useContext(DataContext);

    const [filterType, setFilterType] = useState('Hepsi'); // 'Hepsi', 'Tahsilat', 'Ödeme'
    const [filterMonth, setFilterMonth] = useState(''); // 'YYYY-MM'

    const [isAddModalOpen, setIsAddModalOpen] = useState(false);
    const [editingPaymentId, setEditingPaymentId] = useState(null);

    // Form States
    const [formData, setFormData] = useState({
        date: new Date().toISOString().split('T')[0],
        type: 'Tahsilat',
        description: '',
        amount: '',
        files: []
    });
    const [deleteConfirm, setDeleteConfirm] = useState(null);

    // Özet ve Filtre Hesaplamaları
    const activePaymentRecords = useMemo(() => {
        let records = (paymentRecords || []).filter(r => !r.deleted)
            .sort((a, b) => new Date(b.date) - new Date(a.date));

        if (filterType !== 'Hepsi') {
            records = records.filter(r => r.type === filterType);
        }

        if (filterMonth) {
            records = records.filter(r => {
                const recordMonth = r.date.substring(0, 7); // 'YYYY-MM'
                return recordMonth === filterMonth;
            });
        }

        return records;
    }, [paymentRecords, filterType, filterMonth]);

    const activeForBalance = (paymentRecords || []).filter(r => !r.deleted);
    const totalIncome = activeForBalance.filter(r => r.type === 'Tahsilat').reduce((sum, r) => sum + (r.amount || 0), 0);
    const totalExpense = activeForBalance.filter(r => r.type === 'Ödeme').reduce((sum, r) => sum + (r.amount || 0), 0);
    const netBalance = totalIncome - totalExpense;

    const handleSubmit = async (e) => {
        e.preventDefault();

        try {
            if (editingPaymentId) {
                await updatePayment(editingPaymentId, {
                    ...formData,
                    amount: parseFloat(formData.amount)
                });
            } else {
                await addPayment({
                    ...formData,
                    amount: parseFloat(formData.amount)
                });
            }

            setFormData({
                type: 'Tahsilat',
                date: new Date().toISOString().split('T')[0],
                description: '',
                amount: '',
                files: []
            });
            setIsAddModalOpen(false);
            setEditingPaymentId(null);
        } catch (error) {
            console.error('Ödeme kaydedilirken hata:', error);
            alert('İşlem kaydedilemedi. Lütfen tekrar deneyin.');
        }
    };

    const handleDelete = (id) => {
        deletePayment(id);
    };

    return (
        <div className="space-y-6 animate-in fade-in duration-500">
            {/* Üst İstatistikler */}
            <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                <div className="glass-panel p-5 relative overflow-hidden group">
                    <div className="absolute top-0 right-0 w-24 h-24 bg-emerald-500/10 rounded-full blur-2xl transition-all"></div>
                    <div className="flex justify-between items-start">
                        <div>
                            <p className="text-[var(--text-secondary)] text-sm font-medium">Toplam Tahsilat</p>
                            <h3 className="text-3xl font-bold mt-2 text-[var(--text-primary)]">₺{totalIncome.toLocaleString('tr-TR')}</h3>
                        </div>
                        <div className="p-2 bg-emerald-500/20 rounded-lg text-emerald-400">
                            <ArrowDownRight size={24} />
                        </div>
                    </div>
                </div>

                <div className="glass-panel p-5 relative overflow-hidden group">
                    <div className="absolute top-0 right-0 w-24 h-24 bg-red-500/10 rounded-full blur-2xl transition-all"></div>
                    <div className="flex justify-between items-start">
                        <div>
                            <p className="text-[var(--text-secondary)] text-sm font-medium">Toplam Ödeme</p>
                            <h3 className="text-3xl font-bold mt-2 text-[var(--text-primary)]">₺{totalExpense.toLocaleString('tr-TR')}</h3>
                        </div>
                        <div className="p-2 bg-red-500/20 rounded-lg text-red-400">
                            <ArrowUpRight size={24} />
                        </div>
                    </div>
                </div>

                <div className="glass-panel p-5 relative overflow-hidden group">
                    <div className="absolute top-0 right-0 w-24 h-24 bg-brand-500/10 rounded-full blur-2xl transition-all"></div>
                    <div className="flex justify-between items-start">
                        <div>
                            <p className="text-[var(--text-secondary)] text-sm font-medium">Net Kasa (Bakiye)</p>
                            <h3 className={`text-3xl font-bold mt-2 ${netBalance >= 0 ? 'text-brand-400' : 'text-red-400'}`}>
                                ₺{netBalance.toLocaleString('tr-TR')}
                            </h3>
                        </div>
                        <div className="p-2 bg-brand-500/20 rounded-lg text-brand-400">
                            <Wallet size={24} />
                        </div>
                    </div>
                </div>
            </div>

            {/* Aksiyon Barı */}
            <div className="flex flex-col sm:flex-row justify-between items-center gap-4 mb-2">
                <div className="flex flex-wrap items-center gap-4">
                    <div className="glass-input flex items-center px-4 py-2 hover:border-brand-500/30 transition-colors">
                        <Filter size={16} className="text-[var(--text-secondary)] mr-2" />
                        <span className="text-sm font-medium text-[var(--text-secondary)] mr-2">Tür:</span>
                        <select className="bg-transparent text-sm font-semibold focus:outline-none cursor-pointer"
                            value={filterType} onChange={e => setFilterType(e.target.value)}>
                            <option className="text-slate-900 font-medium" value="Hepsi">Tümü</option>
                            <option className="text-slate-900 font-medium" value="Tahsilat">Tahsilatlar</option>
                            <option className="text-slate-900 font-medium" value="Ödeme">Ödemeler</option>
                        </select>
                    </div>
                    <div className="glass-input flex items-center px-4 py-2 hover:border-brand-500/30 transition-colors relative group">
                        <Calendar size={16} className={`mr-1 transition-colors ${filterMonth ? 'text-brand-400' : 'text-[var(--text-secondary)] group-hover:text-brand-400'}`} />
                        <div className="relative flex items-center">
                            {/* Gerçek input (şeffaf ve üstte) */}
                            <input
                                type="month"
                                className="absolute inset-0 w-full h-full opacity-0 cursor-pointer z-10"
                                value={filterMonth}
                                onChange={e => setFilterMonth(e.target.value)}
                            />
                            {/* Görünen sahte input (içi boşken hiçbir string göstermeyecek) */}
                            {filterMonth && (
                                <span className="text-sm font-semibold pointer-events-none text-brand-400 ml-1">
                                    {new Date(filterMonth + '-01').toLocaleDateString('tr-TR', { month: 'long', year: 'numeric' })}
                                </span>
                            )}
                        </div>
                        {filterMonth && (
                            <button onClick={() => setFilterMonth('')} className="ml-3 p-1 rounded-md bg-red-500/10 text-red-400 hover:bg-red-500/20 hover:text-[var(--text-primary)] transition-colors" title="Filtreyi Temizle relative z-20">
                                <X size={14} />
                            </button>
                        )}
                    </div>
                </div>
                <button
                    onClick={() => setIsAddModalOpen(true)}
                    className="w-full sm:w-auto bg-brand-600 hover:bg-brand-500 text-[var(--text-primary)] px-5 py-2.5 rounded-xl font-semibold transition-all shadow-lg shadow-brand-500/20 flex items-center justify-center whitespace-nowrap"
                >
                    <Plus size={18} className="mr-2" />
                    Yeni İşlem Ekle
                </button>
            </div>

            {/* Ödemeler Tablosu (Liste) */}
            <div className="glass-panel rounded-xl overflow-hidden">
                {activePaymentRecords.length === 0 ? (
                    <div className="p-12 text-center text-slate-500">
                        <Wallet size={48} className="mx-auto mb-4 opacity-20" />
                        <p className="text-lg">Henüz bir ödeme/tahsilat kaydı bulunmuyor.</p>
                        <p className="text-sm mt-1">Nakit akışınızı takip etmek için yeni işlem ekleyin.</p>
                    </div>
                ) : (
                    <div className="overflow-x-auto">
                        <table className="w-full text-left border-collapse">
                            <thead>
                                <tr className="border-b border-[var(--border-color)] text-[var(--text-secondary)] text-sm">
                                    <th className="p-4 font-medium">Tarih</th>
                                    <th className="p-4 font-medium">Tür</th>
                                    <th className="p-4 font-medium">Açıklama (Kime/Kimden)</th>
                                    <th className="p-4 font-medium text-right">Tutar</th>
                                    <th className="p-4 font-medium text-center">İşlem</th>
                                </tr>
                            </thead>
                            <tbody>
                                {activePaymentRecords.map((record) => (
                                    <tr key={record.id} className="border-b border-[var(--border-color)] hover:bg-white/5 transition-colors group">
                                        <td className="p-4 text-[var(--text-primary)]">
                                            {new Date(record.date).toLocaleDateString('tr-TR')}
                                        </td>
                                        <td className="p-4">
                                            <span className={`px-3 py-1 rounded-full text-xs font-medium border ${record.type === 'Tahsilat'
                                                ? 'bg-emerald-500/10 text-emerald-400 border-emerald-500/20'
                                                : 'bg-red-500/10 text-red-400 border-red-500/20'
                                                }`}>
                                                {record.type}
                                            </span>
                                        </td>
                                        <td className="p-4 text-[var(--text-primary)] font-medium">{record.description}</td>
                                        <td className="p-4 text-right font-bold text-[var(--text-primary)]">
                                            ₺{record.amount.toLocaleString('tr-TR')}
                                        </td>
                                        <td className="p-4 text-center">
                                            <div className="flex items-center justify-center gap-1 opacity-100 md:opacity-0 group-hover:opacity-100 transition-opacity">
                                                <button
                                                    onClick={() => {
                                                        setEditingPaymentId(record.id);
                                                        setFormData({
                                                            type: record.type || 'Tahsilat',
                                                            date: record.date || new Date().toISOString().split('T')[0],
                                                            description: record.description || '',
                                                            amount: record.amount || '',
                                                            files: record.files || []
                                                        });
                                                        setIsAddModalOpen(true);
                                                    }}
                                                    className="p-1.5 rounded-lg transition-all text-slate-500 hover:text-brand-400 hover:bg-white/5"
                                                    title="Kaydı Düzenle"
                                                >
                                                    <Pencil size={18} />
                                                </button>
                                                <button
                                                    onClick={() => handleDelete(record.id)}
                                                    className="p-1.5 rounded-lg transition-all text-slate-500 hover:text-red-400 hover:bg-white/5"
                                                    title="Kaydı Sil"
                                                >
                                                    <Trash2 size={18} />
                                                </button>
                                            </div>
                                        </td>
                                    </tr>
                                ))}
                            </tbody>
                        </table>
                    </div>
                )}
            </div>

            {/* Yeni İşlem Ekleme Modalı */}
            {isAddModalOpen && (
                <div className="fixed inset-0 bg-[var(--bg-panel)] backdrop-blur-sm flex items-center justify-center p-4 z-50">
                    <div className="glass-panel w-full max-w-md p-6 border border-[var(--border-color)] rounded-2xl animate-in zoom-in-95 duration-200">
                        <h2 className="text-xl font-bold mb-4 flex items-center text-[var(--text-primary)]">
                            <Wallet className="mr-2 text-brand-400" />
                            {editingPaymentId ? 'İşlemi Düzenle' : 'Yeni İşlem (Para Giriş/Çıkış)'}
                        </h2>

                        <form onSubmit={handleSubmit} className="space-y-4">
                            <div>
                                <label className="block text-sm font-medium text-[var(--text-secondary)] mb-1">İşlem Türü</label>
                                <select
                                    className="w-full bg-[var(--bg-panel-hover)] border border-[var(--border-color)] rounded-lg px-4 py-2.5 text-[var(--text-primary)] focus:outline-none focus:border-brand-500 focus:ring-1 focus:ring-brand-500 transition-all appearance-none"
                                    value={formData.type}
                                    onChange={(e) => setFormData({ ...formData, type: e.target.value })}
                                >
                                    <option value="Tahsilat">Tahsilat (Para Girişi)</option>
                                    <option value="Ödeme">Ödeme (Para Çıkışı)</option>
                                </select>
                            </div>

                            <div>
                                <label className="block text-sm font-medium text-[var(--text-secondary)] mb-1">Tarih</label>
                                <input
                                    type="date"
                                    required
                                    className="w-full bg-[var(--bg-panel-hover)] border border-[var(--border-color)] rounded-lg px-4 py-2.5 text-[var(--text-primary)] focus:outline-none focus:border-brand-500 transition-all"
                                    value={formData.date}
                                    onChange={(e) => setFormData({ ...formData, date: e.target.value })}
                                />
                            </div>

                            <div>
                                <label className="block text-sm font-medium text-[var(--text-secondary)] mb-1">Açıklama</label>
                                <input
                                    type="text"
                                    required
                                    placeholder={formData.type === 'Tahsilat' ? "Örn: Çayırhan Nakliye Tahsilatı" : "Örn: Lastikçi Ahmet Usta Ödemesi"}
                                    className="w-full bg-[var(--bg-panel-hover)] border border-[var(--border-color)] rounded-lg px-4 py-2.5 text-[var(--text-primary)] focus:outline-none focus:border-brand-500 transition-all"
                                    value={formData.description}
                                    onChange={(e) => setFormData({ ...formData, description: e.target.value })}
                                />
                            </div>

                            <div>
                                <label className="block text-sm font-medium text-[var(--text-secondary)] mb-1">Tutar (₺)</label>
                                <input
                                    type="number"
                                    required
                                    min="0"
                                    step="0.01"
                                    placeholder="0.00"
                                    className="w-full bg-[var(--bg-panel-hover)] border border-[var(--border-color)] rounded-lg px-4 py-2.5 text-[var(--text-primary)] focus:outline-none focus:border-brand-500 transition-all"
                                    value={formData.amount}
                                    onChange={(e) => setFormData({ ...formData, amount: e.target.value })}
                                />
                            </div>

                            <div>
                                <label className="block text-sm font-medium text-[var(--text-secondary)] mb-2">📎 Makbuz / Belge Ekle</label>
                                <FileUpload files={formData.files} onChange={files => setFormData({ ...formData, files })} />
                            </div>

                            <div className="flex gap-3 pt-2">
                                <button
                                    type="button"
                                    onClick={() => {
                                        setIsAddModalOpen(false);
                                        setEditingPaymentId(null);
                                        setFormData({
                                            type: 'Tahsilat',
                                            date: new Date().toISOString().split('T')[0],
                                            description: '',
                                            amount: '',
                                            files: []
                                        });
                                    }}
                                    className="flex-1 py-2.5 rounded-lg font-medium text-[var(--text-primary)] hover:bg-white/5 transition-colors"
                                >
                                    İptal
                                </button>
                                <button
                                    type="submit"
                                    className="flex-1 bg-brand-600 hover:bg-brand-500 text-[var(--text-primary)] py-2.5 rounded-lg font-medium shadow-lg shadow-brand-500/25 transition-all"
                                >
                                    Kaydet
                                </button>
                            </div>
                        </form>
                    </div>
                </div>
            )}
        </div>
    );
};

export default Payments;

import React, { useState, useEffect, useRef, useContext } from 'react';
import { Settings as SettingsIcon, Database, Save, Server, ShieldCheck, Camera, UploadCloud, Truck, Loader2, Globe } from 'lucide-react';
import WipeData from './WipeData';
import { DataContext } from '../context/DataContext';

const Settings = () => {
    const { currentSession } = useContext(DataContext);
    const picKey = `tir_profile_pic_${currentSession?.username || 'default'}`;
    const [apiUrl, setApiUrl] = useState('');
    const [profilePic, setProfilePic] = useState(null);
    const [isUploading, setIsUploading] = useState(false);
    const [uploadError, setUploadError] = useState('');
    const fileInputRef = useRef(null);
    const IMGBB_KEY = 'b9783b951fef452d9dee0c3c0fc206cc';

    useEffect(() => {
        const savedUrl = localStorage.getItem('tir_api_url');
        if (savedUrl) setApiUrl(savedUrl);

        const savedPic = localStorage.getItem(picKey);
        if (savedPic) setProfilePic(savedPic);
    }, [picKey]);

    // URL hook kaldırıldı

    const handleImageUpload = async (e) => {
        const file = e.target.files[0];
        if (!file) return;
        setIsUploading(true);
        setUploadError('');
        try {
            const formData = new FormData();
            formData.append('image', file);
            const res = await fetch(`https://api.imgbb.com/1/upload?key=${IMGBB_KEY}`, {
                method: 'POST',
                body: formData,
            });
            const data = await res.json();
            if (data.success) {
                const url = data.data.url;
                setProfilePic(url);
                localStorage.setItem(picKey, url);
                window.dispatchEvent(new Event('tir_profile_pic_updated'));
            } else {
                setUploadError('Yükleme başarısız. Tekrar deneyin.');
            }
        } catch (error) {
            console.error(error);
            setUploadError('Bağlantı hatası. İnternet bağlantınızı kontrol edin.');
        } finally {
            setIsUploading(false);
        }
    };

    return (
        <div className="space-y-6 animate-in fade-in duration-500 max-w-4xl mx-auto">
            <div className="glass-panel p-6 border-l-4 border-l-brand-500">
                <h3 className="text-xl font-bold text-[var(--text-primary)] mb-2 flex items-center">
                    <SettingsIcon className="mr-2" size={24} />
                    Sistem Ayarları
                </h3>
                <p className="text-[var(--text-secondary)] text-sm">
                    Bu ekrandan profil resmini değiştirebilir ve uygulamanın veritabanı bağlantısını yönetebilirsiniz.
                </p>
            </div>

            {/* Profil Resmi Ayarı */}
            <div className="glass-panel border-[var(--border-color)] overflow-hidden">
                <div className="p-6 border-b border-[var(--border-color)] flex items-center justify-between">
                    <h4 className="font-bold text-lg text-[var(--text-primary)] flex items-center">
                        <Camera className="mr-2 text-brand-400" size={20} />
                        Araç Profil Resmi
                    </h4>
                </div>
                <div className="p-6 flex flex-col sm:flex-row items-center gap-6">
                    <div className="relative w-32 h-32 rounded-2xl overflow-hidden bg-[var(--bg-panel-hover)] border-4 border-[var(--border-color)] flex-shrink-0 shadow-xl group">
                        {profilePic ? (
                            <img
                                src={profilePic}
                                alt="Truck Profile"
                                className="w-full h-full object-cover bg-white"
                                onError={() => setProfilePic(null)}
                            />
                        ) : (
                            <div className="w-full h-full bg-brand-500 flex items-center justify-center">
                                <Truck size={48} className="text-[var(--text-primary)] opacity-90" />
                            </div>
                        )}
                        <div className="absolute inset-0 bg-black/60 opacity-0 group-hover:opacity-100 transition-opacity flex flex-col items-center justify-center cursor-pointer"
                            onClick={() => !isUploading && fileInputRef.current.click()}>
                            {isUploading ? <Loader2 className="text-[var(--text-primary)] mb-1 animate-spin" size={24} /> : <UploadCloud className="text-[var(--text-primary)] mb-1" size={24} />}
                            <span className="text-xs text-[var(--text-primary)] font-medium">{isUploading ? 'Yükleniyor...' : 'Değiştir'}</span>
                        </div>
                    </div>
                    <div className="flex-1 space-y-3 text-center sm:text-left">
                        <p className="text-[var(--text-secondary)] text-sm">
                            Menüde aracınızın adının yanında görünecek fotoğrafı buradan yükleyebilirsiniz.
                        </p>
                        {profilePic && profilePic.startsWith('http') && (
                            <div className="flex items-center gap-1.5 text-emerald-400 text-xs font-medium">
                                <Globe size={13} />
                                Tüm cihazlarda görünür (bulut senkronu aktif)
                            </div>
                        )}
                        {uploadError && (
                            <p className="text-red-400 text-xs">{uploadError}</p>
                        )}
                        <input
                            type="file"
                            accept="image/*"
                            className="hidden"
                            ref={fileInputRef}
                            onChange={handleImageUpload}
                        />
                        <button
                            onClick={() => fileInputRef.current.click()}
                            disabled={isUploading}
                            className={`bg-white/10 hover:bg-white/20 text-[var(--text-primary)] px-4 py-2 rounded-lg text-sm transition-colors border border-[var(--border-color)] inline-flex items-center ${isUploading ? 'opacity-60 cursor-not-allowed' : ''}`}
                        >
                            {isUploading ? <Loader2 size={16} className="mr-2 animate-spin" /> : <Camera size={16} className="mr-2" />}
                            {isUploading ? 'Yükleniyor...' : 'Fotoğraf Seç'}
                        </button>
                        {profilePic && (
                            <button
                                onClick={() => {
                                    localStorage.removeItem(picKey);
                                    setProfilePic(null);
                                    window.dispatchEvent(new Event('tir_profile_pic_updated'));
                                }}
                                className="ml-3 text-red-400 hover:text-red-300 px-4 py-2 text-sm transition-colors"
                            >
                                Resmi Kaldır
                            </button>
                        )}
                    </div>
                </div>
            </div>

            {/* API Ayarı */}
            <div className="glass-panel border-[var(--border-color)] overflow-hidden">
                <div className="p-6 border-b border-[var(--border-color)] flex items-center justify-between">
                    <h4 className="font-bold text-lg text-[var(--text-primary)] flex items-center">
                        <Database className="mr-2 text-brand-400" size={20} />
                        Sunucu Entegrasyon Durumu
                    </h4>
                    <span className="bg-emerald-500/20 text-emerald-400 text-xs px-2 py-1 rounded-md font-medium flex items-center">
                        <ShieldCheck size={14} className="mr-1" /> Firebase Aktif
                    </span>
                </div>

                <div className="p-6 space-y-6">
                    <div className="bg-white/5 border border-emerald-500/20 rounded-xl p-5">
                        <div className="flex items-start mb-4">
                            <Server className="text-emerald-400 mt-1 mr-3 flex-shrink-0" size={20} />
                            <div>
                                <label className="block font-medium text-[var(--text-primary)] mb-1">
                                    Bağlantı Sağlıklı
                                </label>
                                <p className="text-sm text-[var(--text-secondary)] mb-3">
                                    Uygulama artık Google Sheets yerine daha hızlı, modern ve anlık çalışan Firebase Cloud Firestore kullanmaktadır. Herhangi bir URL girmeden platform artık bulut özelliklerini doğrudan kullanabilir.
                                </p>
                            </div>
                        </div>
                    </div>
                </div>
            </div>

            <WipeData />
        </div>
    );
};

export default Settings;

import React, { useState, useEffect } from 'react';
import { ShieldAlert, Building2, Plus, Server, Activity, Trash2, Key, Edit2, PauseCircle, PlayCircle, Users, Truck, Check, X, AlertOctagon, LogIn } from 'lucide-react';
import { db } from '../services/firebaseConfig';
import { collection, addDoc, onSnapshot, query, orderBy, deleteDoc, doc, updateDoc, writeBatch, where, getDocs } from 'firebase/firestore';
import { useCompany } from '../context/CompanyContext';

const SuperAdmin = () => {
    const { activeCompanyId, setActiveCompanyId } = useCompany();
    const [companies, setCompanies] = useState([]);;
    const [showForm, setShowForm] = useState(false);
    const [compName, setCompName] = useState('');
    const [compAdmin, setCompAdmin] = useState('');
    const [compPassword, setCompPassword] = useState('');

    const [stats, setStats] = useState({});
    const [editingCompanyId, setEditingCompanyId] = useState(null);
    const [editForm, setEditForm] = useState({ name: '', adminId: '' });

    useEffect(() => {
        const q = query(collection(db, 'companies'), orderBy('createdAt', 'desc'));
        const unsub = onSnapshot(q, (snapshot) => {
            setCompanies(snapshot.docs.map(doc => ({ ...doc.data(), docRefId: doc.id })));
        });

        // Global istatistikleri dinle (Tırlar, Kullanıcılar, Şoförler)
        const unsubTrucks = onSnapshot(collection(db, 'trucks'), (snapshot) => {
            const counts = {};
            snapshot.docs.forEach(d => {
                const cId = d.data().companyId;
                if (cId) counts[cId] = (counts[cId] || 0) + 1;
            });
            setStats(prev => ({ ...prev, trucks: counts }));
        });

        const unsubUsers = onSnapshot(collection(db, 'approved_users'), (snapshot) => {
            const counts = {};
            const driverCounts = {};
            snapshot.docs.forEach(d => {
                const data = d.data();
                const cId = data.companyId;
                if (cId) {
                    counts[cId] = (counts[cId] || 0) + 1;
                    if (data.role === 'şoför' || data.role === 'user') {
                        driverCounts[cId] = (driverCounts[cId] || 0) + 1;
                    }
                }
            });
            setStats(prev => ({ ...prev, users: counts, drivers: driverCounts }));
        });

        return () => { unsub(); unsubTrucks(); unsubUsers(); };
    }, []);

    const handleAddCompany = async (e) => {
        e.preventDefault();
        try {
            const newCompanyId = 'comp_' + Date.now().toString(36);
            await addDoc(collection(db, 'companies'), {
                id: newCompanyId,
                name: compName,
                adminId: compAdmin,
                status: 'active',
                createdAt: new Date().toISOString()
            });

            // Şirket oluşturulunca, hemen o şirketin sahibini "approved_users" içine ekliyoruz
            await addDoc(collection(db, 'approved_users'), {
                username: compAdmin.toLowerCase().trim(),
                password: compPassword,
                role: 'company_admin',
                companyId: newCompanyId,
                createdAt: new Date().toISOString()
            });

            setCompName('');
            setCompAdmin('');
            setCompPassword('');
            setShowForm(false);
        } catch (error) {
            console.error("Şirket eklenirken hata: ", error);
            alert("Şirket oluşturulurken bir hata oluştu.");
        }
    };

    const handleEditSave = async (docRefId) => {
        try {
            await updateDoc(doc(db, 'companies', docRefId), {
                name: editForm.name,
                adminId: editForm.adminId
            });
            setEditingCompanyId(null);
        } catch (error) {
            console.error("Güncelleme hatası: ", error);
        }
    };

    const handleToggleStatus = async (docRefId, currentStatus) => {
        if (window.confirm(`Şirketi ${currentStatus === 'active' ? 'ASKIYA ALMAK' : 'AKTİF ETMEK'} istediğinize emin misiniz?`)) {
            try {
                await updateDoc(doc(db, 'companies', docRefId), {
                    status: currentStatus === 'active' ? 'suspended' : 'active'
                });
            } catch (error) {
                console.error("Durum değiştirme hatası: ", error);
            }
        }
    };

    const handleDeleteCompany = async (company) => {
        const confirmMsg = `DİKKAT! ${company.name} şirketini siliyorsunuz!\n\nBu işlem şirketi ve o şirkete ait TÜM kullanıcıları, araçları ve kayıtları DERİNLEMESİNE silecektir. Bu işlem GERİ ALINAMAZ!\n\nEmin misiniz?`;
        if (window.confirm(confirmMsg)) {
            if (window.confirm("Son kararınız mı? (Veriler tamamen yok edilecek)")) {
                try {
                    // Deep Clean Delete: Önce Şirketi silelim. Opsiyonel: Diğer tabloları da silebilirsiniz.
                    const batch = writeBatch(db);

                    // Şirketin kullanıcılarını sil
                    const uQ = query(collection(db, 'approved_users'), where('companyId', '==', company.id));
                    const uSnap = await getDocs(uQ);
                    uSnap.forEach(d => batch.delete(d.ref));

                    // Şirketin araçlarını sil
                    const tQ = query(collection(db, 'trucks'), where('companyId', '==', company.id));
                    const tSnap = await getDocs(tQ);
                    tSnap.forEach(d => batch.delete(d.ref));

                    // Kendisini sil
                    batch.delete(doc(db, 'companies', company.docRefId));

                    await batch.commit();
                } catch (error) {
                    console.error("Derin silme hatası:", error);
                }
            }
        }
    };

    return (
        <div className="space-y-6 animate-in fade-in duration-500 max-w-6xl mx-auto">
            <div className="glass-panel p-6 border-l-4 border-l-indigo-500 mb-6 flex justify-between items-center">
                <div>
                    <h3 className="text-xl font-bold flex items-center mb-1 text-[var(--text-primary)]">
                        <ShieldAlert className="mr-3 text-indigo-400" size={24} />
                        Super Admin Paneli (SaaS Yönetimi)
                    </h3>
                    <p className="text-[var(--text-secondary)] text-sm">
                        Sistemdeki tüm şirketleri görebilir ve yeni sistem müşterileri oluşturabilirsiniz.
                    </p>
                </div>
                <div className="flex bg-[var(--bg-panel-hover)] rounded-xl border border-[var(--border-color)] p-3 items-center space-x-3">
                    <div className="w-10 h-10 rounded-lg bg-indigo-500/20 flex items-center justify-center text-indigo-400">
                        <Server size={20} />
                    </div>
                    <div>
                        <p className="text-xs text-[var(--text-secondary)] font-medium tracking-wide">TOPLAM MÜŞTERİ</p>
                        <p className="text-lg font-bold text-[var(--text-primary)] leading-none mt-1">{companies.length}</p>
                    </div>
                </div>
            </div>

            <div className="flex justify-between items-center bg-[var(--bg-panel-hover)] p-4 rounded-xl border border-[var(--border-color)] mb-4">
                <div className="text-sm font-medium text-[var(--text-primary)] flex items-center">
                    <Activity size={16} className="text-brand-400 mr-2" />
                    Aktif Müşteri Şirketleri Listesi
                </div>
                <button onClick={() => setShowForm(!showForm)} className="bg-indigo-500 hover:bg-indigo-600 text-[var(--text-primary)] px-4 py-2 rounded-lg text-sm font-medium flex items-center transition-colors shadow-lg shadow-indigo-500/20">
                    <Plus size={16} className="mr-1.5" /> Yeni Müşteri (Şirket) Ekle
                </button>
            </div>

            {showForm && (
                <form onSubmit={handleAddCompany} className="glass-panel p-6 mb-6 grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-5 border border-indigo-500/30">
                    <div>
                        <label className="block text-xs font-medium text-[var(--text-secondary)] mb-1.5">Şirket Adı (Müşteri Ünvanı)</label>
                        <input type="text" required value={compName} onChange={e => setCompName(e.target.value)} className="w-full bg-[var(--bg-panel-hover)] border border-[var(--border-color)] text-[var(--text-primary)] rounded-lg px-4 py-2.5 text-sm focus:border-indigo-500 outline-none transition-colors" placeholder="Örn: X Lojistik A.Ş." />
                    </div>
                    <div>
                        <label className="block text-xs font-medium text-[var(--text-secondary)] mb-1.5">Ana Yönetici (Şirket Sahibinin Kullanıcı Adı)</label>
                        <input type="text" required value={compAdmin} onChange={e => setCompAdmin(e.target.value)} className="w-full bg-[var(--bg-panel-hover)] border border-[var(--border-color)] text-[var(--text-primary)] rounded-lg px-4 py-2.5 text-sm focus:border-indigo-500 outline-none transition-colors" placeholder="Örn: xlojistik_admin" />
                    </div>
                    <div>
                        <label className="block text-xs font-medium text-[var(--text-secondary)] mb-1.5">Yönetici Şifresi (Geçici Şifre)</label>
                        <div className="relative">
                            <Key size={14} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-500" />
                            <input type="text" required value={compPassword} onChange={e => setCompPassword(e.target.value)} className="w-full bg-[var(--bg-panel-hover)] border border-[var(--border-color)] text-[var(--text-primary)] rounded-lg pl-9 pr-4 py-2.5 text-sm focus:border-indigo-500 outline-none transition-colors" placeholder="Örn: xLojistik123" />
                        </div>
                    </div>
                    <div className="flex items-end">
                        <button type="submit" className="w-full bg-indigo-500 text-[var(--text-primary)] hover:bg-indigo-600 px-4 py-2.5 rounded-lg text-sm font-medium transition-colors shadow-lg">
                            Şirketi Sisteme Kaydet
                        </button>
                    </div>
                </form>
            )}

            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-5">
                {companies.map(comp => {
                    const tCount = Math.max(stats.trucks?.[comp.id] || 0, stats.trucks?.[comp.docRefId] || 0);
                    const dCount = Math.max(stats.drivers?.[comp.id] || 0, stats.drivers?.[comp.docRefId] || 0);
                    const isEditing = editingCompanyId === comp.docRefId;

                    return (
                        <div key={comp.id} className={`glass-panel p-6 transition-all group flex flex-col ${comp.status === 'suspended' ? 'border-red-500/30 opacity-80' : 'border-[var(--border-color)] hover:border-indigo-500/50'}`}>
                            <div className="flex justify-between items-start mb-4">
                                <div className={`w-12 h-12 rounded-xl flex items-center justify-center border transition-colors ${comp.status === 'suspended' ? 'bg-red-500/10 border-red-500/20' : 'bg-[var(--bg-panel-hover)] border-[var(--border-color)] group-hover:border-indigo-500/30'}`}>
                                    <Building2 size={24} className={comp.status === 'suspended' ? 'text-red-400' : 'text-indigo-400'} />
                                </div>
                                <div className="flex flex-col items-end gap-2">
                                    <button onClick={() => handleToggleStatus(comp.docRefId, comp.status)} className={`text-[10px] font-bold px-2.5 py-1 rounded-full flex items-center gap-1 transition-colors ${comp.status === 'active' ? 'bg-emerald-500/10 text-emerald-400 hover:bg-emerald-500/20' : 'bg-red-500/10 text-red-400 hover:bg-red-500/20'}`} title={comp.status === 'active' ? 'Şirketi Askıya Al' : 'Ticari Faaliyeti Sürdür'}>
                                        {comp.status === 'active' ? <><Check size={12} /> AKTİF</> : <><AlertOctagon size={12} /> ASKIYA ALINDI</>}
                                    </button>
                                </div>
                            </div>

                            {isEditing ? (
                                <div className="space-y-3 mb-4 flex-1">
                                    <input type="text" value={editForm.name} onChange={e => setEditForm({ ...editForm, name: e.target.value })} className="w-full bg-[var(--bg-panel-hover)] border border-[var(--border-color)] text-[var(--text-primary)] rounded-md px-3 py-1.5 text-sm outline-none focus:border-indigo-500" placeholder="Şirket Adı" />
                                    <input type="text" value={editForm.adminId} onChange={e => setEditForm({ ...editForm, adminId: e.target.value })} className="w-full bg-[var(--bg-panel-hover)] border border-[var(--border-color)] text-[var(--text-primary)] rounded-md px-3 py-1.5 text-sm outline-none focus:border-indigo-500" placeholder="Yönetici Kullanıcı Adı" />
                                    <div className="flex gap-2">
                                        <button onClick={() => handleEditSave(comp.docRefId)} className="flex-1 bg-indigo-500/20 hover:bg-indigo-500/30 text-indigo-400 py-1.5 rounded-md text-xs font-semibold transition border border-indigo-500/30">Kaydet</button>
                                        <button onClick={() => setEditingCompanyId(null)} className="flex-1 bg-slate-700/50 hover:bg-slate-700/80 text-[var(--text-primary)] py-1.5 rounded-md text-xs font-semibold transition border border-slate-600/50">İptal</button>
                                    </div>
                                </div>
                            ) : (
                                <div className="mb-4 flex-1">
                                    <h4 className="text-xl font-bold tracking-tight text-[var(--text-primary)] mb-1.5 truncate" title={comp.name}>{comp.name}</h4>
                                    <p className="text-xs text-[var(--text-secondary)] font-medium flex items-center">
                                        Yönetici: <span className="ml-1 text-[var(--text-primary)] bg-[var(--bg-panel-hover)] px-2 py-0.5 rounded-md">{comp.adminId}</span>
                                    </p>
                                </div>
                            )}

                            {/* Stats */}
                            <div className="flex gap-2 mb-4">
                                <div className="flex-1 bg-[var(--bg-panel-hover)] border border-[var(--border-color)] rounded-lg py-2 flex flex-col items-center justify-center" title="Araç sayısı">
                                    <Truck size={14} className="text-slate-500 mb-1" />
                                    <span className="text-sm font-bold text-[var(--text-primary)] leading-none">{tCount}</span>
                                </div>
                                <div className="flex-1 bg-[var(--bg-panel-hover)] border border-[var(--border-color)] rounded-lg py-2 flex flex-col items-center justify-center" title="Şoför sayısı">
                                    <Users size={14} className="text-slate-500 mb-1" />
                                    <span className="text-sm font-bold text-[var(--text-primary)] leading-none">{dCount}</span>
                                </div>
                            </div>

                            <div className="pt-3 border-t border-[var(--border-color)] flex justify-between items-center mt-auto">
                                <div className="text-[10px] text-slate-500 uppercase tracking-widest font-bold">
                                    ID: {comp.id}
                                </div>
                                <div className="flex gap-1.5 items-center">
                                    <button
                                        onClick={() => {
                                            setActiveCompanyId(comp.id);
                                            localStorage.setItem('tir_current_company', comp.id);
                                        }}
                                        className={`flex items-center gap-1 text-[10px] font-semibold px-2.5 py-1 rounded-full transition-all ${activeCompanyId === comp.id
                                            ? 'bg-brand-500/20 text-brand-400 border border-brand-500/30'
                                            : 'bg-[var(--bg-panel-hover)] text-slate-500 hover:text-indigo-400 hover:bg-indigo-500/10 border border-[var(--border-color)]'
                                            }`}
                                        title="Bu Şirketi Yönet"
                                    >
                                        <LogIn size={10} />
                                        {activeCompanyId === comp.id ? 'AKTİF' : 'Yönet'}
                                    </button>
                                    {(comp.id !== 'inaner_logistics') && (
                                        <>
                                            <button onClick={() => { setEditingCompanyId(comp.docRefId); setEditForm({ name: comp.name, adminId: comp.adminId }); }} className="text-slate-500 hover:text-indigo-400 p-1.5 bg-[var(--bg-panel-hover)] hover:bg-indigo-500/10 rounded-md transition-colors" title="Şirketi Düzenle">
                                                <Edit2 size={13} />
                                            </button>
                                            <button onClick={() => handleDeleteCompany(comp)} className="text-slate-500 hover:text-red-400 p-1.5 bg-[var(--bg-panel-hover)] hover:bg-red-500/10 rounded-md transition-colors" title="Derinlemesine Sil (Cascade Delete)">
                                                <Trash2 size={13} />
                                            </button>
                                        </>
                                    )}
                                </div>
                            </div>
                        </div>
                    );
                })}
            </div>
        </div>
    );
};

export default SuperAdmin;

import React, { useState, useContext, useEffect } from 'react';
import { Plus, Search, MapPin, Truck, Calendar, X, ChevronDown, Check, Trash2, Paperclip, FileText, Eye, Pencil } from 'lucide-react';
import { DataContext } from '../context/DataContext';
import FileUpload from './FileUpload';

const Trips = () => {
    const { trips, addTrip, deleteTrip, editTrip, routes, addRoute, updateRoute, deleteRoute } = useContext(DataContext);
    const [editingTrip, setEditingTrip] = useState(null);
    const [editForm, setEditForm] = useState({});
    const [deleteConfirm, setDeleteConfirm] = useState(null);
    const [viewFiles, setViewFiles] = useState(null); // { title, files }
    const [searchTerm, setSearchTerm] = useState('');
    const [quickTonnage, setQuickTonnage] = useState('');
    const [isModalOpen, setIsModalOpen] = useState(false);
    const [isRouteManagerOpen, setIsRouteManagerOpen] = useState(false);
    const [editingRoute, setEditingRoute] = useState(null);

    // Rota Seçim State'leri
    const [useSavedRoute, setUseSavedRoute] = useState(true);
    const [selectedRouteId, setSelectedRouteId] = useState('');
    const [saveNewRoute, setSaveNewRoute] = useState(false);

    const [formData, setFormData] = useState({
        date: new Date().toISOString().split('T')[0],
        from: '',
        to: '',
        km: '',
        tonnage: '',
        price: '',
        files: []
    });

    // Kayıtlı rota seçildiğinde formu doldur
    useEffect(() => {
        if (useSavedRoute && selectedRouteId) {
            const route = routes.find(r => r.id === parseInt(selectedRouteId));
            if (route) {
                // eslint-disable-next-line
                setFormData(prev => ({
                    ...prev,
                    from: route.from,
                    to: route.to,
                    km: route.km || '',
                    price: route.lastPrice ? String(route.lastPrice) : prev.price
                }));
            }
        }
    }, [selectedRouteId, useSavedRoute, routes]);

    const calculateTotal = (tonnage, price) => {
        return (tonnage * price).toLocaleString('tr-TR', { minimumFractionDigits: 2 });
    };

    const handleQuickAdd = () => {
        const tonnageStr = window.prompt('Tonaj giriniz (Örn: 38.5):');
        if (!tonnageStr) return;
        const tonnageVal = parseFloat(tonnageStr.replace(',', '.'));
        if (isNaN(tonnageVal) || tonnageVal <= 0) {
            alert('Geçerli bir tonaj girmediniz.');
            return;
        }

        const defaultRoute = routes.find(r => r.from === 'Çayırhan' && r.to.includes('Elmadağ'));

        addTrip({
            date: new Date().toISOString().split('T')[0],
            from: 'Çayırhan',
            to: 'Bastaş Elmadağ',
            km: defaultRoute ? defaultRoute.km : 215,
            tonnage: tonnageVal,
            price: 351.40,
            status: 'Fatura Bekliyor'
        });
    };

    const handleManualAdd = (e) => {
        e.preventDefault();

        const kmValue = parseInt(formData.km) || 0;

        // Yeni rotayı kaydetme isteği varsa
        if (!useSavedRoute && saveNewRoute && formData.from && formData.to) {
            addRoute({
                from: formData.from,
                to: formData.to,
                km: kmValue
            });
        }

        addTrip({
            date: formData.date,
            from: formData.from,
            to: formData.to,
            km: kmValue,
            tonnage: parseFloat(formData.tonnage),
            price: parseFloat(formData.price),
            status: 'Fatura Bekliyor',
            files: formData.files
        });

        setIsModalOpen(false);
        resetForm();
    };

    const handleSaveRouteOnly = async () => {
        if (!formData.from || !formData.to) {
            alert("Lütfen en azından Nereden ve Nereye bilgilerini giriniz.");
            return;
        }
        await addRoute({
            from: formData.from,
            to: formData.to,
            km: parseInt(formData.km) || 0
        });
        setSaveNewRoute(false);
    };

    const handleDelete = (id) => {
        deleteTrip(id);
    };

    const resetForm = () => {
        setFormData({
            date: new Date().toISOString().split('T')[0],
            from: '',
            to: '',
            km: '',
            tonnage: '',
            price: '',
            files: []
        });
        setSelectedRouteId('');
        setUseSavedRoute(true);
        setSaveNewRoute(false);
    };

    const filteredTrips = trips.filter(trip =>
        !trip.deleted && (
            trip.from.toLowerCase().includes(searchTerm.toLowerCase()) ||
            trip.to.toLowerCase().includes(searchTerm.toLowerCase()) ||
            trip.date.includes(searchTerm)
        )
    );

    return (
        <div className="space-y-6 animate-in fade-in duration-500 relative pb-ios-nav">

            {/* Üst Kısım / Filtreleme */}
            <div className="glass-panel p-4 flex flex-col md:flex-row justify-between items-center gap-4 mb-2">
                <div className="relative w-full md:w-96 flex-1">
                    <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-[var(--text-secondary)] pointer-events-none" size={16} />
                    <input
                        type="text"
                        placeholder="Sefer ara (Tarih, Güzergah)..."
                        className="w-full glass-input pr-4 py-2"
                        style={{ paddingLeft: '2.5rem' }}
                        value={searchTerm}
                        onChange={(e) => setSearchTerm(e.target.value)}
                    />
                </div>
                <div className="flex flex-col md:flex-row w-full md:w-auto gap-3">
                    <button
                        onClick={handleQuickAdd}
                        className="w-full md:w-auto bg-[var(--bg-panel-hover)] hover:bg-slate-700 text-brand-400 border border-brand-500/30 px-4 py-2 rounded-lg font-medium transition-all shadow-lg shadow-brand-500/10 flex items-center justify-center whitespace-nowrap"
                        title="Çayırhan - Bastaş Elmadağ"
                    >
                        <Truck size={18} className="mr-2" />
                        Hızlı Sefer Ekle
                    </button>
                    <button
                        onClick={() => setIsModalOpen(true)}
                        className="w-full md:w-auto bg-brand-600 hover:bg-brand-500 text-[var(--text-primary)] px-4 py-2 rounded-lg font-medium transition-all shadow-lg shadow-brand-500/20 flex items-center justify-center whitespace-nowrap"
                    >
                        <Plus size={18} className="mr-2" />
                        Manuel Sefer Gir
                    </button>
                </div>
            </div>

            {/* Seferler Tablosu - Masaüstü */}
            <div className="glass-panel overflow-hidden">
                <div className="overflow-x-auto -mx-0 md:mx-0">
                    <table className="w-full text-left border-collapse hidden md:table" style={{ minWidth: '640px' }}>
                        <thead>
                            <tr className="bg-white/5 border-b border-[var(--border-color)] text-[var(--text-secondary)] text-xs uppercase tracking-wide">
                                <th className="p-3 pl-4 font-semibold whitespace-nowrap">Tarih</th>
                                <th className="p-3 font-semibold whitespace-nowrap">Güzergah</th>
                                <th className="p-3 font-semibold text-center whitespace-nowrap">Tonaj</th>
                                <th className="p-3 font-semibold text-right whitespace-nowrap">Toplam</th>
                                <th className="p-3 font-semibold text-center whitespace-nowrap">Durum</th>
                                <th className="p-3 font-semibold text-center whitespace-nowrap w-16"></th>
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-white/5">
                            {filteredTrips.length > 0 ? (
                                filteredTrips.map((trip) => (
                                    <tr key={trip.id} className="hover:bg-white/5 group">
                                        <td className="p-3 pl-4 whitespace-nowrap">
                                            <div className="text-[var(--text-primary)] text-sm font-medium">{new Date(trip.date).toLocaleDateString('tr-TR')}</div>
                                        </td>
                                        <td className="p-3">
                                            <div className="text-sm font-semibold text-[var(--text-primary)] whitespace-nowrap">
                                                {trip.from} <span className="text-brand-400 mx-1">→</span> {trip.to}
                                            </div>
                                            {trip.km > 0 && (
                                                <div className="text-xs text-slate-500 mt-0.5 whitespace-nowrap">{trip.km} km · ₺{trip.price?.toFixed(2)}/ton</div>
                                            )}
                                        </td>
                                        <td className="p-3 text-center whitespace-nowrap">
                                            <span className="text-[var(--text-primary)] font-medium text-sm">{trip.tonnage} t</span>
                                        </td>
                                        <td className="p-3 text-right whitespace-nowrap">
                                            <span className="font-bold text-emerald-400 text-sm">₺{calculateTotal(trip.tonnage, trip.price)}</span>
                                        </td>
                                        <td className="p-3 text-center">
                                            <span className={`px-2.5 py-1 rounded-full text-xs font-medium border whitespace-nowrap ${trip.status === 'Faturalandı' || trip.status === 'Fatura Kesildi'
                                                ? 'bg-emerald-500/10 text-emerald-400 border-emerald-500/20'
                                                : 'bg-amber-500/10 text-amber-400 border-amber-500/20'
                                                }`}>
                                                {trip.status}
                                            </span>
                                        </td>
                                        <td className="p-2 text-center">
                                            <div className="flex items-center justify-center gap-0.5">
                                                {trip.files && trip.files.length > 0 && (
                                                    <button onClick={() => setViewFiles({ title: `${trip.from} → ${trip.to}`, files: trip.files })}
                                                        title={`${trip.files.length} ek`}
                                                        className="p-1.5 rounded-lg text-slate-500 hover:text-brand-400 hover:bg-brand-500/10">
                                                        <Paperclip size={14} />
                                                    </button>
                                                )}
                                                <button onClick={() => { setEditingTrip(trip); setEditForm({ status: trip.status || 'Fatura Bekliyor', tonnage: trip.tonnage, price: trip.price }); }}
                                                    className="p-1.5 rounded-lg text-slate-500 hover:text-brand-400 hover:bg-brand-500/10">
                                                    <Pencil size={14} />
                                                </button>
                                            </div>
                                        </td>
                                    </tr>
                                ))
                            ) : (
                                <tr>
                                    <td colSpan="6" className="p-8 text-center text-slate-500">
                                        <Truck size={32} className="mx-auto mb-3 opacity-30" />
                                        <p className="text-lg font-medium text-[var(--text-secondary)]">Henüz Kayıtlı Sefer Yok</p>
                                        <p className="text-sm mt-1">Sisteme yeni bir sefer eklediğinizde burada listelenecektir.</p>
                                    </td>
                                </tr>
                            )}
                        </tbody>
                    </table>

                    {/* Mobil Kart Görünümü */}
                    <div className="md:hidden flex flex-col gap-3 p-2">
                        {filteredTrips.length > 0 ? (
                            filteredTrips.map((trip) => (
                                <div key={trip.id} className="bg-[var(--bg-panel)] border border-[var(--border-color)] rounded-2xl p-4 shadow-sm relative overflow-hidden">
                                    <div className="flex justify-between items-start mb-3">
                                        <div className="flex-1 pr-2">
                                            <div className="text-xs text-slate-500 mb-1">{new Date(trip.date).toLocaleDateString('tr-TR')}</div>
                                            <div className="font-semibold text-[var(--text-primary)] leading-tight">
                                                {trip.from} <span className="text-brand-400 mx-0.5">→</span> {trip.to}
                                            </div>
                                        </div>
                                        <div className={`px-2 py-1 rounded-full text-[9px] font-bold tracking-wider text-right uppercase mt-1
                                            ${trip.status === 'Faturalandı' || trip.status === 'Fatura Kesildi'
                                                ? 'bg-emerald-500/10 text-emerald-400 border border-emerald-500/20'
                                                : 'bg-amber-500/10 text-amber-400 border border-amber-500/20'}`}>
                                            {trip.status}
                                        </div>
                                    </div>

                                    <div className="grid grid-cols-2 gap-3 mb-4">
                                        <div className="bg-white/5 rounded-xl p-3">
                                            <div className="text-[10px] text-slate-500 uppercase font-semibold mb-1">TONAJ</div>
                                            <div className="text-[var(--text-primary)] font-medium text-sm">{trip.tonnage} t</div>
                                        </div>
                                        <div className="bg-white/5 rounded-xl p-3">
                                            <div className="text-[10px] text-slate-500 uppercase font-semibold mb-1">TOPLAM TUTAR</div>
                                            <div className="text-emerald-400 font-bold text-sm">₺{calculateTotal(trip.tonnage, trip.price)}</div>
                                        </div>
                                    </div>

                                    <div className="flex justify-end gap-2 border-t border-[var(--border-color)] pt-3">
                                        {trip.files && trip.files.length > 0 && (
                                            <button onClick={() => setViewFiles({ title: `${trip.from} → ${trip.to}`, files: trip.files })}
                                                className="p-2 bg-white/5 hover:bg-white/10 rounded-lg text-brand-400 transition-colors mr-auto flex items-center gap-1.5 text-xs font-medium">
                                                <Paperclip size={14} /> {trip.files.length} Ek
                                            </button>
                                        )}
                                        <button onClick={() => { setEditingTrip(trip); setEditForm({ status: trip.status || 'Fatura Bekliyor', tonnage: trip.tonnage, price: trip.price }); }}
                                            className="p-2 bg-white/5 hover:bg-white/10 rounded-lg text-[var(--text-secondary)] transition-colors">
                                            <Pencil size={18} />
                                        </button>
                                        <button onClick={() => handleDelete(trip.id)}
                                            className="p-2 bg-white/5 hover:bg-red-500/20 rounded-lg text-[var(--text-secondary)] hover:text-red-400 transition-colors">
                                            <Trash2 size={18} />
                                        </button>
                                    </div>
                                </div>
                            ))
                        ) : (
                            <div className="p-8 text-center text-slate-500">
                                <Truck size={32} className="mx-auto mb-3 opacity-30" />
                                <p className="text-lg font-medium text-[var(--text-secondary)]">Henüz Kayıtlı Sefer Yok</p>
                            </div>
                        )}
                    </div>
                </div>
            </div>


            {/* Düzenle Modal */}
            {editingTrip && (
                <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-[var(--bg-panel)] backdrop-blur-sm">
                    <div className="glass-panel w-full max-w-sm p-6 relative animate-in zoom-in-95 duration-200">
                        <button onClick={() => setEditingTrip(null)} className="absolute top-4 right-4 text-[var(--text-secondary)] hover:text-[var(--text-primary)]"><X size={20} /></button>
                        <h3 className="text-lg font-bold text-[var(--text-primary)] mb-4 flex items-center gap-2"><Pencil size={16} className="text-brand-400" /> Seferi Düzenle</h3>
                        <div className="space-y-3">
                            <div>
                                <label className="block text-xs text-[var(--text-secondary)] mb-1">Tonaj</label>
                                <input type="number" step="0.01" className="w-full glass-input px-3 py-2 text-sm"
                                    value={editForm.tonnage} onChange={e => setEditForm({ ...editForm, tonnage: parseFloat(e.target.value) })} />
                            </div>
                            <div>
                                <label className="block text-xs text-[var(--text-secondary)] mb-1">Birim Fiyat (TL)</label>
                                <input type="number" step="0.01" className="w-full glass-input px-3 py-2 text-sm"
                                    value={editForm.price} onChange={e => setEditForm({ ...editForm, price: parseFloat(e.target.value) })} />
                            </div>
                            <div>
                                <label className="block text-xs text-[var(--text-secondary)] mb-1">Durum</label>
                                <select className="w-full glass-input px-3 py-2 text-sm bg-[var(--bg-panel)]"
                                    value={editForm.status} onChange={e => setEditForm({ ...editForm, status: e.target.value })}>
                                    <option value="Fatura Bekliyor">Fatura Bekliyor</option>
                                    <option value="Fatura Kesildi">Fatura Kesildi</option>
                                    <option value="Faturalandı">Faturalandı</option>
                                </select>
                            </div>
                            <button onClick={async () => {
                                if (editTrip) await editTrip(editingTrip.id, editForm);
                                setEditingTrip(null);
                            }} className="w-full bg-brand-600 hover:bg-brand-500 text-[var(--text-primary)] py-2.5 rounded-lg font-medium transition-all mt-2">
                                Kaydet
                            </button>
                            <button onClick={() => { handleDelete(editingTrip.id); setEditingTrip(null); }}
                                className="w-full flex items-center justify-center gap-2 text-red-400 hover:text-red-300 border border-red-500/20 hover:border-red-500/40 hover:bg-red-500/5 py-2.5 rounded-lg text-sm font-medium transition-all">
                                <Trash2 size={14} /> Bu Seferi Sil
                            </button>
                        </div>
                    </div>
                </div>
            )}

            {/* Manuel Ekle Modal */}
            {isModalOpen && (
                <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-[var(--bg-panel)] backdrop-blur-sm">
                    <div className="glass-panel w-full max-w-lg p-6 relative animate-in zoom-in-95 duration-200 border-brand-500/30">
                        <button
                            onClick={() => setIsModalOpen(false)}
                            className="absolute top-4 right-4 text-[var(--text-secondary)] hover:text-[var(--text-primary)]"
                        >
                            <X size={20} />
                        </button>

                        <h3 className="text-xl font-bold text-[var(--text-primary)] mb-6 flex items-center">
                            <MapPin className="mr-2 text-brand-500" /> Yeni Sefer / Rota
                        </h3>

                        <form onSubmit={handleManualAdd} className="space-y-5">
                            <div>
                                <label className="block text-sm font-medium text-[var(--text-primary)] mb-1">Tarih</label>
                                <input
                                    type="date"
                                    required
                                    className="w-full glass-input px-4 py-2"
                                    value={formData.date}
                                    onChange={(e) => setFormData({ ...formData, date: e.target.value })}
                                />
                            </div>

                            {/* Rota Seçim Alanı */}
                            <div className="p-4 bg-white/5 border border-[var(--border-color)] rounded-xl space-y-4">
                                <div className="flex items-center justify-between mb-2">
                                    <label className="text-sm font-bold text-brand-300">Güzergah Belirleme</label>
                                    <div className="flex items-center space-x-2 bg-[var(--bg-panel-hover)] p-1 rounded-lg">
                                        <button
                                            type="button"
                                            className={`px-3 py-1 text-xs font-medium rounded ${useSavedRoute ? 'bg-brand-500 text-[var(--text-primary)]' : 'text-[var(--text-secondary)]'}`}
                                            onClick={() => setUseSavedRoute(true)}
                                        >
                                            Kayıtlı Rota
                                        </button>
                                        <button
                                            type="button"
                                            className={`px-3 py-1 text-xs font-medium rounded ${!useSavedRoute ? 'bg-brand-500 text-[var(--text-primary)]' : 'text-[var(--text-secondary)]'}`}
                                            onClick={() => {
                                                setUseSavedRoute(false);
                                                setSelectedRouteId('');
                                                setFormData(f => ({ ...f, from: '', to: '', km: '' }));
                                            }}
                                        >
                                            Yeni Rota
                                        </button>
                                        <div className="w-[1px] h-3 bg-white/10 mx-1"></div>
                                        <button
                                            type="button"
                                            className="px-2 py-1 text-[10px] font-bold text-brand-400 hover:text-brand-300 uppercase tracking-tighter"
                                            onClick={() => setIsRouteManagerOpen(true)}
                                        >
                                            Yönet
                                        </button>
                                    </div>
                                </div>

                                {useSavedRoute ? (
                                    <div>
                                        <div className="relative">
                                            <select
                                                className="w-full glass-input px-4 py-2 appearance-none bg-[var(--bg-panel-hover)] pr-10"
                                                value={selectedRouteId}
                                                onChange={(e) => setSelectedRouteId(e.target.value)}
                                                required={useSavedRoute}
                                            >
                                                <option value="">Rotalarımdan Seçin...</option>
                                                {routes.map(r => (
                                                    <option key={r.id} value={r.id}>
                                                        {r.from} ➔ {r.to} ({r.km} km)
                                                    </option>
                                                ))}
                                            </select>
                                            <ChevronDown size={16} className="absolute right-3 top-1/2 -translate-y-1/2 text-[var(--text-secondary)] pointer-events-none" />
                                        </div>
                                    </div>
                                ) : (
                                    <div className="space-y-4 animate-in fade-in slide-in-from-top-2 duration-300">
                                        <div className="grid grid-cols-2 gap-4">
                                            <div>
                                                <label className="block text-xs text-[var(--text-secondary)] mb-1">Yükleme (Nereden)</label>
                                                <input
                                                    type="text"
                                                    required={!useSavedRoute}
                                                    placeholder="Örn: Ankara"
                                                    className="w-full glass-input px-3 py-2 text-sm"
                                                    value={formData.from}
                                                    onChange={(e) => setFormData({ ...formData, from: e.target.value })}
                                                />
                                            </div>
                                            <div>
                                                <label className="block text-xs text-[var(--text-secondary)] mb-1">Boşaltma (Nereye)</label>
                                                <input
                                                    type="text"
                                                    required={!useSavedRoute}
                                                    placeholder="Örn: İstanbul"
                                                    className="w-full glass-input px-3 py-2 text-sm"
                                                    value={formData.to}
                                                    onChange={(e) => setFormData({ ...formData, to: e.target.value })}
                                                />
                                            </div>
                                        </div>
                                        <div>
                                            <label className="block text-xs text-[var(--text-secondary)] mb-1">Mesafe (KM)</label>
                                            <div className="flex gap-4 items-center">
                                                <input
                                                    type="number"
                                                    required={!useSavedRoute}
                                                    placeholder="Örn: 450"
                                                    className="w-full glass-input px-3 py-2 text-sm"
                                                    value={formData.km}
                                                    onChange={(e) => setFormData({ ...formData, km: e.target.value })}
                                                />
                                                <div className="flex items-center gap-2">
                                                    <label className="flex items-center space-x-2 text-sm text-[var(--text-primary)] cursor-pointer whitespace-nowrap">
                                                        <div className={`w-5 h-5 rounded border flex items-center justify-center transition-colors ${saveNewRoute ? 'bg-brand-500 border-brand-500' : 'border-slate-500'}`}>
                                                            {saveNewRoute && <Check size={14} className="text-[var(--text-primary)]" />}
                                                        </div>
                                                        <input
                                                            type="checkbox"
                                                            className="hidden"
                                                            checked={saveNewRoute}
                                                            onChange={(e) => setSaveNewRoute(e.target.checked)}
                                                        />
                                                        <span>Hafızaya Al</span>
                                                    </label>
                                                    {formData.from && formData.to && (
                                                        <button
                                                            type="button"
                                                            onClick={handleSaveRouteOnly}
                                                            className="px-2 py-1 bg-brand-500/20 text-brand-400 text-[10px] font-bold rounded border border-brand-500/30 hover:bg-brand-500/30 transition-all uppercase"
                                                        >
                                                            Şimdi Kaydet
                                                        </button>
                                                    )}
                                                </div>
                                            </div>
                                        </div>
                                    </div>
                                )}
                            </div>

                            <div className="grid grid-cols-2 gap-4 pt-2">
                                <div>
                                    <label className="block text-sm font-medium text-[var(--text-primary)] mb-1">Tonaj</label>
                                    <input
                                        type="number"
                                        step="0.01"
                                        required
                                        placeholder="Örn: 24.5"
                                        className="w-full glass-input px-4 py-2"
                                        value={formData.tonnage}
                                        onChange={(e) => setFormData({ ...formData, tonnage: e.target.value })}
                                    />
                                </div>
                                <div>
                                    <label className="block text-sm font-medium text-[var(--text-primary)] mb-1">Birim Fiyat (TL)</label>
                                    <input
                                        type="number"
                                        step="0.01"
                                        required
                                        placeholder="Örn: 450"
                                        className="w-full glass-input px-4 py-2"
                                        value={formData.price}
                                        onChange={(e) => setFormData({ ...formData, price: e.target.value })}
                                    />
                                </div>
                            </div>

                            <div>
                                <label className="block text-sm font-medium text-[var(--text-primary)] mb-2">📎 İrsaliye / Belge Ekle</label>
                                <FileUpload files={formData.files} onChange={files => setFormData({ ...formData, files })} />
                            </div>

                            <button
                                type="submit"
                                className="w-full bg-brand-600 hover:bg-brand-500 text-[var(--text-primary)] px-4 py-3 rounded-lg font-medium transition-all shadow-lg mt-2"
                            >
                                Seferi Kaydet
                            </button>
                        </form>
                    </div>
                </div>
            )}

            {/* Rota Yönetimi Modal */}
            {isRouteManagerOpen && (
                <div className="fixed inset-0 z-[60] flex items-center justify-center p-4 bg-[var(--bg-panel)] backdrop-blur-md">
                    <div className="glass-panel w-full max-w-md p-6 relative animate-in zoom-in-95 duration-200 border-brand-500/30">
                        <button onClick={() => setIsRouteManagerOpen(false)} className="absolute top-4 right-4 text-[var(--text-secondary)] hover:text-[var(--text-primary)]"><X size={20} /></button>
                        <h3 className="text-xl font-bold text-[var(--text-primary)] mb-6 flex items-center"><MapPin className="mr-2 text-brand-500" /> Rota Yönetimi</h3>

                        <div className="space-y-4 max-h-[60vh] overflow-y-auto pr-2 custom-scrollbar">
                            {routes.map(route => (
                                <div key={route.id} className="p-3 bg-white/5 border border-[var(--border-color)] rounded-xl">
                                    {editingRoute === route.id ? (
                                        <div className="space-y-3">
                                            <div className="grid grid-cols-2 gap-2">
                                                <input className="glass-input px-2 py-1 text-xs" value={route.from} onChange={e => updateRoute(route.id, { from: e.target.value })} />
                                                <input className="glass-input px-2 py-1 text-xs" value={route.to} onChange={e => updateRoute(route.id, { to: e.target.value })} />
                                            </div>
                                            <div className="flex gap-2">
                                                <input type="number" className="glass-input px-2 py-1 text-xs w-20" value={route.km} onChange={e => updateRoute(route.id, { km: parseInt(e.target.value) || 0 })} />
                                                <button onClick={() => setEditingRoute(null)} className="ml-auto bg-brand-600 text-[var(--text-primary)] px-3 py-1 rounded text-xs">Tamam</button>
                                            </div>
                                        </div>
                                    ) : (
                                        <div className="flex items-center justify-between">
                                            <div>
                                                <p className="text-sm font-bold text-[var(--text-primary)]">{route.from} ➔ {route.to}</p>
                                                <p className="text-xs text-slate-500">{route.km} km {route.lastPrice ? `· ₺${route.lastPrice}` : ''}</p>
                                            </div>
                                            <div className="flex gap-1">
                                                <button onClick={() => setEditingRoute(route.id)} className="p-1.5 text-[var(--text-secondary)] hover:text-brand-400"><Pencil size={14} /></button>
                                                <button onClick={() => deleteRoute(route.id)} className="p-1.5 text-[var(--text-secondary)] hover:text-red-400"><Trash2 size={14} /></button>
                                            </div>
                                        </div>
                                    )}
                                </div>
                            ))}
                            {routes.length === 0 && <p className="text-center text-slate-500 text-sm py-4">Kayıtlı rota bulunamadı.</p>}
                        </div>

                        <button
                            onClick={() => setIsRouteManagerOpen(false)}
                            className="w-full bg-[var(--bg-panel-hover)] hover:bg-slate-700 text-[var(--text-primary)] py-3 rounded-lg font-medium transition-all mt-6 border border-[var(--border-color)]"
                        >
                            Kapat
                        </button>
                    </div>
                </div>
            )}

            {/* Dosya Görüntüleyici Modal */}
            {viewFiles && (
                <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-[var(--bg-panel)] backdrop-blur-sm" onClick={() => setViewFiles(null)}>
                    <div className="glass-panel w-full max-w-lg p-5 relative animate-in zoom-in-95 duration-200 max-h-[80vh] overflow-y-auto"
                        onClick={e => e.stopPropagation()}>
                        <button onClick={() => setViewFiles(null)} className="absolute top-4 right-4 text-[var(--text-secondary)] hover:text-[var(--text-primary)]"><X size={20} /></button>
                        <h3 className="font-bold text-[var(--text-primary)] mb-1 pr-8">📎 Ekler</h3>
                        <p className="text-xs text-slate-500 mb-4">{viewFiles.title}</p>
                        <div className="space-y-3">
                            {viewFiles.files.map((f, i) => (
                                <div key={i} className="bg-white/5 rounded-xl p-3 border border-[var(--border-color)]">
                                    {f.type && f.type.startsWith('image/') ? (
                                        <a href={f.data} target="_blank" rel="noreferrer">
                                            <img src={f.data} alt={f.name} className="w-full rounded-lg max-h-64 object-contain bg-[var(--bg-panel)] cursor-zoom-in hover:opacity-90 transition" />
                                        </a>
                                    ) : (
                                        <a href={f.data} download={f.name}
                                            className="flex items-center gap-3 hover:opacity-80 transition-opacity">
                                            <FileText size={24} className="text-brand-400 flex-shrink-0" />
                                            <div>
                                                <p className="text-sm font-medium text-[var(--text-primary)]">{f.name}</p>
                                                <p className="text-xs text-slate-500">İndirmek için tıklayın</p>
                                            </div>
                                        </a>
                                    )}
                                    <p className="text-xs text-slate-600 mt-1.5">{f.name}</p>
                                </div>
                            ))}
                        </div>
                    </div>
                </div>
            )}

        </div>
    );
};

export default Trips;

import React, { createContext, useState, useEffect, useContext } from 'react';
import { db } from '../services/firebaseConfig';
import { collection, query, where, onSnapshot } from 'firebase/firestore';

export const CompanyContext = createContext();

export const CompanyProvider = ({ children }) => {
    // Session bazlı dinamik başlangıç firması
    const [activeCompanyId, setActiveCompanyId] = useState(() => {
        return localStorage.getItem('tir_current_company') || 'inaner_logistics';
    });
    const [companyData, setCompanyData] = useState(null);
    const [companies, setCompanies] = useState([]);

    useEffect(() => {
        const unsub = onSnapshot(collection(db, 'companies'), (snapshot) => {
            setCompanies(snapshot.docs.map(doc => ({ ...doc.data(), docRefId: doc.id })));
        });
        return () => unsub();
    }, []);

    useEffect(() => {
        if (!activeCompanyId) return;
        const unsub = onSnapshot(query(collection(db, 'companies'), where('id', '==', activeCompanyId)), (snapshot) => {
            if (!snapshot.empty) {
                setCompanyData(snapshot.docs[0].data());
            }
        });
        return () => unsub();
    }, [activeCompanyId]);

    return (
        <CompanyContext.Provider value={{ activeCompanyId, setActiveCompanyId, companyData, companies }}>
            {children}
        </CompanyContext.Provider>
    );
};

export const useCompany = () => useContext(CompanyContext);

